-- FIN62 RELEASE CANDIDATE: NOT APPROVED FOR LIVE APPLICATION.
-- Generated by scripts/generate-shift-financial-upgrade.cjs. UTF-8/LF, no BOM.
-- Schema/routine preparation only: no historical backfill or rollout approval.
-- Existing sales, stock, amounts, PINs and permission grants are not rewritten.
-- Future writes gain private version/provenance metadata; exact owner review is
-- required before this file is applied to the named production project.
BEGIN;
SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='60s';
DO $financial_preflight$
BEGIN
 IF EXISTS(SELECT 1 FROM pg_namespace WHERE nspname IN(
  'fin62_preparation','fin62_evidence_preparation','fin62_cloud_preparation',
  'fin62_version_preparation','fin62_origin_preparation','fin62_action_preparation',
  'fin62_history_preparation','fin62_web_preparation','fin62_live_preparation',
  'fin62_admin_preparation','fin62_rollout_preparation')) THEN
  RAISE EXCEPTION 'FIN62_EXISTING_METADATA_REQUIRES_REVIEW';
 END IF;
END $financial_preflight$;

-- Source: scripts/preparation/shift-financial-math-postgres.sql
-- Canonical source SHA256: FA99870D7E1205ACFF2608E99681D20A464C2D124BBE6BFF3E4F9C6A52C88E2A
-- FIN62 isolated canonical-v2 math preparation ONLY. No RPC, admission, author
-- verification, completeness claim, runtime wiring or business-table reads.
-- Approved NEW-action rule: exact decimals; final 2dp ties away from zero.
-- Native legacy-v1 evaluation remains explicitly unverified: SQL Server/JS
-- expression scales differ. Never recalculate accepted history through v2.
CREATE SCHEMA IF NOT EXISTS fin62_preparation;
CREATE OR REPLACE FUNCTION fin62_preparation.math_label_length(input text)
RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $fn$
 SELECT coalesce(sum(CASE WHEN ascii(character)>65535 THEN 2 ELSE 1 END),0)::integer FROM regexp_split_to_table(input,'') character;
$fn$;
CREATE OR REPLACE FUNCTION fin62_preparation.math_decimal_text(input text)
RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $fn$
DECLARE token text; exponent_text text; value numeric; coefficient text;
BEGIN
 token:=btrim(input,E' \t\n\r\f'||chr(11));
 IF token IS NULL OR length(token)>128 OR token !~ '^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$' THEN RAISE EXCEPTION 'FIN62_NUMERIC_UNSUPPORTED'; END IF;
 exponent_text:=substring(token FROM '[eE]([+-]?[0-9]+)$');
 IF exponent_text IS NOT NULL AND abs(exponent_text::numeric)>38 THEN RAISE EXCEPTION 'FIN62_NUMERIC_UNSUPPORTED'; END IF;
 value:=trim_scale(token::numeric);
 coefficient:=ltrim(replace(abs(value)::text,'.',''),'0');
 IF scale(value)>38 OR length(coefficient)>76 THEN RAISE EXCEPTION 'FIN62_NUMERIC_UNSUPPORTED'; END IF;
 RETURN value;
END $fn$;
CREATE OR REPLACE FUNCTION fin62_preparation.math_unique_json(input json,depth integer DEFAULT 0)
RETURNS void LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,fin62_preparation AS $fn$
DECLARE child json;
BEGIN
 IF depth>64 THEN RAISE EXCEPTION 'FIN62_BASIS_LIMIT'; END IF;
 IF json_typeof(input)='object' THEN
  IF EXISTS(SELECT 1 FROM json_each(input) GROUP BY key COLLATE "C" HAVING count(*)>1) THEN RAISE EXCEPTION 'FIN62_DUPLICATE_JSON_KEY'; END IF;
  FOR child IN SELECT value FROM json_each(input) LOOP PERFORM math_unique_json(child,depth+1); END LOOP;
 ELSIF json_typeof(input)='array' THEN
  FOR child IN SELECT value FROM json_array_elements(input) LOOP PERFORM math_unique_json(child,depth+1); END LOOP;
 END IF;
END $fn$;
CREATE OR REPLACE FUNCTION fin62_preparation.math_method(input text)
RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $fn$
DECLARE method text; trimmed text;
BEGIN
 method:=translate(coalesce(input,''),'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz');
 trimmed:=btrim(method,E' \t\n\r\f'||chr(11));
 IF method IS DISTINCT FROM trimmed AND trimmed COLLATE "C" IN('cash','card','wallet','bank_transfer','transfer','qr','online','ewallet') THEN RAISE EXCEPTION 'FIN62_METHOD_CONTEXT_REQUIRED'; END IF;
 RETURN method;
END $fn$;
CREATE OR REPLACE FUNCTION fin62_preparation.validate_financial_math(basis jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,fin62_preparation AS $fn$
DECLARE canonical boolean; opening numeric; cash_total numeric:=0;card_total numeric:=0;digital_total numeric:=0;
 input jsonb;identifier text; total numeric; paid numeric; cash numeric; card numeric; digital numeric;
 method text; raw text; parsed json; payment json; amount_value json; method_value json; amount numeric;
 split boolean; refunded boolean; net_cash numeric; expected jsonb; failure text;
BEGIN
 IF basis IS NULL OR jsonb_typeof(basis)<>'object' THEN RAISE EXCEPTION 'FIN62_BASIS_LIMIT'; END IF;
 IF jsonb_typeof(basis->'prototypeVersion') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'FIN62_LEGACY_CONTEXT_REQUIRED'; END IF;
 IF basis->>'prototypeVersion'='1' AND basis->>'formula'='sqlserver-current-sales-net-refund-raw-v1' THEN RAISE EXCEPTION 'FIN62_LEGACY_NATIVE_MATH_UNVERIFIED'; END IF;
 IF basis->>'prototypeVersion'='2' AND basis->>'formula'='canonical-exact-decimal-v2' THEN canonical:=true;
 ELSIF basis->>'prototypeVersion'='1' AND basis->>'formula'='current-sales-net-refund-v1' THEN canonical:=false;
 ELSE RAISE EXCEPTION 'FIN62_LEGACY_CONTEXT_REQUIRED'; END IF;
 IF jsonb_typeof(basis->'inputs') IS DISTINCT FROM 'array' OR jsonb_array_length(basis->'inputs')>20000 THEN RAISE EXCEPTION 'FIN62_BASIS_LIMIT'; END IF;
 IF jsonb_typeof(basis->'branchId') IS DISTINCT FROM 'string' OR nullif(basis->>'branchId','') IS NULL OR math_label_length(basis->>'branchId')>128 OR
  coalesce(basis->>'shiftId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'FIN62_INPUT_INVALID'; END IF;
 IF NOT basis?'openingFloat' OR jsonb_typeof(basis->'openingFloat') NOT IN('string','null') THEN RAISE EXCEPTION 'FIN62_INPUT_INVALID'; END IF;
 opening:=CASE WHEN basis->'openingFloat'='null'::jsonb THEN 0 ELSE math_decimal_text(basis->>'openingFloat') END;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(basis->'inputs') GROUP BY (value->>'id') COLLATE "C" HAVING count(*)>1) THEN RAISE EXCEPTION 'FIN62_INPUT_INVALID'; END IF;
 FOR input IN SELECT value FROM jsonb_array_elements(basis->'inputs') LOOP
  identifier:=input->>'id';
  IF jsonb_typeof(input)<>'object' OR jsonb_typeof(input->'branchId') IS DISTINCT FROM 'string' OR jsonb_typeof(input->'shiftId') IS DISTINCT FROM 'string' OR
   identifier IS NULL OR identifier !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR
   input->>'branchId' IS DISTINCT FROM basis->>'branchId' OR input->>'shiftId' IS DISTINCT FROM basis->>'shiftId'
  THEN RAISE EXCEPTION 'FIN62_INPUT_INVALID'; END IF;
  IF NOT input?'totalAmount' OR NOT input?'paymentType' OR NOT input?'rowVersion' OR
   jsonb_typeof(input->'totalAmount') NOT IN('string','null') OR jsonb_typeof(input->'paymentType') NOT IN('string','null') OR
   jsonb_typeof(input->'rowVersion') NOT IN('string','null') THEN RAISE EXCEPTION 'FIN62_INPUT_INVALID'; END IF;
  IF canonical THEN
   IF NOT input?'paymentsJson' OR NOT input?'isRefunded' OR jsonb_typeof(input->'isRefunded') NOT IN('boolean','null') OR jsonb_typeof(input->'paymentsJson') NOT IN('string','null') THEN RAISE EXCEPTION 'FIN62_INPUT_INVALID'; END IF;
   refunded:=coalesce((input->>'isRefunded')::boolean,false);
   -- Retain all raw refunded inputs, without parsing payments the established
   -- formula excludes. This does not omit a row from the supplied snapshot.
   IF refunded THEN CONTINUE; END IF;
   raw:=input->>'paymentsJson';parsed:=NULL;
   IF raw IS NOT NULL AND raw<>'' THEN
    BEGIN parsed:=raw::json; EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'FIN62_PAYMENTS_UNVERIFIED'; END;
    PERFORM math_unique_json(parsed);
   END IF;
   split:=CASE WHEN json_typeof(parsed)='array' THEN json_array_length(parsed)>0 ELSE false END;
  ELSE
   IF NOT input?'payments' OR NOT input?'refunded' OR jsonb_typeof(input->'refunded') NOT IN('boolean','null') THEN RAISE EXCEPTION 'FIN62_INPUT_INVALID'; END IF;
   refunded:=coalesce((input->>'refunded')::boolean,false);IF refunded THEN CONTINUE;END IF;
   parsed:=(input->'payments')::json;
   split:=CASE WHEN json_typeof(parsed)='array' THEN json_array_length(parsed)>0 ELSE false END;
  END IF;
  total:=CASE WHEN input->'totalAmount'='null'::jsonb THEN NULL ELSE math_decimal_text(input->>'totalAmount') END;
  paid:=0;cash:=0;card:=0;digital:=0;
  IF split THEN
   FOR payment IN SELECT value FROM json_array_elements(parsed) LOOP
    IF canonical AND json_typeof(payment) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'FIN62_INPUT_INVALID'; END IF;
    amount_value:=NULL;method_value:=NULL;
    IF json_typeof(payment)='object' THEN
     SELECT value INTO amount_value FROM json_each(payment) WHERE key='amount' LIMIT 1;
     SELECT value INTO method_value FROM json_each(payment) WHERE key='method' LIMIT 1;
    END IF;
    amount:=0;
    IF amount_value IS NOT NULL AND json_typeof(amount_value)<>'null' THEN
     IF json_typeof(amount_value) NOT IN('number','string') THEN RAISE EXCEPTION 'FIN62_NUMERIC_UNSUPPORTED'; END IF;
     amount:=math_decimal_text(amount_value#>>'{}');
    END IF;
    IF canonical AND method_value IS NOT NULL AND json_typeof(method_value) NOT IN('string','null') THEN RAISE EXCEPTION 'FIN62_INPUT_INVALID'; END IF;
    method:=CASE WHEN canonical THEN math_method(method_value#>>'{}') ELSE lower(coalesce(method_value#>>'{}','')) END;paid:=paid+amount;
    IF method COLLATE "C"='cash' THEN cash:=cash+amount;
    ELSIF method COLLATE "C"='card' THEN card:=card+amount;
    ELSIF method COLLATE "C" IN('wallet','bank_transfer','transfer','qr','online','ewallet') THEN digital:=digital+amount; END IF;
   END LOOP;
   net_cash:=CASE WHEN cash>0 THEN greatest(0,cash-greatest(0,paid-coalesce(total,0))) ELSE cash END;
  ELSE
   method:=CASE WHEN canonical THEN math_method(input->>'paymentType') ELSE lower(coalesce(input->>'paymentType','')) END;
   net_cash:=CASE WHEN method COLLATE "C"='cash' THEN coalesce(total,0) ELSE 0 END;
   card:=CASE WHEN method COLLATE "C"='card' THEN coalesce(total,0) ELSE 0 END;
   digital:=CASE WHEN method COLLATE "C" IN('wallet','bank_transfer','transfer','qr','online','ewallet') THEN coalesce(total,0) ELSE 0 END;
  END IF;
  cash_total:=cash_total+net_cash;card_total:=card_total+card;digital_total:=digital_total+digital;
 END LOOP;
 expected:=jsonb_build_object('cash',round(opening+cash_total,2)::text,'card',round(card_total,2)::text,'digital',round(digital_total,2)::text);
 -- Validate output bounds, never silently truncate a large aggregate.
 PERFORM math_decimal_text(expected->>'cash');PERFORM math_decimal_text(expected->>'card');PERFORM math_decimal_text(expected->>'digital');
 RETURN jsonb_build_object('status','computed','expected',expected,'formula',basis->>'formula');
EXCEPTION WHEN OTHERS THEN
 GET STACKED DIAGNOSTICS failure=MESSAGE_TEXT;
 RETURN jsonb_build_object('status','unsupported','code',CASE WHEN failure ~ '^FIN62_[A-Z_]+$' THEN failure ELSE 'FIN62_MALFORMED_OR_UNSUPPORTED' END);
END $fn$;
-- Raw entry point: jsonb alone has already lost duplicate keys, exact version
-- spelling and original byte length. Future admission must not bypass this
-- layer merely because the internal arithmetic accepts parsed jsonb.
CREATE OR REPLACE FUNCTION fin62_preparation.validate_financial_math_text(raw_basis text)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,fin62_preparation AS $fn$
DECLARE parsed json; version_value json; failure text;
BEGIN
 IF raw_basis IS NULL OR octet_length(raw_basis)>6*1024*1024 THEN RAISE EXCEPTION 'FIN62_BASIS_LIMIT'; END IF;
 parsed:=raw_basis::json;
 IF json_typeof(parsed)<>'object' THEN RAISE EXCEPTION 'FIN62_INPUT_INVALID'; END IF;
 PERFORM math_unique_json(parsed);
 SELECT value INTO version_value FROM json_each(parsed) WHERE key='prototypeVersion' LIMIT 1;
 IF json_typeof(version_value) IS DISTINCT FROM 'number' OR version_value::text NOT IN('1','2') THEN RAISE EXCEPTION 'FIN62_LEGACY_CONTEXT_REQUIRED'; END IF;
 RETURN validate_financial_math(parsed::jsonb);
EXCEPTION WHEN OTHERS THEN
 GET STACKED DIAGNOSTICS failure=MESSAGE_TEXT;
 RETURN jsonb_build_object('status','unsupported','code',CASE WHEN failure ~ '^FIN62_[A-Z_]+$' THEN failure ELSE 'FIN62_MALFORMED_OR_UNSUPPORTED' END);
END $fn$;
REVOKE ALL ON FUNCTION fin62_preparation.math_label_length(text),fin62_preparation.math_decimal_text(text),fin62_preparation.math_unique_json(json,integer),
 fin62_preparation.math_method(text),fin62_preparation.validate_financial_math(jsonb),fin62_preparation.validate_financial_math_text(text) FROM PUBLIC;

-- Source: scripts/preparation/shift-financial-cloud-receipts.sql
-- Canonical source SHA256: 989768764B06B19FD5B302C129761FD2FFF7714165734150D1E280B26D341A61
-- FIN62 PREPARATION ONLY / NOT FINAL / DO NOT DEPLOY OR EXECUTE ON OPERATOR DB.
-- Baseline foundation only. No financial-operation issuer or successful admission.
-- Raw versioned inputs only: no expected totals or final math are computed here.
-- This SQL preserves existing validators and grants. The hosting layer must first
-- verify device proof and authorized user read scope; SQL read scope alone does
-- not implement a Management user's authorized branch subset.
-- Shared order is ONLY helper execution order within one transaction; it is
-- never a global commit clock. Controlled ordered helper calls are required.
CREATE SCHEMA IF NOT EXISTS fin62_evidence_preparation;
REVOKE ALL ON SCHEMA fin62_evidence_preparation FROM PUBLIC,anon,authenticated,service_role;
CREATE SEQUENCE IF NOT EXISTS fin62_evidence_preparation.helper_order AS bigint;
REVOKE ALL ON SEQUENCE fin62_evidence_preparation.helper_order FROM PUBLIC,anon,authenticated,service_role;
CREATE SCHEMA fin62_cloud_preparation;
REVOKE ALL ON SCHEMA fin62_cloud_preparation FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE fin62_cloud_preparation.bases(
 id uuid PRIMARY KEY,organization_id text NOT NULL,branch_id text NOT NULL,
 terminal_id text NOT NULL,shift_id uuid NOT NULL,basis_version integer NOT NULL CHECK(basis_version=2),
 basis jsonb NOT NULL,basis_hash text NOT NULL CHECK(basis_hash ~ '^[a-f0-9]{64}$'),
 captured_at timestamptz NOT NULL,snapshot_text text NOT NULL,creator_xid xid8 NOT NULL,evidence_order bigint NOT NULL UNIQUE,
 CHECK(basis->>'branchId'=branch_id AND basis->>'shiftId'=shift_id::text)
);
ALTER TABLE fin62_cloud_preparation.bases ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_cloud_preparation.bases FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION fin62_cloud_preparation.immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION 'FIN62_BASE_IMMUTABLE'; END $$;
REVOKE ALL ON FUNCTION fin62_cloud_preparation.immutable() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER bases_immutable BEFORE UPDATE OR DELETE ON fin62_cloud_preparation.bases FOR EACH ROW EXECUTE FUNCTION fin62_cloud_preparation.immutable();
CREATE FUNCTION public.prototype_fin62_create_basis(p_org text,p_branch text,p_terminal text,p_shift uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $function$
DECLARE result jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_SERVICE_REQUIRED'; END IF;
 PERFORM public.pos_sync_validate_read_scope(p_org,p_branch,p_terminal);
 -- COMPLETE actual server rows from ONE statement snapshot; never a caller list.
 WITH scope AS MATERIALIZED (
  SELECT * FROM public.shifts WHERE id=p_shift AND store_id=p_branch
 ), inputs AS MATERIALIZED (
  SELECT s.id,s.store_id,s.shift_id,s.total_amount,s.payment_type,s.payments,s.is_refunded,s.row_version,s.discount_amount
  FROM public.sales s JOIN scope sh ON s.shift_id=sh.id::text AND s.store_id=sh.store_id
 ), raw AS (
  SELECT jsonb_build_object('prototypeVersion',2,'formula','canonical-exact-decimal-v2','branchId',sh.store_id,'shiftId',sh.id,
   'openingFloat',sh.opening_float::text,'shiftVersion',sh.row_version::text,'parentSnapshot',to_jsonb(sh),
   'inputs',coalesce((SELECT jsonb_agg(jsonb_build_object('id',i.id,'branchId',i.store_id,'shiftId',i.shift_id,
    'totalAmount',i.total_amount::text,'paymentType',i.payment_type,'paymentsJson',i.payments::text,
    'discountAmount',i.discount_amount::text,'isRefunded',i.is_refunded,'rowVersion',i.row_version::text) ORDER BY i.id) FROM inputs i),'[]'::jsonb)) value
  FROM scope sh
 ), stored AS (
  INSERT INTO fin62_cloud_preparation.bases(id,organization_id,branch_id,terminal_id,shift_id,basis_version,basis,basis_hash,captured_at,snapshot_text,creator_xid,evidence_order)
  SELECT gen_random_uuid(),p_org,p_branch,p_terminal,p_shift,2,value,encode(sha256(convert_to(value::text,'UTF8')),'hex'),statement_timestamp(),pg_current_snapshot()::text,pg_current_xact_id(),nextval('fin62_evidence_preparation.helper_order') FROM raw
  RETURNING id,basis,basis_hash,captured_at
 ) SELECT jsonb_build_object('basisId',id,'basis',basis,'basisHash',basis_hash,'basisJson',basis::text,'capturedAt',captured_at) INTO result FROM stored;
 IF result IS NULL THEN RAISE EXCEPTION 'FIN62_SHIFT_BRANCH_MISSING'; END IF;
 RETURN result;
END $function$;
REVOKE ALL ON FUNCTION public.prototype_fin62_create_basis(text,text,text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.prototype_fin62_create_basis(text,text,text,uuid) TO service_role;
-- Deliberately no writer accepting caller-provided authorized flags/actor labels.
-- Financial receipt issuance requires actual guarded sale/refund writer wiring.
CREATE FUNCTION public.prototype_fin62_admit(p_org text,p_branch text,p_terminal text,p_basis uuid,p_intent uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $function$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_SERVICE_REQUIRED'; END IF;
 PERFORM public.pos_sync_validate_read_scope(p_org,p_branch,p_terminal);
 IF NOT EXISTS(SELECT 1 FROM fin62_cloud_preparation.bases b WHERE b.id=p_basis AND b.organization_id=p_org AND b.branch_id=p_branch AND b.terminal_id=p_terminal)
 THEN RAISE EXCEPTION 'FIN62_BASIS_SCOPE_MISMATCH'; END IF;
 RAISE EXCEPTION 'FIN62_VERIFIED_FINANCIAL_RECEIPTS_REQUIRED';
END $function$;
REVOKE ALL ON FUNCTION public.prototype_fin62_admit(text,text,text,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.prototype_fin62_admit(text,text,text,uuid,uuid) TO service_role;

-- Source: scripts/preparation/shift-financial-version-receipts.sql
-- Canonical source SHA256: E586BEE66E61A826D85CF9DC2A7C54FB615CA6A774A335BFBC05F0737A8F120B
-- FIN62 PREPARATION ONLY / NOT FINAL / DO NOT EXECUTE ON OPERATOR DATABASE.
-- Records actual committed sales row versions, NOT operator authorization.
-- No client-row/authorized-flag issuer. No existing writer/validator is replaced.
-- Observed auth/GUC context is diagnostic only and NEVER verified author proof.
-- Shared order is ONLY helper execution order within one transaction; it is
-- never a global commit clock. Controlled ordered helper calls are required.
CREATE SCHEMA IF NOT EXISTS fin62_evidence_preparation;
REVOKE ALL ON SCHEMA fin62_evidence_preparation FROM PUBLIC,anon,authenticated,service_role;
CREATE SEQUENCE IF NOT EXISTS fin62_evidence_preparation.helper_order AS bigint;
REVOKE ALL ON SEQUENCE fin62_evidence_preparation.helper_order FROM PUBLIC,anon,authenticated,service_role;
CREATE SCHEMA fin62_version_preparation;
REVOKE ALL ON SCHEMA fin62_version_preparation FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE fin62_version_preparation.sales_versions(
 id uuid PRIMARY KEY,sale_id uuid NOT NULL,operation text NOT NULL CHECK(operation IN('INSERT','UPDATE','DELETE')),
 before_basis jsonb,after_basis jsonb,before_hash text,after_hash text,
 observed_auth_uid uuid,observed_context jsonb NOT NULL,
 capture_xid xid8 NOT NULL,evidence_order bigint NOT NULL UNIQUE,provenance text NOT NULL CHECK(provenance='stored_sql_version_only'),captured_at timestamptz NOT NULL,
 CHECK((before_basis IS NULL)=(before_hash IS NULL)),CHECK((after_basis IS NULL)=(after_hash IS NULL)),
 CHECK(before_basis IS NOT NULL OR after_basis IS NOT NULL)
);
CREATE INDEX sales_versions_lookup ON fin62_version_preparation.sales_versions(sale_id,captured_at,id);
ALTER TABLE fin62_version_preparation.sales_versions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_version_preparation.sales_versions FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION fin62_version_preparation.basis(row_value jsonb) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('id',row_value->>'id','branchId',row_value->>'store_id','shiftId',row_value->>'shift_id',
 'totalAmount',row_value->>'total_amount','discountAmount',row_value->>'discount_amount','paymentType',row_value->>'payment_type','paymentsJson',(row_value->'payments')::text,
 'isRefunded',row_value->'is_refunded','rowVersion',row_value->>'row_version');
$$;
REVOKE ALL ON FUNCTION fin62_version_preparation.basis(jsonb) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION fin62_version_preparation.immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION 'FIN62_VERSION_IMMUTABLE'; END $$;
REVOKE ALL ON FUNCTION fin62_version_preparation.immutable() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER sales_versions_immutable BEFORE UPDATE OR DELETE ON fin62_version_preparation.sales_versions FOR EACH ROW EXECUTE FUNCTION fin62_version_preparation.immutable();
CREATE FUNCTION fin62_version_preparation.capture_sale() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $function$
DECLARE before_value jsonb;after_value jsonb;sid uuid;
BEGIN
 IF TG_OP<>'INSERT' THEN before_value:=fin62_version_preparation.basis(to_jsonb(OLD));sid:=OLD.id; END IF;
 IF TG_OP<>'DELETE' THEN after_value:=fin62_version_preparation.basis(to_jsonb(NEW));sid:=NEW.id; END IF;
 IF before_value IS NOT DISTINCT FROM after_value THEN RETURN NULL; END IF;
 INSERT INTO fin62_version_preparation.sales_versions(id,sale_id,operation,before_basis,after_basis,before_hash,after_hash,observed_auth_uid,observed_context,capture_xid,evidence_order,provenance,captured_at)
 VALUES(gen_random_uuid(),sid,TG_OP,before_value,after_value,
  CASE WHEN before_value IS NULL THEN NULL ELSE encode(sha256(convert_to(before_value::text,'UTF8')),'hex') END,
  CASE WHEN after_value IS NULL THEN NULL ELSE encode(sha256(convert_to(after_value::text,'UTF8')),'hex') END,
  auth.uid(),jsonb_build_object('databaseRole',session_user,'branchSetting',left(current_setting('pos.branch_id',true),256),
   'terminalSetting',left(current_setting('pos.terminal_id',true),256),'contextVerified',false),
  pg_current_xact_id(),nextval('fin62_evidence_preparation.helper_order'),'stored_sql_version_only',statement_timestamp());
 RETURN NULL;
END $function$;
REVOKE ALL ON FUNCTION fin62_version_preparation.capture_sale() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER prototype_fin62_capture_sale_version AFTER INSERT OR UPDATE OR DELETE ON public.sales FOR EACH ROW EXECUTE FUNCTION fin62_version_preparation.capture_sale();
-- A table trigger observes accepted SQL state across existing mutation aliases.
-- It does not authorize those aliases, attest historical local-only versions,
-- enroll keys, prove completeness or issue financial-operation/action receipts.

-- Source: scripts/preparation/shift-financial-known-basis.sql
-- Canonical source SHA256: D457C1244530ADE35D458F5A9E48BE234F61A9A248631EB65D5FAAA22144457E
-- FIN62 PREPARATION ONLY / NOT FINAL / DO NOT APPLY TO OPERATOR DATABASE.
-- Read-only stored-version verification. NOT operator authorization, proof that a
-- device actually observed these versions, action admission or permission grant.
-- Requires the separate baseline/version/math preparation fixtures. No writes.
-- Private semantic comparison only. SQL/local row-version clocks are NOT a
-- financial identity. Invalid/ambiguous raw payments remain held, even refunded.
CREATE FUNCTION fin62_cloud_preparation.fact_identity(value text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
 SELECT CASE WHEN value ~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN lower(value) ELSE value END;
$$;
CREATE FUNCTION fin62_cloud_preparation.fact_payment(entry jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE method text;folded text;
BEGIN
 IF jsonb_typeof(entry)<>'object' THEN RAISE EXCEPTION 'FIN62_FINANCIAL_FACT_UNVERIFIED';END IF;
 IF entry?'amount' AND entry->'amount'<>'null'::jsonb THEN
  IF jsonb_typeof(entry->'amount') NOT IN('number','string') THEN RAISE EXCEPTION 'FIN62_FINANCIAL_FACT_UNVERIFIED';END IF;
  entry:=jsonb_set(entry,'{amount}',to_jsonb(fin62_preparation.math_decimal_text(entry->>'amount')));
 END IF;
 method:=entry->>'method';folded:=translate(method,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz');
 IF jsonb_typeof(entry->'method')='string' AND folded COLLATE "C" IN('cash','card','wallet','bank_transfer','transfer','qr','online','ewallet') THEN entry:=jsonb_set(entry,'{method}',to_jsonb(folded));END IF;
 RETURN entry;
END $$;
REVOKE ALL ON FUNCTION fin62_cloud_preparation.fact_payment(jsonb) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION fin62_cloud_preparation.financial_fact(item jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $fact$
DECLARE parsed json;payments jsonb;method text;folded text;total numeric;refunded boolean;
BEGIN
 IF jsonb_typeof(item)<>'object' OR NOT(item?'totalAmount' AND item?'paymentType' AND item?'paymentsJson' AND item?'isRefunded') OR
  jsonb_typeof(item->'totalAmount') NOT IN('string','null') OR jsonb_typeof(item->'paymentType') NOT IN('string','null') OR
  jsonb_typeof(item->'paymentsJson') NOT IN('string','null') OR jsonb_typeof(item->'isRefunded') NOT IN('boolean','null') THEN RAISE EXCEPTION 'FIN62_FINANCIAL_FACT_UNVERIFIED'; END IF;
 total:=CASE WHEN item->'totalAmount'='null'::jsonb THEN NULL ELSE fin62_preparation.math_decimal_text(item->>'totalAmount') END;
 refunded:=coalesce((item->>'isRefunded')::boolean,false);
 IF item->'paymentsJson'='null'::jsonb THEN payments:='null'::jsonb;
 ELSE
  BEGIN parsed:=CASE WHEN item->>'paymentsJson'='' THEN 'null'::json ELSE (item->>'paymentsJson')::json END;EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'FIN62_FINANCIAL_FACT_UNVERIFIED';END;
  PERFORM fin62_preparation.math_unique_json(parsed);payments:=parsed::jsonb;
  IF jsonb_typeof(payments)='array' THEN
   -- Aggregate once in original order; repeated JSONB array concatenation
   -- copies the growing array for every tender and becomes quadratic.
   SELECT coalesce(jsonb_agg(fin62_cloud_preparation.fact_payment(value) ORDER BY ordinal),'[]'::jsonb) INTO payments
   FROM jsonb_array_elements(payments) WITH ORDINALITY tender(value,ordinal);
  END IF;
 END IF;
 IF jsonb_typeof(payments) IS DISTINCT FROM 'array' OR payments='[]'::jsonb THEN payments:='null'::jsonb;END IF;
 method:=item->>'paymentType';folded:=translate(method,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz');
 IF folded COLLATE "C" IN('cash','card','wallet','bank_transfer','transfer','qr','online','ewallet') THEN method:=folded;END IF;
 RETURN jsonb_build_object('id',fin62_cloud_preparation.fact_identity(item->>'id'),
  'branchId',fin62_cloud_preparation.fact_identity(item->>'branchId'),'shiftId',fin62_cloud_preparation.fact_identity(item->>'shiftId'),
  'totalAmount',total,'discountAmount',CASE WHEN item->>'discountAmount' IS NULL THEN 0 ELSE fin62_preparation.math_decimal_text(item->>'discountAmount') END,'paymentType',method,'payments',payments,'isRefunded',refunded);
END $fact$;
REVOKE ALL ON FUNCTION fin62_cloud_preparation.fact_identity(text),fin62_cloud_preparation.financial_fact(jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- NEW v2 snapshots exclude refunded tender fields exactly as canonical math.
-- Actual mutation policy continues to use FULL financial_fact below/elsewhere.
CREATE FUNCTION fin62_cloud_preparation.snapshot_financial_fact(item jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
BEGIN
 IF item->'isRefunded'='true'::jsonb THEN
  IF jsonb_typeof(item->'paymentType') NOT IN('string','null') OR jsonb_typeof(item->'paymentsJson') NOT IN('string','null') THEN RAISE EXCEPTION 'FIN62_FINANCIAL_FACT_UNVERIFIED';END IF;
  RETURN fin62_cloud_preparation.financial_fact(item||jsonb_build_object('paymentType',NULL,'paymentsJson',NULL))-'paymentType'-'payments';
 END IF;
 RETURN fin62_cloud_preparation.financial_fact(item);
END $$;
REVOKE ALL ON FUNCTION fin62_cloud_preparation.snapshot_financial_fact(jsonb) FROM PUBLIC,anon,authenticated,service_role;-- Actual MVCC visibility, never statement time, determines which transitions
-- were absent from the baseline snapshot. Timestamps remain diagnostics only.
CREATE FUNCTION fin62_cloud_preparation.version_reachable(p_basis uuid,p_sale uuid,p_receipt uuid,p_initial jsonb)
RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $lineage$
DECLARE base fin62_cloud_preparation.bases%ROWTYPE;target fin62_version_preparation.sales_versions%ROWTYPE;
BEGIN
 SELECT * INTO STRICT base FROM fin62_cloud_preparation.bases WHERE id=p_basis;
 SELECT * INTO target FROM fin62_version_preparation.sales_versions WHERE id=p_receipt AND sale_id=p_sale;
 IF NOT FOUND THEN RETURN false;END IF;
 -- For the same xid, private sequence values prove supported ordered helper
 -- calls. Arbitrary multi-mutating CTE/privileged SQL remains unverified.
 IF target.capture_xid=base.creator_xid THEN
  IF target.evidence_order<=base.evidence_order THEN RETURN false;END IF;
 ELSIF pg_visible_in_snapshot(target.capture_xid,base.snapshot_text::pg_snapshot) THEN RETURN false;END IF;
 IF (SELECT count(*) FROM fin62_version_preparation.sales_versions v WHERE v.sale_id=p_sale AND ((v.capture_xid=base.creator_xid AND v.evidence_order>base.evidence_order) OR
  (v.capture_xid<>base.creator_xid AND NOT pg_visible_in_snapshot(v.capture_xid,base.snapshot_text::pg_snapshot))))>512 THEN RAISE EXCEPTION 'FIN62_VERSION_LINEAGE_LIMIT';END IF;
 RETURN (WITH RECURSIVE edges AS MATERIALIZED(
  SELECT v.id,fin62_cloud_preparation.snapshot_financial_fact(v.before_basis) before_fact,fin62_cloud_preparation.snapshot_financial_fact(v.after_basis) after_fact
  FROM fin62_version_preparation.sales_versions v WHERE v.sale_id=p_sale AND ((v.capture_xid=base.creator_xid AND v.evidence_order>base.evidence_order) OR
   (v.capture_xid<>base.creator_xid AND NOT pg_visible_in_snapshot(v.capture_xid,base.snapshot_text::pg_snapshot)))
   AND (v.before_basis IS NULL OR (fin62_cloud_preparation.fact_identity(v.before_basis->>'branchId')=fin62_cloud_preparation.fact_identity(base.branch_id)
    AND fin62_cloud_preparation.fact_identity(v.before_basis->>'shiftId')=base.shift_id::text))
   AND (v.after_basis IS NULL OR (fin62_cloud_preparation.fact_identity(v.after_basis->>'branchId')=fin62_cloud_preparation.fact_identity(base.branch_id)
    AND fin62_cloud_preparation.fact_identity(v.after_basis->>'shiftId')=base.shift_id::text))
 ),reachable(fact) AS(
  SELECT coalesce(fin62_cloud_preparation.snapshot_financial_fact(p_initial),'null'::jsonb)
  UNION
  SELECT coalesce(e.after_fact,'null'::jsonb) FROM reachable r JOIN edges e ON coalesce(e.before_fact,'null'::jsonb)=r.fact
 ) SELECT EXISTS(SELECT 1 FROM edges e JOIN reachable r ON coalesce(e.before_fact,'null'::jsonb)=r.fact WHERE e.id=p_receipt));
END $lineage$;
REVOKE ALL ON FUNCTION fin62_cloud_preparation.version_reachable(uuid,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.prototype_fin62_verify_known_basis(
 p_org text,p_branch text,p_terminal text,p_basis uuid,p_raw_basis text,p_refs jsonb,p_expected jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $function$
DECLARE saved fin62_cloud_preparation.bases%ROWTYPE; calculation jsonb; action_basis jsonb;
 item jsonb;old_item jsonb;ref jsonb;historical fin62_version_preparation.sales_versions%ROWTYPE;
 baseline_map jsonb;action_map jsonb;refs_map jsonb;selected jsonb;raw_version text;used_ids text[]:=ARRAY[]::text[];identifier text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_SERVICE_REQUIRED'; END IF;
 PERFORM public.pos_sync_validate_read_scope(p_org,p_branch,p_terminal);
 SELECT * INTO saved FROM fin62_cloud_preparation.bases WHERE id=p_basis AND organization_id=p_org AND branch_id=p_branch AND terminal_id=p_terminal;
 IF NOT FOUND THEN RAISE EXCEPTION 'FIN62_BASIS_SCOPE_MISMATCH'; END IF;
 IF jsonb_array_length(saved.basis->'inputs')>20000 OR octet_length(saved.basis::text)>6*1024*1024 THEN RAISE EXCEPTION 'FIN62_BASIS_LIMIT'; END IF;
 IF p_raw_basis IS NULL OR octet_length(p_raw_basis)>6*1024*1024 THEN RAISE EXCEPTION 'FIN62_BASIS_LIMIT';END IF;
 BEGIN
  PERFORM fin62_preparation.math_unique_json(p_raw_basis::json);
  SELECT value::text INTO raw_version FROM json_each(p_raw_basis::json) WHERE key='prototypeVersion';
  IF raw_version IS DISTINCT FROM '2' THEN RAISE EXCEPTION 'FIN62_INPUT_MATH_UNSUPPORTED';END IF;
  action_basis:=p_raw_basis::jsonb;
  IF jsonb_typeof(action_basis->'inputs') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'FIN62_INPUT_MATH_UNSUPPORTED';END IF;
 EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'FIN62_INPUT_MATH_UNSUPPORTED';END;
 -- Normalize UUID case before the strict math parser, preserving non-UUID labels.
 action_basis:=action_basis||jsonb_build_object(
  'branchId',CASE WHEN jsonb_typeof(action_basis->'branchId')='string' THEN to_jsonb(fin62_cloud_preparation.fact_identity(action_basis->>'branchId')) ELSE action_basis->'branchId' END,
  'shiftId',CASE WHEN jsonb_typeof(action_basis->'shiftId')='string' THEN to_jsonb(fin62_cloud_preparation.fact_identity(action_basis->>'shiftId')) ELSE action_basis->'shiftId' END,
  'inputs',(SELECT coalesce(jsonb_agg(value||jsonb_build_object(
   'id',CASE WHEN jsonb_typeof(value->'id')='string' THEN to_jsonb(fin62_cloud_preparation.fact_identity(value->>'id')) ELSE value->'id' END,
   'branchId',CASE WHEN jsonb_typeof(value->'branchId')='string' THEN to_jsonb(fin62_cloud_preparation.fact_identity(value->>'branchId')) ELSE value->'branchId' END,
   'shiftId',CASE WHEN jsonb_typeof(value->'shiftId')='string' THEN to_jsonb(fin62_cloud_preparation.fact_identity(value->>'shiftId')) ELSE value->'shiftId' END)),'[]'::jsonb) FROM jsonb_array_elements(action_basis->'inputs')));
 calculation:=fin62_preparation.validate_financial_math_text(action_basis::text);
 IF calculation->>'status' IS DISTINCT FROM 'computed' THEN RAISE EXCEPTION 'FIN62_INPUT_MATH_UNSUPPORTED'; END IF;
 IF action_basis->'prototypeVersion' IS DISTINCT FROM saved.basis->'prototypeVersion' OR action_basis->'formula' IS DISTINCT FROM saved.basis->'formula' OR
  fin62_cloud_preparation.fact_identity(action_basis->>'branchId') IS DISTINCT FROM fin62_cloud_preparation.fact_identity(saved.basis->>'branchId') OR fin62_cloud_preparation.fact_identity(action_basis->>'shiftId') IS DISTINCT FROM saved.basis->>'shiftId' OR
  (CASE WHEN action_basis->'openingFloat'='null'::jsonb THEN 0 ELSE fin62_preparation.math_decimal_text(action_basis->>'openingFloat') END) IS DISTINCT FROM (CASE WHEN saved.basis->'openingFloat'='null'::jsonb THEN 0 ELSE fin62_preparation.math_decimal_text(saved.basis->>'openingFloat') END)
 THEN RAISE EXCEPTION 'FIN62_BASIS_CONTEXT_MISMATCH'; END IF;
 IF calculation->'expected' IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'FIN62_EXPECTED_MISMATCH'; END IF;
 IF jsonb_typeof(p_refs) IS DISTINCT FROM 'array' OR jsonb_array_length(p_refs)>20000 OR octet_length(p_refs::text)>2*1024*1024 THEN RAISE EXCEPTION 'FIN62_RECEIPT_REFS_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_refs) x GROUP BY x->>'saleId' HAVING count(*)>1) OR
  EXISTS(SELECT 1 FROM jsonb_array_elements(p_refs) x GROUP BY x->>'receiptId' HAVING count(*)>1)
 THEN RAISE EXCEPTION 'FIN62_RECEIPT_REFS_INVALID'; END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(p_refs) LOOP
  IF jsonb_typeof(ref)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(ref))<>3 OR NOT(ref?'saleId' AND ref?'receiptId' AND ref?'side') OR
   coalesce(ref->>'saleId','')!~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' OR
   coalesce(ref->>'receiptId','')!~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' OR
   coalesce(ref->>'side','') NOT IN('before','after','delete') THEN RAISE EXCEPTION 'FIN62_RECEIPT_REFS_INVALID'; END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(value||jsonb_build_object('saleId',fin62_cloud_preparation.fact_identity(value->>'saleId'),'receiptId',fin62_cloud_preparation.fact_identity(value->>'receiptId'))),'[]'::jsonb) INTO p_refs FROM jsonb_array_elements(p_refs);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_refs) x GROUP BY x->>'saleId' HAVING count(*)>1) OR
  EXISTS(SELECT 1 FROM jsonb_array_elements(p_refs) x GROUP BY x->>'receiptId' HAVING count(*)>1) THEN RAISE EXCEPTION 'FIN62_RECEIPT_REFS_INVALID';END IF;
 SELECT coalesce(jsonb_object_agg(fin62_cloud_preparation.fact_identity(value->>'id'),value),'{}'::jsonb) INTO baseline_map FROM jsonb_array_elements(saved.basis->'inputs');
 SELECT coalesce(jsonb_object_agg(value->>'id',value),'{}'::jsonb) INTO action_map FROM jsonb_array_elements(action_basis->'inputs');
 SELECT coalesce(jsonb_object_agg(value->>'saleId',value),'{}'::jsonb) INTO refs_map FROM jsonb_array_elements(p_refs);
 -- Preserve EVERY baseline ID unless its exact prior state has an actual DELETE
 -- receipt. A caller-supplied subset never establishes baseline completeness.
 FOR old_item IN SELECT value FROM jsonb_array_elements(saved.basis->'inputs') LOOP
  identifier:=fin62_cloud_preparation.fact_identity(old_item->>'id');
  IF NOT(action_map?identifier) THEN
   ref:=refs_map->identifier;
   IF ref IS NULL OR ref->>'side' IS DISTINCT FROM 'delete' THEN RAISE EXCEPTION 'FIN62_BASELINE_ROW_OMITTED'; END IF;
   SELECT * INTO historical FROM fin62_version_preparation.sales_versions WHERE id=(ref->>'receiptId')::uuid AND sale_id=identifier::uuid;
   IF NOT FOUND OR historical.operation<>'DELETE' OR historical.after_basis IS NOT NULL OR NOT fin62_cloud_preparation.version_reachable(saved.id,identifier::uuid,historical.id,old_item)
   THEN RAISE EXCEPTION 'FIN62_STORED_VERSION_REQUIRED'; END IF;
   used_ids:=array_append(used_ids,ref->>'receiptId');
  END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(action_basis->'inputs') LOOP
  identifier:=item->>'id';old_item:=baseline_map->identifier;
  IF fin62_cloud_preparation.snapshot_financial_fact(old_item) IS NOT DISTINCT FROM fin62_cloud_preparation.snapshot_financial_fact(item) THEN CONTINUE; END IF;
  ref:=refs_map->identifier;
  IF ref IS NULL OR coalesce(ref->>'side','') NOT IN('before','after') THEN RAISE EXCEPTION 'FIN62_STORED_VERSION_REQUIRED'; END IF;
  SELECT * INTO historical FROM fin62_version_preparation.sales_versions WHERE id=(ref->>'receiptId')::uuid AND sale_id=identifier::uuid;
  IF NOT FOUND OR NOT fin62_cloud_preparation.version_reachable(saved.id,identifier::uuid,historical.id,old_item) THEN RAISE EXCEPTION 'FIN62_STORED_VERSION_REQUIRED'; END IF;
  selected:=CASE WHEN ref->>'side'='before' THEN historical.before_basis ELSE historical.after_basis END;
  IF fin62_cloud_preparation.snapshot_financial_fact(selected) IS DISTINCT FROM fin62_cloud_preparation.snapshot_financial_fact(item) OR fin62_cloud_preparation.fact_identity(selected->>'branchId') IS DISTINCT FROM fin62_cloud_preparation.fact_identity(p_branch) OR fin62_cloud_preparation.fact_identity(selected->>'shiftId') IS DISTINCT FROM saved.shift_id::text
  THEN RAISE EXCEPTION 'FIN62_STORED_VERSION_REQUIRED'; END IF;
  used_ids:=array_append(used_ids,ref->>'receiptId');
 END LOOP;
 IF cardinality(used_ids)<>jsonb_array_length(p_refs) THEN RAISE EXCEPTION 'FIN62_UNUSED_RECEIPT_REF'; END IF;
 RETURN jsonb_build_object('status','verified-stored-basis','basisId',saved.id,'expected',calculation->'expected',
  'operatorAuthorized',false,'observedByDeviceProven',false,'admissionGranted',false);
END $function$;
REVOKE ALL ON FUNCTION public.prototype_fin62_verify_known_basis(text,text,text,uuid,text,jsonb,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.prototype_fin62_verify_known_basis(text,text,text,uuid,text,jsonb,jsonb) TO service_role;

-- Source: scripts/preparation/shift-financial-opening-origin.sql
-- Canonical source SHA256: 63F29DE5708D85D6C4F575BA300A137512B3C1258433C8E476F080F1BB4A0075
-- FIN62 PREPARATION ONLY / NOT FINAL / DO NOT APPLY TO OPERATOR DATABASE.
-- Accepted OPEN origin foundation. Does NOT verify HTTP device/user proofs;
-- the hosting layer must supply its existing verified terminal admission.
-- Existing aggregate routines/permissions are delegated unchanged. No backfill.
CREATE SCHEMA fin62_origin_preparation;
REVOKE ALL ON SCHEMA fin62_origin_preparation FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE fin62_origin_preparation.active_context(
 backend_pid integer NOT NULL,capture_xid xid8 NOT NULL,nonce uuid PRIMARY KEY,
 organization_id text NOT NULL,branch_id text NOT NULL,terminal_id text NOT NULL,shift_id uuid NOT NULL,
 UNIQUE(backend_pid,capture_xid)
);
CREATE TABLE fin62_origin_preparation.births(nonce uuid PRIMARY KEY,shift_id uuid NOT NULL,basis_id uuid NOT NULL REFERENCES fin62_cloud_preparation.bases(id));
CREATE TABLE fin62_origin_preparation.origins(
 id uuid PRIMARY KEY,organization_id text NOT NULL,branch_id text NOT NULL,terminal_id text NOT NULL,
 local_aggregate_id uuid NOT NULL,row_hash text NOT NULL CHECK(row_hash~'^[a-f0-9]{64}$'),
 shift_id uuid NOT NULL UNIQUE,batch_id uuid NOT NULL,operations_hash text NOT NULL,
 basis_id uuid NOT NULL REFERENCES fin62_cloud_preparation.bases(id),upload_result jsonb NOT NULL,
 UNIQUE(organization_id,terminal_id,local_aggregate_id)
);
ALTER TABLE fin62_origin_preparation.active_context ENABLE ROW LEVEL SECURITY;
ALTER TABLE fin62_origin_preparation.births ENABLE ROW LEVEL SECURITY;
ALTER TABLE fin62_origin_preparation.origins ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA fin62_origin_preparation FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION fin62_origin_preparation.immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION 'FIN62_OPEN_ORIGIN_IMMUTABLE';END $$;
REVOKE ALL ON FUNCTION fin62_origin_preparation.immutable() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER births_immutable BEFORE UPDATE OR DELETE ON fin62_origin_preparation.births FOR EACH ROW EXECUTE FUNCTION fin62_origin_preparation.immutable();
CREATE TRIGGER origins_immutable BEFORE UPDATE OR DELETE ON fin62_origin_preparation.origins FOR EACH ROW EXECUTE FUNCTION fin62_origin_preparation.immutable();
CREATE FUNCTION fin62_origin_preparation.capture_birth() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $fn$
DECLARE context fin62_origin_preparation.active_context%ROWTYPE;basis jsonb;
BEGIN
 SELECT * INTO context FROM fin62_origin_preparation.active_context WHERE backend_pid=pg_backend_pid() AND capture_xid=pg_current_xact_id() AND shift_id=NEW.id;
 IF NOT FOUND THEN RETURN NULL;END IF; -- All old/unwrapped insertion paths stay unchanged.
 IF NEW.store_id IS DISTINCT FROM context.branch_id OR NEW.terminal_id IS DISTINCT FROM context.terminal_id OR NEW.status IS DISTINCT FROM 'OPEN' OR
  NEW.closed_at IS NOT NULL OR coalesce(NEW.state,'ACTIVE')<>'ACTIVE' THEN RAISE EXCEPTION 'FIN62_OPEN_BIRTH_INVALID';END IF;
 IF EXISTS(SELECT 1 FROM public.sales s WHERE s.shift_id=NEW.id::text AND s.store_id=context.branch_id) THEN RAISE EXCEPTION 'FIN62_OPEN_BIRTH_NOT_EMPTY';END IF;
 basis:=public.prototype_fin62_create_basis(context.organization_id,context.branch_id,context.terminal_id,NEW.id);
 IF jsonb_array_length(basis->'basis'->'inputs')<>0 THEN RAISE EXCEPTION 'FIN62_OPEN_BIRTH_NOT_EMPTY';END IF;
 INSERT INTO fin62_origin_preparation.births(nonce,shift_id,basis_id) VALUES(context.nonce,NEW.id,(basis->>'basisId')::uuid);
 RETURN NULL;
END $fn$;
REVOKE ALL ON FUNCTION fin62_origin_preparation.capture_birth() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER prototype_fin62_capture_open_birth AFTER INSERT ON public.shifts FOR EACH ROW EXECUTE FUNCTION fin62_origin_preparation.capture_birth();
CREATE FUNCTION public.prototype_fin62_push_open_origin(
 p_batch uuid,p_org text,p_branch text,p_terminal text,p_local_aggregate uuid,p_opening_json text,p_row_hash text,p_operations jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $fn$
DECLARE row_value jsonb;shift uuid;digest text;v_nonce uuid;basis uuid;result jsonb;prior fin62_origin_preparation.origins%ROWTYPE;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_SERVICE_REQUIRED';END IF;
 PERFORM public.pos_sync_validate_scope(p_org,p_branch,p_terminal);
 IF p_batch IS NULL OR p_local_aggregate IS NULL OR p_opening_json IS NULL OR octet_length(p_opening_json)>256*1024 OR
  p_row_hash IS NULL OR p_row_hash!~'^[a-f0-9]{64}$' OR encode(sha256(convert_to(p_opening_json,'UTF8')),'hex')<>p_row_hash
 THEN RAISE EXCEPTION 'FIN62_OPEN_ORIGIN_INPUT_INVALID';END IF;
 PERFORM fin62_preparation.math_unique_json(p_opening_json::json);row_value:=p_opening_json::jsonb;
 IF octet_length(p_operations::text)>6*1024*1024 OR jsonb_typeof(p_operations) IS DISTINCT FROM 'array' OR jsonb_array_length(p_operations)<>1 OR p_operations->0->>'table' IS DISTINCT FROM 'shifts' OR
  jsonb_typeof(p_operations->0->'rows') IS DISTINCT FROM 'array' OR jsonb_array_length(p_operations->0->'rows')<>1 OR
  p_operations->0->'rows'->0 IS DISTINCT FROM row_value OR coalesce((p_operations->0->>'deletePhase')::boolean,false) OR
  EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(p_operations->0->'changes','[]'::jsonb)) c WHERE upper(coalesce(c->>'operation','')) NOT IN('INSERT','I'))
 THEN RAISE EXCEPTION 'FIN62_OPEN_ORIGIN_OPERATIONS_INVALID';END IF;
 IF row_value->>'store_id' IS DISTINCT FROM p_branch OR row_value->>'terminal_id' IS DISTINCT FROM p_terminal OR
  row_value->>'status' IS DISTINCT FROM 'OPEN' OR coalesce(row_value->>'state','ACTIVE')<>'ACTIVE' OR row_value->>'closed_at' IS NOT NULL
 THEN RAISE EXCEPTION 'FIN62_OPEN_ORIGIN_INPUT_INVALID';END IF;
 shift:=(row_value->>'id')::uuid;IF shift IS NULL THEN RAISE EXCEPTION 'FIN62_OPEN_ORIGIN_INPUT_INVALID';END IF;
 digest:=encode(sha256(convert_to(p_operations::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('fin62-open-origin:'||shift::text,0));
 SELECT * INTO prior FROM fin62_origin_preparation.origins WHERE organization_id=p_org AND terminal_id=p_terminal AND local_aggregate_id=p_local_aggregate;
 IF FOUND THEN
  IF ROW(prior.branch_id,prior.shift_id,prior.row_hash,prior.batch_id,prior.operations_hash) IS DISTINCT FROM ROW(p_branch,shift,p_row_hash,p_batch,digest)
  THEN RAISE EXCEPTION 'FIN62_OPEN_ORIGIN_CONFLICT';END IF;
  RETURN prior.upload_result||jsonb_build_object('openingOrigin',jsonb_build_object('localAggregateId',p_local_aggregate,'rowHash',p_row_hash),'birthBasisId',prior.basis_id,'originReplayed',true);
 END IF;
 IF EXISTS(SELECT 1 FROM public.shifts WHERE id=shift) OR EXISTS(SELECT 1 FROM fin62_origin_preparation.origins WHERE shift_id=shift) THEN RAISE EXCEPTION 'FIN62_OPEN_ORIGIN_NOT_NEW';END IF;
 v_nonce:=gen_random_uuid();
 INSERT INTO fin62_origin_preparation.active_context VALUES(pg_backend_pid(),pg_current_xact_id(),v_nonce,p_org,p_branch,p_terminal,shift);
 result:=public.pos_sync_push_aggregate(p_batch,p_org,p_branch,p_terminal,p_operations);
 IF result->'ok' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'FIN62_OPEN_UPLOAD_NOT_ACKNOWLEDGED';END IF;
 SELECT basis_id INTO basis FROM fin62_origin_preparation.births WHERE births.nonce=v_nonce AND shift_id=shift;
 IF basis IS NULL OR NOT EXISTS(SELECT 1 FROM public.shifts s WHERE s.id=shift AND s.store_id=p_branch AND s.status='OPEN' AND s.closed_at IS NULL) THEN RAISE EXCEPTION 'FIN62_OPEN_BIRTH_MISSING';END IF;
 INSERT INTO fin62_origin_preparation.origins VALUES(gen_random_uuid(),p_org,p_branch,p_terminal,p_local_aggregate,p_row_hash,shift,p_batch,digest,basis,result);
 DELETE FROM fin62_origin_preparation.active_context c WHERE c.nonce=v_nonce;
 RETURN result||jsonb_build_object('openingOrigin',jsonb_build_object('localAggregateId',p_local_aggregate,'rowHash',p_row_hash),'birthBasisId',basis,'originReplayed',false);
END $fn$;
REVOKE ALL ON FUNCTION public.prototype_fin62_push_open_origin(uuid,text,text,text,uuid,text,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.prototype_fin62_push_open_origin(uuid,text,text,text,uuid,text,text,jsonb) TO service_role;
CREATE FUNCTION fin62_origin_preparation.resolve(p_org text,p_branch text,p_terminal text,p_shift uuid,p_origin jsonb)
RETURNS uuid LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $fn$
DECLARE basis uuid;
BEGIN
 IF jsonb_typeof(p_origin) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_origin))<>2 OR
  coalesce(p_origin->>'localAggregateId','')!~'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' OR coalesce(p_origin->>'rowHash','')!~'^[a-f0-9]{64}$'
 THEN RAISE EXCEPTION 'FIN62_OPEN_ORIGIN_INPUT_INVALID';END IF;
 SELECT basis_id INTO basis FROM fin62_origin_preparation.origins WHERE organization_id=p_org AND branch_id=p_branch AND terminal_id=p_terminal AND shift_id=p_shift
  AND local_aggregate_id=(p_origin->>'localAggregateId')::uuid AND row_hash=p_origin->>'rowHash';
 IF basis IS NULL THEN RAISE EXCEPTION 'FIN62_OPEN_ORIGIN_UNPROVEN';END IF;RETURN basis;
END $fn$;
REVOKE ALL ON FUNCTION fin62_origin_preparation.resolve(text,text,text,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- Source: scripts/preparation/shift-financial-admission.sql
-- Canonical source SHA256: 099C671B723AE6D2213194102A7909E752B03FC4B06C795B808D850C0F6E20DB
-- FIN62 PREPARATION ONLY / NOT FINAL / DO NOT APPLY TO OPERATOR DATABASE.
-- Additive service-only composition of the ACTUAL unchanged author/start RPCs.
-- HTTP must verify BOTH signatures under their distinct domains using the same
-- already verified graph-author key before this call. PostgreSQL does NOT
-- verify Ed25519; service_role is the existing trusted HTTP-to-SQL boundary.
-- No native activation, baseline/operation issuer, migration registration or
-- historical rewrite is included. Stored-version evidence is NOT author proof.
CREATE SCHEMA fin62_action_preparation;
REVOKE ALL ON SCHEMA fin62_action_preparation FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE fin62_action_preparation.receipts(
 intent_id uuid PRIMARY KEY,organization_id text NOT NULL,branch_id text NOT NULL,terminal_id text NOT NULL,
 shift_id uuid NOT NULL,author_id uuid NOT NULL,key_id uuid NOT NULL,
 graph_payload_hash text NOT NULL CHECK(graph_payload_hash~'^[a-f0-9]{64}$'),
 basis_id uuid NOT NULL,basis_hash text NOT NULL CHECK(basis_hash~'^[a-f0-9]{64}$'),
 basis_json text NOT NULL,basis_proof jsonb NOT NULL,formula text NOT NULL CHECK(formula='canonical-exact-decimal-v2'),
 acknowledgement jsonb NOT NULL,accepted_at timestamptz NOT NULL DEFAULT statement_timestamp()
);
ALTER TABLE fin62_action_preparation.receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_action_preparation.receipts FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION fin62_action_preparation.immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION 'FIN62_ACTION_RECEIPT_IMMUTABLE';END $$;
REVOKE ALL ON FUNCTION fin62_action_preparation.immutable() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON fin62_action_preparation.receipts FOR EACH ROW EXECUTE FUNCTION fin62_action_preparation.immutable();
CREATE FUNCTION public.pos_sync_push_financial_shift_intent(
 p_batch_id uuid,p_organization_id text,p_branch_id text,p_terminal_id text,p_operations jsonb,p_shift_intent jsonb,
 p_shift_author jsonb,p_author_authority jsonb,p_closing_start jsonb,p_start_authority jsonb,p_financial_basis jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $function$
DECLARE raw_graph text;raw_basis text;proof jsonb;intent jsonb;basis jsonb;parent jsonb;expected jsonb;
 graph_hash text;basis_hash text;sid uuid;basis_id uuid;prior fin62_action_preparation.receipts%ROWTYPE;
 result jsonb;field text;amount numeric;parents integer;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_SERVICE_REQUIRED';END IF;
 PERFORM public.pos_sync_validate_scope(p_organization_id,p_branch_id,p_terminal_id);
 IF jsonb_typeof(p_financial_basis) IS DISTINCT FROM 'object' OR
  (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_financial_basis) key) IS DISTINCT FROM ARRAY['basisJson','proof']::text[] OR
  jsonb_typeof(p_financial_basis->'basisJson') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'FIN62_PROOF_INVALID';END IF;
 raw_basis:=p_financial_basis->>'basisJson';proof:=p_financial_basis->'proof';raw_graph:=p_shift_intent->>'payloadJson';
 IF raw_graph IS NULL OR octet_length(raw_graph)>6*1024*1024 OR raw_basis IS NULL OR octet_length(raw_basis)>6*1024*1024 OR
  jsonb_typeof(proof) IS DISTINCT FROM 'object' OR octet_length(proof::text)>4096 OR
  (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(proof) key) IS DISTINCT FROM
   ARRAY['action','algorithm','authorId','basisHash','branchId','formula','graphPayloadHash','intentId','keyId','projectOrigin','serverBasisId','shiftId','signature','subject','terminalId','version']::text[] OR
  proof->'version' IS DISTINCT FROM '1'::jsonb OR proof->>'algorithm' IS DISTINCT FROM 'Ed25519' OR
  proof->>'formula' IS DISTINCT FROM 'canonical-exact-decimal-v2' OR coalesce(proof->>'signature','')!~'^[A-Za-z0-9_-]{86}$' OR
  coalesce(proof->>'basisHash','')!~'^[a-f0-9]{64}$' OR coalesce(proof->>'graphPayloadHash','')!~'^[a-f0-9]{64}$' OR
  coalesce(proof->>'serverBasisId','')!~'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
 THEN RAISE EXCEPTION 'FIN62_PROOF_INVALID';END IF;
 graph_hash:=encode(sha256(convert_to(raw_graph,'UTF8')),'hex');basis_hash:=encode(sha256(convert_to(raw_basis,'UTF8')),'hex');
 IF proof->>'graphPayloadHash' IS DISTINCT FROM graph_hash OR proof->>'basisHash' IS DISTINCT FROM basis_hash THEN RAISE EXCEPTION 'FIN62_PROOF_HASH_MISMATCH';END IF;
 intent:=raw_graph::jsonb;basis:=raw_basis::jsonb;sid:=(intent->>'shiftId')::uuid;basis_id:=(proof->>'serverBasisId')::uuid;
 IF sid IS NULL OR proof->>'shiftId' IS DISTINCT FROM sid::text OR proof->>'intentId' IS DISTINCT FROM p_batch_id::text OR
  proof->>'terminalId' IS DISTINCT FROM p_terminal_id OR proof->>'branchId' IS DISTINCT FROM p_branch_id OR
  proof->>'action' IS DISTINCT FROM intent->>'kind' OR coalesce(proof->>'action','') NOT IN('ORIGINAL','RECOUNT') OR
  basis->'prototypeVersion' IS DISTINCT FROM '2'::jsonb OR basis->>'formula' IS DISTINCT FROM 'canonical-exact-decimal-v2' OR
  basis->>'branchId' IS DISTINCT FROM p_branch_id OR basis->>'shiftId' IS DISTINCT FROM sid::text OR
  jsonb_typeof(basis->'versionReferences') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'FIN62_PROOF_CONTEXT_MISMATCH';END IF;
 FOREACH field IN ARRAY ARRAY['version','algorithm','keyId','projectOrigin','terminalId','authorId','subject','branchId','shiftId','intentId','action'] LOOP
  IF proof->field IS DISTINCT FROM p_shift_author->field THEN RAISE EXCEPTION 'FIN62_AUTHOR_BINDING_MISMATCH';END IF;
 END LOOP;
 IF p_shift_author->>'payloadHash' IS DISTINCT FROM graph_hash THEN RAISE EXCEPTION 'FIN62_AUTHOR_BINDING_MISMATCH';END IF;
 -- Exact same lock order as the actual immutable intent/author/start writers.
 PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-batch:'||p_batch_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-intent:'||p_batch_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-shift:'||sid::text,0));
 SELECT * INTO prior FROM fin62_action_preparation.receipts WHERE intent_id=p_batch_id;
 IF FOUND THEN
  IF ROW(prior.organization_id,prior.branch_id,prior.terminal_id,prior.shift_id,prior.author_id,prior.key_id,prior.graph_payload_hash,prior.basis_id,prior.basis_hash,prior.formula)
    IS DISTINCT FROM ROW(p_organization_id,p_branch_id,p_terminal_id,sid,(proof->>'authorId')::uuid,(proof->>'keyId')::uuid,graph_hash,basis_id,basis_hash,proof->>'formula') OR
   convert_to(prior.basis_json,'UTF8') IS DISTINCT FROM convert_to(raw_basis,'UTF8') OR prior.basis_proof IS DISTINCT FROM proof
  THEN RAISE EXCEPTION 'FIN62_ACTION_REPLAY_MISMATCH';END IF;
  -- Do NOT reprice accepted history after a refund or account revocation.
  -- The old RPC still verifies its exact author receipt and returns the fresh
  -- current-token/superseded acknowledgement rather than replaying old money.
 ELSE
  IF EXISTS(SELECT 1 FROM pos_sync_private.shift_intent_receipts WHERE intent_id=p_batch_id) THEN RAISE EXCEPTION 'FIN62_FINANCIAL_HISTORY_UNPROVEN';END IF;
  SELECT count(*) INTO parents FROM jsonb_array_elements(intent->'operations') op,LATERAL jsonb_array_elements(op->'rows') row_value WHERE op->>'table'='shifts';
  IF parents<>1 THEN RAISE EXCEPTION 'FIN62_PARENT_INVALID';END IF;
  SELECT row_value INTO parent FROM jsonb_array_elements(intent->'operations') op,LATERAL jsonb_array_elements(op->'rows') row_value WHERE op->>'table'='shifts';
  expected:='{}'::jsonb;
  FOREACH field IN ARRAY ARRAY['cash','card','digital'] LOOP
   IF jsonb_typeof(parent->('expected_'||field)) NOT IN('number','string') OR NOT parent?('expected_'||field) THEN RAISE EXCEPTION 'FIN62_EXPECTED_INVALID';END IF;
   amount:=fin62_preparation.math_decimal_text(parent->>('expected_'||field));
   IF round(amount,2) IS DISTINCT FROM amount THEN RAISE EXCEPTION 'FIN62_EXPECTED_FRACTIONAL';END IF;
   expected:=expected||jsonb_build_object(field,round(amount,2)::text);
  END LOOP;
  PERFORM public.prototype_fin62_verify_known_basis(p_organization_id,p_branch_id,p_terminal_id,basis_id,raw_basis,basis->'versionReferences',expected);
 END IF;
 IF p_closing_start IS NOT NULL THEN
  result:=public.pos_sync_push_started_shift_intent(p_batch_id,p_organization_id,p_branch_id,p_terminal_id,p_operations,p_shift_intent,p_shift_author,p_author_authority,p_closing_start,p_start_authority);
 ELSE
  IF p_start_authority IS NOT NULL THEN RAISE EXCEPTION 'FIN62_START_PROOF_REQUIRED';END IF;
  result:=public.pos_sync_push_author_shift_intent(p_batch_id,p_organization_id,p_branch_id,p_terminal_id,p_operations,p_shift_intent,p_shift_author,p_author_authority);
 END IF;
 IF prior.intent_id IS NULL THEN
  INSERT INTO fin62_action_preparation.receipts(intent_id,organization_id,branch_id,terminal_id,shift_id,author_id,key_id,graph_payload_hash,basis_id,basis_hash,basis_json,basis_proof,formula,acknowledgement)
  VALUES(p_batch_id,p_organization_id,p_branch_id,p_terminal_id,sid,(proof->>'authorId')::uuid,(proof->>'keyId')::uuid,graph_hash,basis_id,basis_hash,raw_basis,proof,proof->>'formula',result);
 END IF;
 RETURN result||jsonb_build_object('financial_basis_receipt',jsonb_build_object('ack_version',1,'intentId',p_batch_id,'graphPayloadHash',graph_hash,'basisHash',basis_hash,'serverBasisId',basis_id,'formula',proof->>'formula'));
END $function$;
REVOKE ALL ON FUNCTION public.pos_sync_push_financial_shift_intent(uuid,text,text,text,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pos_sync_push_financial_shift_intent(uuid,text,text,text,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb) TO service_role;

-- Source: scripts/preparation/shift-financial-operation-history.sql
-- Canonical source SHA256: D3118AC2657B889CB9B57B8C2096EA2C2AC563800D7436096D017A98D17F34E2
-- FIN62 PREPARATION ONLY / NOT FINAL / NO LIVE APPLICATION OR ACTIVATION.
-- HTTP MUST verify Ed25519 for author-bound actions; OBSERVE instead requires the existing verified native-device proof.
-- SQL independently checks real registered identity/current action flags. It
-- accepts no caller-supplied authorized flag. Metadata ACK is NOT a sale/shift
-- upload ACK. Applying this preparation rewrites no existing business rows; explicitly called business adapters retain the existing guarded writers.
CREATE SCHEMA fin62_history_preparation;
REVOKE ALL ON SCHEMA fin62_history_preparation FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE fin62_history_preparation.streams(
 organization_id text NOT NULL,branch_id text NOT NULL,terminal_id text NOT NULL,shift_id uuid NOT NULL,
 opening_origin jsonb NOT NULL,birth_basis_id uuid NOT NULL,
 sequence bigint NOT NULL CHECK(sequence>=0),operation_id uuid NOT NULL,payload_hash text NOT NULL,state jsonb NOT NULL CHECK(state='{}'::jsonb),
 PRIMARY KEY(organization_id,branch_id,terminal_id,shift_id)
);
CREATE TABLE fin62_history_preparation.stream_facts(
 organization_id text NOT NULL,branch_id text NOT NULL,terminal_id text NOT NULL,shift_id uuid NOT NULL,sale_id uuid NOT NULL,fact jsonb NOT NULL,
 PRIMARY KEY(organization_id,branch_id,terminal_id,shift_id,sale_id),
 FOREIGN KEY(organization_id,branch_id,terminal_id,shift_id) REFERENCES fin62_history_preparation.streams(organization_id,branch_id,terminal_id,shift_id)
);
ALTER TABLE fin62_history_preparation.stream_facts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_history_preparation.stream_facts FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION fin62_history_preparation.stream_state(p_org text,p_branch text,p_terminal text,p_shift uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT coalesce(jsonb_object_agg(sale_id::text,fact),'{}') FROM fin62_history_preparation.stream_facts WHERE organization_id=p_org AND branch_id=p_branch AND terminal_id=p_terminal AND shift_id=p_shift;
$$;CREATE TABLE fin62_history_preparation.nodes(
 operation_id uuid PRIMARY KEY,organization_id text NOT NULL,branch_id text NOT NULL,terminal_id text NOT NULL,shift_id uuid NOT NULL,
 sequence bigint NOT NULL CHECK(sequence>0),node_kind text NOT NULL CHECK(node_kind IN('MUTATION','CLOSE_BOUNDARY','OBSERVATION')),
 payload_json text NOT NULL,payload_hash text NOT NULL,proof jsonb NOT NULL,
 graph_json text,graph_author jsonb,basis_json text,graph_hash text,basis_hash text,
 observed_basis_id uuid REFERENCES fin62_cloud_preparation.bases(id),pending_from jsonb NOT NULL DEFAULT '{}'::jsonb,
 acknowledgement jsonb NOT NULL,UNIQUE(organization_id,branch_id,terminal_id,shift_id,sequence)
);
ALTER TABLE fin62_history_preparation.streams ENABLE ROW LEVEL SECURITY;
ALTER TABLE fin62_history_preparation.nodes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA fin62_history_preparation FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION fin62_history_preparation.immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION 'FIN62_HISTORY_IMMUTABLE';END $$;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON fin62_history_preparation.nodes FOR EACH ROW EXECUTE FUNCTION fin62_history_preparation.immutable();
CREATE FUNCTION fin62_history_preparation.canonical_json(value jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
BEGIN
 IF jsonb_typeof(value)='object' THEN RETURN '{'||coalesce((SELECT string_agg(to_json(key)::text||':'||fin62_history_preparation.canonical_json(val),',' ORDER BY key COLLATE "C") FROM jsonb_each(value) x(key,val)),'')||'}';
 ELSIF jsonb_typeof(value)='array' THEN RETURN '['||coalesce((SELECT string_agg(fin62_history_preparation.canonical_json(val),',' ORDER BY n) FROM jsonb_array_elements(value) WITH ORDINALITY x(val,n)),'')||']';
 ELSE RETURN value::text;END IF;
END $$;
CREATE FUNCTION fin62_history_preparation.fact(value jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 IF jsonb_typeof(value)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(value) key) IS DISTINCT FROM
  ARRAY['branchId','discountAmount','id','isRefunded','paymentType','paymentsJson','rowVersion','shiftId','totalAmount']::text[] OR
  EXISTS(SELECT 1 FROM unnest(ARRAY['totalAmount','paymentType','paymentsJson','discountAmount','rowVersion']) field WHERE jsonb_typeof(value->field) NOT IN('string','null')) THEN RAISE EXCEPTION 'FIN62_OPERATION_FACT_INVALID';END IF;
 result:=fin62_cloud_preparation.financial_fact(value);
 RETURN result||jsonb_build_object('discountAmount',CASE WHEN value->'discountAmount'='null'::jsonb THEN 0 ELSE fin62_preparation.math_decimal_text(value->>'discountAmount') END);
END $$;
CREATE FUNCTION fin62_history_preparation.snapshot_fact(value jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 -- Reuse exact shape/numeric validation but do not parse excluded refund tenders.
 result:=fin62_history_preparation.fact(CASE WHEN value->'isRefunded'='true'::jsonb THEN value||jsonb_build_object('paymentType',NULL,'paymentsJson',NULL) ELSE value END);
 IF value->'isRefunded'='true'::jsonb THEN
  IF jsonb_typeof(value->'paymentType') NOT IN('string','null') OR jsonb_typeof(value->'paymentsJson') NOT IN('string','null') THEN RAISE EXCEPTION 'FIN62_OPERATION_FACT_INVALID';END IF;
  result:=result-'paymentType'-'payments';
 END IF;
 RETURN result;
END $$;
CREATE FUNCTION fin62_history_preparation.snapshot_canonical_fact(value jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
 SELECT CASE WHEN value->'isRefunded'='true'::jsonb THEN value-'paymentType'-'payments' ELSE value END;
$$;
CREATE FUNCTION fin62_history_preparation.ensure_stream(p_org text,p_branch text,p_terminal text,p_shift uuid,p_origin jsonb) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE v_basis uuid;birth jsonb;genesis_id uuid;genesis_hash text;
BEGIN
 PERFORM fin62_rollout_preparation.assert_approved(p_org,p_branch,p_terminal);
 IF jsonb_typeof(p_origin) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'FIN62_HISTORY_ORIGIN_CONFLICT';END IF;
 IF p_origin?'serverBasisId' THEN
  IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_origin) key) IS DISTINCT FROM ARRAY['serverBasisHash','serverBasisId']::text[] THEN RAISE EXCEPTION 'FIN62_HISTORY_ORIGIN_CONFLICT';END IF;
  SELECT b.id,b.basis,b.basis_hash INTO v_basis,birth,genesis_hash FROM fin62_cloud_preparation.bases b WHERE b.id=(p_origin->>'serverBasisId')::uuid AND b.organization_id=p_org AND b.branch_id=p_branch AND b.terminal_id=p_terminal AND b.shift_id=p_shift;
  IF NOT FOUND OR genesis_hash IS DISTINCT FROM p_origin->>'serverBasisHash' THEN RAISE EXCEPTION 'FIN62_HISTORY_ORIGIN_CONFLICT';END IF;
  genesis_id:=v_basis;

 ELSE
  v_basis:=fin62_origin_preparation.resolve(p_org,p_branch,p_terminal,p_shift,p_origin);
  SELECT b.basis INTO STRICT birth FROM fin62_cloud_preparation.bases b WHERE b.id=v_basis;
  IF jsonb_array_length(birth->'inputs')<>0 THEN RAISE EXCEPTION 'FIN62_OPEN_BIRTH_NOT_EMPTY';END IF;
  genesis_id:=(p_origin->>'localAggregateId')::uuid;genesis_hash:=p_origin->>'rowHash';
 END IF;
 INSERT INTO fin62_history_preparation.protected_shifts VALUES(p_shift,p_branch) ON CONFLICT DO NOTHING;
  INSERT INTO fin62_history_preparation.streams VALUES(p_org,p_branch,p_terminal,p_shift,p_origin,v_basis,0,genesis_id,genesis_hash,'{}') ON CONFLICT DO NOTHING;
 IF FOUND THEN
  INSERT INTO fin62_history_preparation.stream_facts SELECT p_org,p_branch,p_terminal,p_shift,(item->>'id')::uuid,item FROM jsonb_array_elements(birth->'inputs') item;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM fin62_history_preparation.streams s WHERE s.organization_id=p_org AND s.branch_id=p_branch AND s.terminal_id=p_terminal AND s.shift_id=p_shift AND s.opening_origin=p_origin AND s.birth_basis_id=v_basis)
 THEN RAISE EXCEPTION 'FIN62_HISTORY_ORIGIN_CONFLICT';END IF;
END $$;
CREATE FUNCTION fin62_history_preparation.current_author(p_branch text,p_terminal text,p_proof jsonb,p_action text,p_operation uuid,p_hash text) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE v_key pos_sync_private.shift_author_keys%ROWTYPE;person public.app_users%ROWTYPE;flag text;
BEGIN
 IF jsonb_typeof(p_proof) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_proof) key) IS DISTINCT FROM
  (CASE WHEN p_action IN('ORIGINAL','RECOUNT') THEN ARRAY['action','algorithm','authorId','branchId','intentId','keyId','payloadHash','projectOrigin','shiftId','signature','subject','terminalId','version']::text[] ELSE ARRAY['action','algorithm','authorId','branchId','keyId','operationId','payloadHash','projectOrigin','signature','subject','terminalId','version']::text[] END) OR p_proof->'version' IS DISTINCT FROM '1'::jsonb OR p_proof->>'algorithm' IS DISTINCT FROM 'Ed25519' OR p_proof->>'terminalId' IS DISTINCT FROM p_terminal OR
  p_proof->>'branchId' IS DISTINCT FROM p_branch OR (CASE WHEN p_action IN('ORIGINAL','RECOUNT') THEN p_proof->>'intentId' ELSE p_proof->>'operationId' END) IS DISTINCT FROM p_operation::text OR p_proof->>'action' IS DISTINCT FROM p_action OR
  p_proof->>'payloadHash' IS DISTINCT FROM p_hash OR coalesce(p_proof->>'signature','')!~'^[A-Za-z0-9_-]{86}$'
 THEN RAISE EXCEPTION 'FIN62_HISTORY_AUTHOR_INVALID';END IF;
 SELECT * INTO v_key FROM pos_sync_private.shift_author_keys k WHERE k.key_id=(p_proof->>'keyId')::uuid FOR SHARE;
 IF NOT FOUND OR v_key.revoked_at IS NOT NULL OR v_key.terminal_id IS DISTINCT FROM p_terminal OR v_key.author_id::text IS DISTINCT FROM p_proof->>'authorId' OR
  v_key.project_origin IS DISTINCT FROM p_proof->>'projectOrigin' OR v_key.subject IS DISTINCT FROM p_proof->>'subject' THEN RAISE EXCEPTION 'FIN62_HISTORY_AUTHOR_REVOKED';END IF;
 SELECT * INTO person FROM public.app_users WHERE id=v_key.author_id FOR SHARE;
 IF NOT FOUND OR person.is_active IS DISTINCT FROM true OR person.user_id IS DISTINCT FROM v_key.subject OR (person.store_id IS NOT NULL AND person.store_id IS DISTINCT FROM p_branch)
 THEN RAISE EXCEPTION 'FIN62_HISTORY_AUTHOR_REVOKED';END IF;
 flag:=CASE p_action WHEN 'OPEN' THEN 'can_open_shift' WHEN 'SALE' THEN 'can_process_sale' WHEN 'REFUND' THEN 'can_process_refund' WHEN 'ORIGINAL' THEN 'can_shift_cash_count' WHEN 'RECOUNT' THEN 'can_shift_cash_recount' ELSE NULL END;
 IF flag IS NULL THEN RAISE EXCEPTION 'FIN62_HISTORY_UNSUPPORTED_ACTION';END IF;
 IF p_action IN('OPEN','SALE','REFUND') THEN
  IF NOT coalesce(person.permissions->flag='true'::jsonb,false) OR person.permissions->(CASE WHEN p_action='OPEN' THEN 'page:shifts' ELSE 'page:register' END)='false'::jsonb THEN RAISE EXCEPTION 'FIN62_HISTORY_PERMISSION_REVOKED';END IF;
 ELSE
  IF NOT(pos_sync_private.shift_author_flag(person.permissions,flag) OR (p_action='ORIGINAL' AND pos_sync_private.shift_author_flag(person.permissions,'can_close_shift'))) THEN RAISE EXCEPTION 'FIN62_HISTORY_PERMISSION_REVOKED';END IF;
 END IF;
END $$;
CREATE TABLE fin62_history_preparation.sale_birth_claims(sale_id uuid PRIMARY KEY,organization_id text,branch_id text NOT NULL,terminal_id text,shift_id uuid,operation_id uuid NOT NULL);
ALTER TABLE fin62_history_preparation.sale_birth_claims ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_history_preparation.sale_birth_claims FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON fin62_history_preparation.sale_birth_claims FOR EACH ROW EXECUTE FUNCTION fin62_history_preparation.immutable();CREATE TABLE fin62_history_preparation.sale_steps(
 operation_id uuid NOT NULL REFERENCES fin62_history_preparation.nodes(operation_id) DEFERRABLE INITIALLY DEFERRED,sale_id uuid NOT NULL,
 organization_id text NOT NULL,branch_id text NOT NULL,terminal_id text NOT NULL,shift_id uuid NOT NULL,sequence bigint NOT NULL,
 action text NOT NULL CHECK(action IN('SALE','REFUND')),before_fact jsonb,after_fact jsonb NOT NULL,raw_before jsonb,raw_after jsonb NOT NULL,PRIMARY KEY(operation_id,sale_id)
);
CREATE INDEX sale_steps_scope_sale ON fin62_history_preparation.sale_steps(organization_id,branch_id,shift_id,sale_id,terminal_id);
CREATE INDEX sale_steps_scope_sequence ON fin62_history_preparation.sale_steps(organization_id,branch_id,terminal_id,shift_id,sequence,sale_id);
ALTER TABLE fin62_history_preparation.sale_steps ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_history_preparation.sale_steps FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON fin62_history_preparation.sale_steps FOR EACH ROW EXECUTE FUNCTION fin62_history_preparation.immutable();CREATE FUNCTION public.pos_sync_register_financial_event(p_org text,p_branch text,p_terminal text,p_raw text,p_proof jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $fn$
DECLARE event jsonb;digest text;sid uuid;op uuid;n bigint;head fin62_history_preparation.streams%ROWTYPE;prior fin62_history_preparation.nodes%ROWTYPE;
 change jsonb;current_value jsonb;before_value jsonb;after_value jsonb;before_fact jsonb;after_fact jsonb;identifier text;ack jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_SERVICE_REQUIRED';END IF;
 PERFORM public.pos_sync_validate_scope(p_org,p_branch,p_terminal);
 IF p_raw IS NULL OR octet_length(p_raw)>6*1024*1024 THEN RAISE EXCEPTION 'FIN62_HISTORY_LIMIT';END IF;
 PERFORM fin62_preparation.math_unique_json(p_raw::json,48);event:=p_raw::jsonb;
 IF jsonb_typeof(event)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(event) key) IS DISTINCT FROM
  (CASE WHEN event->'version'='2'::jsonb THEN ARRAY['action','branchId','changes','cloudOrigin','operationId','predecessorHash','predecessorOperationId','sequence','shiftId','terminalId','version']::text[] ELSE ARRAY['action','branchId','changes','openingOrigin','operationId','predecessorHash','predecessorOperationId','sequence','shiftId','terminalId','version']::text[] END) OR event->'version' NOT IN('1'::jsonb,'2'::jsonb) OR
  event->>'branchId' IS DISTINCT FROM p_branch OR event->>'terminalId' IS DISTINCT FROM p_terminal OR jsonb_typeof(event->'sequence') IS DISTINCT FROM 'string' OR
  coalesce(event->>'sequence','')!~'^[1-9][0-9]{0,18}$' OR jsonb_typeof(event->'changes') IS DISTINCT FROM 'array' OR jsonb_array_length(event->'changes') NOT BETWEEN 1 AND 500
 THEN RAISE EXCEPTION 'FIN62_HISTORY_EVENT_INVALID';END IF;
 op:=(event->>'operationId')::uuid;sid:=(event->>'shiftId')::uuid;n:=(event->>'sequence')::bigint;
 IF op IS NULL OR sid IS NULL OR n::text IS DISTINCT FROM event->>'sequence' THEN RAISE EXCEPTION 'FIN62_HISTORY_EVENT_INVALID';END IF;
 digest:=encode(sha256(convert_to(p_raw,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('fin62-history-node:'||op::text,0));
 SELECT * INTO prior FROM fin62_history_preparation.nodes WHERE operation_id=op;
 IF FOUND THEN
  IF prior.node_kind<>'MUTATION' OR ROW(prior.organization_id,prior.branch_id,prior.terminal_id,prior.shift_id,prior.sequence,prior.payload_hash) IS DISTINCT FROM ROW(p_org,p_branch,p_terminal,sid,n,digest) OR
   convert_to(prior.payload_json,'UTF8') IS DISTINCT FROM convert_to(p_raw,'UTF8') OR prior.proof IS DISTINCT FROM p_proof THEN RAISE EXCEPTION 'FIN62_HISTORY_REPLAY_MISMATCH';END IF;
  RETURN prior.acknowledgement; -- No new write, no permission revival.
 END IF;
 PERFORM fin62_history_preparation.current_author(p_branch,p_terminal,p_proof,event->>'action',op,digest);
 PERFORM fin62_history_preparation.ensure_stream(p_org,p_branch,p_terminal,sid,coalesce(event->'openingOrigin',event->'cloudOrigin'));
 SELECT * INTO STRICT head FROM fin62_history_preparation.streams s WHERE s.organization_id=p_org AND s.branch_id=p_branch AND s.terminal_id=p_terminal AND s.shift_id=sid FOR UPDATE;
 IF n<>head.sequence+1 OR event->>'predecessorOperationId' IS DISTINCT FROM head.operation_id::text OR event->>'predecessorHash' IS DISTINCT FROM head.payload_hash THEN RAISE EXCEPTION 'FIN62_HISTORY_GAP_OR_CONFLICT';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(event->'changes') x GROUP BY x->>'saleId' HAVING count(*)>1) THEN RAISE EXCEPTION 'FIN62_HISTORY_EVENT_INVALID';END IF;

 FOR change IN SELECT value FROM jsonb_array_elements(event->'changes') ORDER BY value->>'saleId' LOOP
  IF jsonb_typeof(change)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(change) key) IS DISTINCT FROM ARRAY['after','before','saleId']::text[] THEN RAISE EXCEPTION 'FIN62_HISTORY_EVENT_INVALID';END IF;
  identifier:=(change->>'saleId')::uuid::text;IF identifier IS NULL THEN RAISE EXCEPTION 'FIN62_HISTORY_EVENT_INVALID';END IF;
  before_value:=nullif(change->'before','null'::jsonb);after_value:=nullif(change->'after','null'::jsonb);
  SELECT fact INTO current_value FROM fin62_history_preparation.stream_facts WHERE organization_id=p_org AND branch_id=p_branch AND terminal_id=p_terminal AND shift_id=sid AND sale_id=identifier::uuid FOR UPDATE;
  before_fact:=fin62_history_preparation.fact(before_value);after_fact:=fin62_history_preparation.fact(after_value);
  IF before_fact IS DISTINCT FROM fin62_history_preparation.fact(current_value) OR after_fact IS NULL OR
   after_fact->>'id' IS DISTINCT FROM identifier OR after_fact->>'branchId' IS DISTINCT FROM fin62_cloud_preparation.fact_identity(p_branch) OR after_fact->>'shiftId' IS DISTINCT FROM sid::text
  THEN RAISE EXCEPTION 'FIN62_HISTORY_BEFORE_OR_SCOPE_MISMATCH';END IF;
  IF event->>'action'='SALE' THEN
   IF before_value IS NOT NULL OR coalesce((after_fact->>'isRefunded')::boolean,false) THEN RAISE EXCEPTION 'FIN62_HISTORY_FIELD_POLICY';END IF;   IF EXISTS(SELECT 1 FROM public.sales s WHERE s.id=identifier::uuid) THEN RAISE EXCEPTION 'FIN62_SALE_BIRTH_ALREADY_EXISTS';END IF;
   INSERT INTO fin62_history_preparation.sale_birth_claims VALUES(identifier::uuid,p_org,p_branch,p_terminal,sid,op) ON CONFLICT DO NOTHING;
   IF NOT FOUND THEN RAISE EXCEPTION 'FIN62_SALE_BIRTH_ALREADY_CLAIMED';END IF;
  ELSIF event->>'action'='REFUND' THEN
   IF before_fact IS NULL OR coalesce((before_fact->>'isRefunded')::boolean,false) OR after_fact->'isRefunded' IS DISTINCT FROM 'true'::jsonb OR (before_fact-'isRefunded') IS DISTINCT FROM (after_fact-'isRefunded') THEN RAISE EXCEPTION 'FIN62_HISTORY_FIELD_POLICY';END IF;
  ELSE RAISE EXCEPTION 'FIN62_HISTORY_UNSUPPORTED_ACTION';END IF;
  INSERT INTO fin62_history_preparation.sale_steps VALUES(op,identifier::uuid,p_org,p_branch,p_terminal,sid,n,event->>'action',before_fact,after_fact,before_value,after_value);
  INSERT INTO fin62_history_preparation.stream_facts VALUES(p_org,p_branch,p_terminal,sid,identifier::uuid,after_value)
  ON CONFLICT(organization_id,branch_id,terminal_id,shift_id,sale_id) DO UPDATE SET fact=EXCLUDED.fact WHERE fin62_history_preparation.stream_facts.fact IS DISTINCT FROM EXCLUDED.fact;
 END LOOP;

 ack:=jsonb_build_object('status','financial_metadata_recorded','operationId',op,'payloadHash',digest,'sequence',n::text,'businessUploaded',false,'shiftClosed',false);
 INSERT INTO fin62_history_preparation.nodes(operation_id,organization_id,branch_id,terminal_id,shift_id,sequence,node_kind,payload_json,payload_hash,proof,acknowledgement)
 VALUES(op,p_org,p_branch,p_terminal,sid,n,'MUTATION',p_raw,digest,p_proof,ack);
 UPDATE fin62_history_preparation.streams SET sequence=n,operation_id=op,payload_hash=digest WHERE organization_id=p_org AND branch_id=p_branch AND terminal_id=p_terminal AND shift_id=sid;
 RETURN ack;
END $fn$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA fin62_history_preparation FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.pos_sync_register_financial_event(text,text,text,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pos_sync_register_financial_event(text,text,text,text,jsonb) TO service_role;

CREATE FUNCTION fin62_history_preparation.check_frontier(p_org text,p_branch text,p_terminal text,p_shift uuid,p_origin jsonb,p_raw_basis text)
RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $fn$
DECLARE basis jsonb;frontier jsonb;head fin62_history_preparation.streams%ROWTYPE;computed jsonb;birth jsonb;item jsonb;
BEGIN
 PERFORM fin62_history_preparation.ensure_stream(p_org,p_branch,p_terminal,p_shift,p_origin);
 SELECT * INTO STRICT head FROM fin62_history_preparation.streams s WHERE s.organization_id=p_org AND s.branch_id=p_branch AND s.terminal_id=p_terminal AND s.shift_id=p_shift FOR UPDATE;
 computed:=fin62_preparation.validate_financial_math_text(p_raw_basis);
 IF computed->>'status' IS DISTINCT FROM 'computed' THEN RAISE EXCEPTION 'FIN62_HISTORY_BASIS_UNSUPPORTED';END IF;
 basis:=p_raw_basis::jsonb;frontier:=basis->'financialFrontier';
 IF basis->>'branchId' IS DISTINCT FROM p_branch OR basis->>'shiftId' IS DISTINCT FROM p_shift::text OR jsonb_typeof(frontier) IS DISTINCT FROM 'object' OR
  (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(frontier) key) IS DISTINCT FROM (CASE WHEN p_origin?'serverBasisId' THEN ARRAY['cloudOrigin','hash','operationId','reservedSequence','sequence']::text[] ELSE ARRAY['hash','openingOrigin','operationId','reservedSequence','sequence']::text[] END) OR
  coalesce(frontier->'openingOrigin',frontier->'cloudOrigin') IS DISTINCT FROM p_origin OR jsonb_typeof(frontier->'sequence') IS DISTINCT FROM 'string' OR jsonb_typeof(frontier->'reservedSequence') IS DISTINCT FROM 'string' OR
  frontier->>'sequence' IS DISTINCT FROM head.sequence::text OR frontier->>'reservedSequence' IS DISTINCT FROM (head.sequence+1)::text OR
  frontier->>'operationId' IS DISTINCT FROM head.operation_id::text OR frontier->>'hash' IS DISTINCT FROM head.payload_hash
 THEN RAISE EXCEPTION 'FIN62_HISTORY_FRONTIER_GAP_OR_CONFLICT';END IF;
 SELECT b.basis INTO STRICT birth FROM fin62_cloud_preparation.bases b WHERE b.id=head.birth_basis_id;
 IF (CASE WHEN basis->'openingFloat'='null'::jsonb THEN 0 ELSE fin62_preparation.math_decimal_text(basis->>'openingFloat') END)
  IS DISTINCT FROM (CASE WHEN birth->'openingFloat'='null'::jsonb THEN 0 ELSE fin62_preparation.math_decimal_text(birth->>'openingFloat') END)
 THEN RAISE EXCEPTION 'FIN62_HISTORY_OPENING_MISMATCH';END IF;
 IF jsonb_array_length(basis->'inputs')<>(SELECT count(*) FROM fin62_history_preparation.stream_facts f WHERE f.organization_id=p_org AND f.branch_id=p_branch AND f.terminal_id=p_terminal AND f.shift_id=p_shift) THEN RAISE EXCEPTION 'FIN62_HISTORY_SNAPSHOT_INCOMPLETE';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(basis->'inputs') LOOP
  IF fin62_history_preparation.snapshot_fact(item) IS DISTINCT FROM fin62_history_preparation.snapshot_fact((SELECT f.fact FROM fin62_history_preparation.stream_facts f WHERE f.organization_id=p_org AND f.branch_id=p_branch AND f.terminal_id=p_terminal AND f.shift_id=p_shift AND f.sale_id=(item->>'id')::uuid)) THEN RAISE EXCEPTION 'FIN62_HISTORY_SNAPSHOT_INCOMPLETE';END IF;
 END LOOP;
 RETURN computed||jsonb_build_object('reservedSequence',(head.sequence+1)::text,'predecessorOperationId',head.operation_id,'predecessorHash',head.payload_hash);
END $fn$;
CREATE FUNCTION public.pos_sync_register_financial_boundary(p_org text,p_branch text,p_terminal text,p_raw_graph text,p_graph_author jsonb,p_financial_basis jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $fn$
DECLARE graph jsonb;basis jsonb;proof jsonb;raw_basis text;graph_hash text;basis_hash text;sid uuid;op uuid;frontier jsonb;computed jsonb;
 parent jsonb;field text;value numeric;head fin62_history_preparation.streams%ROWTYPE;prior fin62_history_preparation.nodes%ROWTYPE;payload jsonb;payload_text text;digest text;ack jsonb;validation_graph jsonb;operation_part jsonb;submitted jsonb;total_rows integer:=0;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_SERVICE_REQUIRED';END IF;
 PERFORM public.pos_sync_validate_scope(p_org,p_branch,p_terminal);
 IF p_raw_graph IS NULL OR octet_length(p_raw_graph)>6*1024*1024 OR jsonb_typeof(p_financial_basis) IS DISTINCT FROM 'object' OR
  (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_financial_basis) key) IS DISTINCT FROM ARRAY['basisJson','proof']::text[] OR jsonb_typeof(p_financial_basis->'basisJson') IS DISTINCT FROM 'string'
 THEN RAISE EXCEPTION 'FIN62_HISTORY_BOUNDARY_INVALID';END IF;
 PERFORM fin62_preparation.math_unique_json(p_raw_graph::json,48);graph:=p_raw_graph::jsonb;raw_basis:=p_financial_basis->>'basisJson';
 IF octet_length(raw_basis)>6*1024*1024 THEN RAISE EXCEPTION 'FIN62_HISTORY_LIMIT';END IF;
 PERFORM fin62_preparation.math_unique_json(raw_basis::json,48);basis:=raw_basis::jsonb;proof:=p_financial_basis->'proof';
 graph_hash:=encode(sha256(convert_to(p_raw_graph,'UTF8')),'hex');basis_hash:=encode(sha256(convert_to(raw_basis,'UTF8')),'hex');
 op:=(graph->>'intentId')::uuid;sid:=(graph->>'shiftId')::uuid;
 IF op IS NULL OR sid IS NULL OR graph->>'branchId' IS DISTINCT FROM p_branch OR graph->>'kind' NOT IN('ORIGINAL','RECOUNT') OR
  p_graph_author->>'shiftId' IS DISTINCT FROM sid::text OR proof->>'shiftId' IS DISTINCT FROM sid::text OR proof->>'graphPayloadHash' IS DISTINCT FROM graph_hash OR
  proof->>'basisHash' IS DISTINCT FROM basis_hash OR proof->>'formula' IS DISTINCT FROM 'canonical-exact-decimal-v2' OR
  (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(proof) key) IS DISTINCT FROM
  (CASE WHEN proof?'serverBasisId' THEN ARRAY['action','algorithm','authorId','basisHash','branchId','formula','graphPayloadHash','intentId','keyId','projectOrigin','serverBasisId','shiftId','signature','subject','terminalId','version']::text[] ELSE ARRAY['action','algorithm','authorId','basisHash','branchId','formula','graphPayloadHash','intentId','keyId','openingOrigin','projectOrigin','shiftId','signature','subject','terminalId','version']::text[] END) OR
  coalesce(proof->>'signature','')!~'^[A-Za-z0-9_-]{86}$'
 THEN RAISE EXCEPTION 'FIN62_HISTORY_BOUNDARY_INVALID';END IF;
 FOREACH field IN ARRAY ARRAY['version','algorithm','keyId','projectOrigin','terminalId','authorId','subject','branchId','shiftId','intentId','action'] LOOP
  IF proof->field IS DISTINCT FROM p_graph_author->field THEN RAISE EXCEPTION 'FIN62_HISTORY_AUTHOR_BINDING_MISMATCH';END IF;
 END LOOP;
 IF p_graph_author->>'payloadHash' IS DISTINCT FROM graph_hash THEN RAISE EXCEPTION 'FIN62_HISTORY_AUTHOR_BINDING_MISMATCH';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('fin62-history-node:'||op::text,0));
 SELECT * INTO prior FROM fin62_history_preparation.nodes WHERE operation_id=op;
 IF FOUND THEN
  IF prior.node_kind<>'CLOSE_BOUNDARY' OR ROW(prior.organization_id,prior.branch_id,prior.terminal_id,prior.shift_id,prior.graph_hash,prior.basis_hash) IS DISTINCT FROM ROW(p_org,p_branch,p_terminal,sid,graph_hash,basis_hash) OR
   convert_to(prior.graph_json,'UTF8') IS DISTINCT FROM convert_to(p_raw_graph,'UTF8') OR convert_to(prior.basis_json,'UTF8') IS DISTINCT FROM convert_to(raw_basis,'UTF8') OR prior.proof IS DISTINCT FROM proof OR prior.graph_author IS DISTINCT FROM p_graph_author
  THEN RAISE EXCEPTION 'FIN62_HISTORY_REPLAY_MISMATCH';END IF;
  RETURN prior.acknowledgement;
 END IF;
 PERFORM fin62_history_preparation.current_author(p_branch,p_terminal,p_graph_author,graph->>'kind',op,graph_hash);
 computed:=fin62_history_preparation.check_frontier(p_org,p_branch,p_terminal,sid,coalesce(proof->'openingOrigin',basis->'financialFrontier'->'cloudOrigin'),raw_basis);
 -- Existing actual graph validation checks links/count math/branch consistency,
 -- but metadata registration never invokes a shift mutation or graph receipt.
 -- Main freezes operations in registry dependency order, not validator order.
 -- Build only an ordered validation view; the original signed bytes/hash and
 -- complete optional variance activity remain immutable in the receipt.
 IF jsonb_typeof(graph->'operations') IS DISTINCT FROM 'array' OR jsonb_array_length(graph->'operations') NOT IN(6,7) OR
  (SELECT count(DISTINCT x.value->>'table') FROM jsonb_array_elements(graph->'operations') x)<>jsonb_array_length(graph->'operations') OR
  EXISTS(SELECT 1 FROM jsonb_array_elements(graph->'operations') x WHERE x->>'table' IS NULL OR x->>'table'<>ALL(ARRAY['shifts','shift_cash_counts','shift_reconciliations','shift_close_events','shift_notifications','shift_variance_alerts','activity_events']) OR coalesce((x->>'deletePhase')::boolean,false) OR jsonb_typeof(x->'rows') IS DISTINCT FROM 'array' OR coalesce(x->'changes','[]'::jsonb)<>'[]'::jsonb)
 THEN RAISE EXCEPTION 'FIN62_HISTORY_BOUNDARY_INVALID';END IF;
 FOREACH field IN ARRAY ARRAY['shifts','shift_cash_counts','shift_reconciliations','shift_close_events','shift_notifications','shift_variance_alerts'] LOOP
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(graph->'operations') x WHERE x->>'table'=field) THEN RAISE EXCEPTION 'FIN62_HISTORY_BOUNDARY_INVALID';END IF;
 END LOOP;
 FOR operation_part IN SELECT x.value FROM jsonb_array_elements(graph->'operations') x LOOP
  total_rows:=total_rows+jsonb_array_length(operation_part->'rows');
  IF total_rows>2000 OR (SELECT count(*)<>count(DISTINCT x.value->>'id') FROM jsonb_array_elements(operation_part->'rows') x) THEN RAISE EXCEPTION 'SYNC_SHIFT_GRAPH_DUPLICATE';END IF;
  FOR submitted IN SELECT x.value FROM jsonb_array_elements(operation_part->'rows') x LOOP
   IF lower(btrim(submitted->>'store_id')) IS DISTINCT FROM lower(btrim(p_branch)) OR (submitted?'branch_id' AND lower(btrim(submitted->>'branch_id')) IS DISTINCT FROM lower(btrim(p_branch))) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN';END IF;
   IF operation_part->>'table'='activity_events' AND (submitted->>'event_type' IS DISTINCT FROM 'shift_cash_variance' OR submitted->>'entity_type' IS DISTINCT FROM 'shift' OR (submitted->>'entity_id')::uuid IS DISTINCT FROM sid OR lower(btrim(submitted->>'branch_id')) IS DISTINCT FROM lower(btrim(p_branch))) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN';END IF;
  END LOOP;
 END LOOP;
 SELECT jsonb_agg(jsonb_build_object('table',name,'rows',(SELECT jsonb_agg(row_value||jsonb_build_object('store_id',p_branch,'id',(row_value->>'id')::uuid::text)||CASE WHEN name='shifts' THEN '{}'::jsonb ELSE jsonb_build_object('shift_id',(row_value->>'shift_id')::uuid::text) END) FROM jsonb_array_elements((SELECT x->'rows' FROM jsonb_array_elements(graph->'operations') x WHERE x->>'table'=name)) row_value)) ORDER BY ordinal)
 INTO validation_graph FROM unnest(ARRAY['shifts','shift_cash_counts','shift_reconciliations','shift_close_events','shift_notifications','shift_variance_alerts']) WITH ORDINALITY names(name,ordinal);
 -- Empty child arrays remain arrays rather than SQL NULL in this view.
 SELECT jsonb_agg(jsonb_set(x,'{rows}',coalesce(nullif(x->'rows','null'::jsonb),'[]'::jsonb)) ORDER BY ordinal) INTO validation_graph FROM jsonb_array_elements(validation_graph) WITH ORDINALITY parts(x,ordinal);
 PERFORM pos_sync_private.validate_graph(validation_graph,p_branch,sid,true);
 SELECT row_value INTO parent FROM jsonb_array_elements(graph->'operations') part,LATERAL jsonb_array_elements(part->'rows') row_value WHERE part->>'table'='shifts';
 FOREACH field IN ARRAY ARRAY['cash','card','digital'] LOOP
  IF NOT parent?('expected_'||field) OR jsonb_typeof(parent->('expected_'||field)) NOT IN('number','string') THEN RAISE EXCEPTION 'FIN62_HISTORY_EXPECTED_MISMATCH';END IF;
  value:=fin62_preparation.math_decimal_text(parent->>('expected_'||field));
  IF value IS DISTINCT FROM fin62_preparation.math_decimal_text(computed->'expected'->>field) THEN RAISE EXCEPTION 'FIN62_HISTORY_EXPECTED_MISMATCH';END IF;
 END LOOP;
 SELECT * INTO STRICT head FROM fin62_history_preparation.streams s WHERE s.organization_id=p_org AND s.branch_id=p_branch AND s.terminal_id=p_terminal AND s.shift_id=sid FOR UPDATE;
 IF proof?'serverBasisId' AND proof->>'serverBasisId' IS DISTINCT FROM head.birth_basis_id::text THEN RAISE EXCEPTION 'FIN62_HISTORY_ORIGIN_CONFLICT';END IF;
 payload:=jsonb_build_object(CASE WHEN head.opening_origin?'serverBasisId' THEN 'cloudOrigin' ELSE 'openingOrigin' END,head.opening_origin,'sequence',(head.sequence+1)::text,'predecessorOperationId',head.operation_id,'predecessorHash',head.payload_hash,
  'intentId',op,'graphPayloadHash',graph_hash,'basisHash',basis_hash);
 payload_text:=fin62_history_preparation.canonical_json(payload);digest:=encode(sha256(convert_to(payload_text,'UTF8')),'hex');
 ack:=jsonb_build_object('status','boundary_registered_not_shift_closed','operationId',op,'payloadHash',digest,'sequence',(head.sequence+1)::text,
  'graphPayloadHash',graph_hash,'basisHash',basis_hash,'businessUploaded',false,'shiftClosed',false);
 INSERT INTO fin62_history_preparation.nodes(operation_id,organization_id,branch_id,terminal_id,shift_id,sequence,node_kind,payload_json,payload_hash,proof,graph_json,graph_author,basis_json,graph_hash,basis_hash,acknowledgement)
 VALUES(op,p_org,p_branch,p_terminal,sid,head.sequence+1,'CLOSE_BOUNDARY',payload_text,digest,proof,p_raw_graph,p_graph_author,raw_basis,graph_hash,basis_hash,ack);
 UPDATE fin62_history_preparation.streams SET sequence=head.sequence+1,operation_id=op,payload_hash=digest WHERE organization_id=p_org AND branch_id=p_branch AND terminal_id=p_terminal AND shift_id=sid;
 RETURN ack;
END $fn$;
-- Source alias protection preparation. There is intentionally NO activation API
-- or privileged-context issuer until web and every native financial alias are
-- integrated. Owner-only fixtures may add protected scopes to prove bypass deny.
CREATE TABLE fin62_history_preparation.protected_shifts(shift_id uuid PRIMARY KEY,branch_id text NOT NULL);
ALTER TABLE fin62_history_preparation.protected_shifts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_history_preparation.protected_shifts FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION fin62_history_preparation.block_unintegrated_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE sid text;branch text;
BEGIN
 IF TG_OP='DELETE' THEN sid:=OLD.shift_id;branch:=OLD.store_id;ELSE sid:=NEW.shift_id;branch:=NEW.store_id;END IF;
 IF EXISTS(SELECT 1 FROM fin62_history_preparation.protected_shifts p WHERE p.shift_id::text=sid AND p.branch_id=branch) OR
  (TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM fin62_history_preparation.protected_shifts p WHERE p.shift_id::text=OLD.shift_id AND p.branch_id=OLD.store_id))
 THEN RAISE EXCEPTION 'FIN62_FINANCIAL_ALIAS_NOT_INTEGRATED';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;
END $$;
CREATE TRIGGER prototype_fin62_financial_write_guard BEFORE INSERT OR UPDATE OR DELETE ON public.sales FOR EACH ROW EXECUTE FUNCTION fin62_history_preparation.block_unintegrated_write();
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA fin62_history_preparation FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.pos_sync_register_financial_boundary(text,text,text,text,jsonb,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pos_sync_register_financial_boundary(text,text,text,text,jsonb,jsonb) TO service_role;
-- Actual guarded OPEN adapter. Proof crypto remains the existing HTTP service
-- admission precondition; SQL independently checks exact envelope/key/person.
CREATE TABLE fin62_history_preparation.open_author_receipts(
 local_aggregate_id uuid PRIMARY KEY,organization_id text NOT NULL,branch_id text NOT NULL,terminal_id text NOT NULL,
 envelope_json text NOT NULL,proof jsonb NOT NULL,acknowledgement jsonb NOT NULL
);
ALTER TABLE fin62_history_preparation.open_author_receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_history_preparation.open_author_receipts FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON fin62_history_preparation.open_author_receipts FOR EACH ROW EXECUTE FUNCTION fin62_history_preparation.immutable();
CREATE FUNCTION public.pos_sync_register_financial_open(p_batch uuid,p_org text,p_branch text,p_terminal text,p_local_aggregate uuid,p_opening_json text,p_row_hash text,p_operations jsonb,p_opening_envelope text,p_proof jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $fn$
DECLARE envelope jsonb;prior fin62_history_preparation.open_author_receipts%ROWTYPE;ack jsonb;digest text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_SERVICE_REQUIRED';END IF;
 PERFORM public.pos_sync_validate_scope(p_org,p_branch,p_terminal);
 IF p_opening_envelope IS NULL OR octet_length(p_opening_envelope)>6*1024*1024 THEN RAISE EXCEPTION 'FIN62_HISTORY_OPEN_INVALID';END IF;
 PERFORM fin62_preparation.math_unique_json(p_opening_envelope::json,48);envelope:=p_opening_envelope::jsonb;
 IF jsonb_typeof(envelope) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(envelope) key) IS DISTINCT FROM
  ARRAY['branchId','localAggregateId','rowHash','rowJson','shiftId','terminalId','version']::text[] OR envelope->'version' IS DISTINCT FROM '1'::jsonb OR
  envelope->>'branchId' IS DISTINCT FROM p_branch OR envelope->>'terminalId' IS DISTINCT FROM p_terminal OR envelope->>'localAggregateId' IS DISTINCT FROM p_local_aggregate::text OR
  envelope->>'rowHash' IS DISTINCT FROM p_row_hash OR convert_to(envelope->>'rowJson','UTF8') IS DISTINCT FROM convert_to(p_opening_json,'UTF8') OR
  envelope->>'shiftId' IS DISTINCT FROM (p_opening_json::jsonb)->>'id'
 THEN RAISE EXCEPTION 'FIN62_HISTORY_OPEN_INVALID';END IF;
 digest:=encode(sha256(convert_to(p_opening_envelope,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('fin62-history-open:'||p_local_aggregate::text,0));
 SELECT * INTO prior FROM fin62_history_preparation.open_author_receipts WHERE local_aggregate_id=p_local_aggregate;
 IF FOUND THEN
  IF ROW(prior.organization_id,prior.branch_id,prior.terminal_id) IS DISTINCT FROM ROW(p_org,p_branch,p_terminal) OR
   convert_to(prior.envelope_json,'UTF8') IS DISTINCT FROM convert_to(p_opening_envelope,'UTF8') OR prior.proof IS DISTINCT FROM p_proof
  THEN RAISE EXCEPTION 'FIN62_HISTORY_REPLAY_MISMATCH';END IF;
  -- Underlying exact origin replay also compares batch/operations/raw row and
  -- cannot reopen an already closed shift or manufacture a new birth.
  PERFORM public.prototype_fin62_push_open_origin(p_batch,p_org,p_branch,p_terminal,p_local_aggregate,p_opening_json,p_row_hash,p_operations);
  RETURN prior.acknowledgement;
 END IF;
 PERFORM fin62_rollout_preparation.assert_approved(p_org,p_branch,p_terminal);
 PERFORM fin62_history_preparation.current_author(p_branch,p_terminal,p_proof,'OPEN',p_local_aggregate,digest);
 ack:=public.prototype_fin62_push_open_origin(p_batch,p_org,p_branch,p_terminal,p_local_aggregate,p_opening_json,p_row_hash,p_operations);
 INSERT INTO fin62_history_preparation.protected_shifts VALUES((envelope->>'shiftId')::uuid,p_branch) ON CONFLICT DO NOTHING;
 INSERT INTO fin62_history_preparation.open_author_receipts VALUES(p_local_aggregate,p_org,p_branch,p_terminal,p_opening_envelope,p_proof,ack);
 RETURN ack;
END $fn$;
REVOKE ALL ON FUNCTION public.pos_sync_register_financial_open(uuid,text,text,text,uuid,text,text,jsonb,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pos_sync_register_financial_open(uuid,text,text,text,uuid,text,text,jsonb,text,jsonb) TO service_role;
CREATE TABLE fin62_history_preparation.business_context(pid integer NOT NULL,xid xid8 NOT NULL,organization_id text NOT NULL,branch_id text NOT NULL,terminal_id text NOT NULL,PRIMARY KEY(pid,xid));
CREATE TABLE fin62_history_preparation.business_receipts(batch_id uuid PRIMARY KEY,organization_id text NOT NULL,branch_id text NOT NULL,terminal_id text NOT NULL,operations jsonb NOT NULL,acknowledgement jsonb NOT NULL);
ALTER TABLE fin62_history_preparation.business_context ENABLE ROW LEVEL SECURITY;
ALTER TABLE fin62_history_preparation.business_receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_history_preparation.business_context,fin62_history_preparation.business_receipts FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON fin62_history_preparation.business_receipts FOR EACH ROW EXECUTE FUNCTION fin62_history_preparation.immutable();
CREATE TABLE fin62_history_preparation.publications(
 batch_id uuid NOT NULL REFERENCES fin62_history_preparation.business_receipts(batch_id),sale_id uuid NOT NULL,
 organization_id text NOT NULL,branch_id text NOT NULL,terminal_id text NOT NULL,shift_id uuid NOT NULL,financial_fact jsonb NOT NULL,
 stream_sequence bigint NOT NULL,capture_xid xid8 NOT NULL,evidence_order bigint NOT NULL,
 PRIMARY KEY(batch_id,sale_id)
);
CREATE INDEX publications_scope_sale ON fin62_history_preparation.publications(organization_id,branch_id,shift_id,sale_id,terminal_id);
ALTER TABLE fin62_history_preparation.publications ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_history_preparation.publications FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON fin62_history_preparation.publications FOR EACH ROW EXECUTE FUNCTION fin62_history_preparation.immutable();CREATE FUNCTION fin62_history_preparation.row_fact(p_row jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
 SELECT fin62_history_preparation.fact(fin62_version_preparation.basis(p_row)||jsonb_build_object('discountAmount',p_row->>'discount_amount'));
$$;
CREATE FUNCTION fin62_history_preparation.row_snapshot_fact(p_row jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
 SELECT fin62_history_preparation.snapshot_fact(fin62_version_preparation.basis(p_row)||jsonb_build_object('discountAmount',p_row->>'discount_amount'));
$$;CREATE TABLE fin62_history_preparation.live_context(pid integer NOT NULL,xid xid8 NOT NULL,branch_id text NOT NULL,shift_id uuid,sale_id uuid NOT NULL,author_id uuid NOT NULL,action text NOT NULL CHECK(action IN('SALE','REFUND')),PRIMARY KEY(pid,xid));
ALTER TABLE fin62_history_preparation.live_context ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_history_preparation.live_context FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION fin62_history_preparation.live_row_allowed(p_operation text,p_old jsonb,p_new jsonb) RETURNS boolean LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE scope fin62_history_preparation.live_context%ROWTYPE;before_fact jsonb;after_fact jsonb;
BEGIN
 SELECT * INTO scope FROM fin62_history_preparation.live_context WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id();
 IF NOT FOUND OR p_operation='DELETE' OR p_new->>'store_id' IS DISTINCT FROM scope.branch_id THEN RETURN false;END IF;
 IF p_operation='INSERT' THEN
  RETURN scope.action='SALE' AND p_new->>'id'=scope.sale_id::text AND p_new->>'shift_id' IS NOT DISTINCT FROM scope.shift_id::text;
 END IF;
 IF ROW(p_old->>'store_id',p_old->>'shift_id') IS DISTINCT FROM ROW(p_new->>'store_id',p_new->>'shift_id') THEN RETURN false;END IF;
 before_fact:=fin62_history_preparation.row_fact(p_old);after_fact:=fin62_history_preparation.row_fact(p_new);
 IF scope.action='SALE' THEN RETURN before_fact IS NOT DISTINCT FROM after_fact;END IF;
 RETURN scope.action='REFUND' AND p_new->>'id'=scope.sale_id::text AND p_new->>'shift_id' IS NOT DISTINCT FROM scope.shift_id::text AND
  (before_fact-'isRefunded') IS NOT DISTINCT FROM (after_fact-'isRefunded') AND NOT(coalesce((before_fact->>'isRefunded')::boolean,false) AND NOT coalesce((after_fact->>'isRefunded')::boolean,false));
END $$;
REVOKE ALL ON FUNCTION fin62_history_preparation.live_row_allowed(text,jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;CREATE OR REPLACE FUNCTION fin62_history_preparation.block_unintegrated_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE sid text;b text;protected boolean:=false;scope fin62_history_preparation.business_context%ROWTYPE;desired jsonb;
BEGIN
 IF TG_OP='DELETE' THEN sid:=OLD.shift_id;b:=OLD.store_id;ELSE sid:=NEW.shift_id;b:=NEW.store_id;END IF;
 SELECT EXISTS(SELECT 1 FROM fin62_history_preparation.protected_shifts p WHERE p.shift_id::text=sid AND p.branch_id=b) INTO protected;
 IF TG_OP='UPDATE' THEN protected:=protected OR EXISTS(SELECT 1 FROM fin62_history_preparation.protected_shifts p WHERE p.shift_id::text=OLD.shift_id AND p.branch_id=OLD.store_id);END IF;
 IF NOT protected THEN IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;END IF;
 IF fin62_history_preparation.live_row_allowed(TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END) THEN RETURN NEW;END IF;
 SELECT * INTO scope FROM fin62_history_preparation.business_context WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id();
 IF NOT FOUND OR scope.branch_id IS DISTINCT FROM b OR TG_OP='DELETE' THEN RAISE EXCEPTION 'FIN62_FINANCIAL_ALIAS_NOT_INTEGRATED';END IF;
 SELECT s.fact INTO desired FROM fin62_history_preparation.stream_facts s WHERE s.organization_id=scope.organization_id AND s.branch_id=scope.branch_id AND s.terminal_id=scope.terminal_id AND s.shift_id::text=sid AND s.sale_id=NEW.id;
 IF desired IS NULL OR fin62_history_preparation.row_snapshot_fact(to_jsonb(NEW)) IS DISTINCT FROM fin62_history_preparation.snapshot_fact(desired) THEN RAISE EXCEPTION 'FIN62_FINANCIAL_PROJECTION_MISMATCH';END IF;
 IF TG_OP='UPDATE' AND ROW(OLD.shift_id,OLD.store_id) IS DISTINCT FROM ROW(NEW.shift_id,NEW.store_id) THEN RAISE EXCEPTION 'FIN62_FINANCIAL_SCOPE_IMMUTABLE';END IF;
 RETURN NEW;
END $$;
CREATE FUNCTION public.pos_sync_push_financial_business_aggregate(p_batch uuid,p_org text,p_branch text,p_terminal text,p_operations jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $fn$
DECLARE prior fin62_history_preparation.business_receipts%ROWTYPE;part jsonb;r jsonb;sid uuid;sale uuid;head fin62_history_preparation.streams%ROWTYPE;stored jsonb;cursor_fact jsonb;target jsonb;node record;change jsonb;ack jsonb;started boolean;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_SERVICE_REQUIRED';END IF;
 PERFORM public.pos_sync_validate_scope(p_org,p_branch,p_terminal);
 IF p_batch IS NULL OR jsonb_typeof(p_operations) IS DISTINCT FROM 'array' OR octet_length(p_operations::text)>6*1024*1024 THEN RAISE EXCEPTION 'FIN62_BUSINESS_INVALID';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('fin62-business:'||p_batch::text,0));
 SELECT * INTO prior FROM fin62_history_preparation.business_receipts WHERE batch_id=p_batch;
 IF FOUND THEN
  IF ROW(prior.organization_id,prior.branch_id,prior.terminal_id) IS DISTINCT FROM ROW(p_org,p_branch,p_terminal) OR prior.operations IS DISTINCT FROM p_operations THEN RAISE EXCEPTION 'FIN62_HISTORY_REPLAY_MISMATCH';END IF;
  RETURN prior.acknowledgement;
 END IF;
  -- All protected business projections and graph publication use the same
 -- per-shift lock before reading a head or writing a sale (phantom prevention).
 FOR sid IN SELECT DISTINCT (row_value->>'shift_id')::uuid FROM jsonb_array_elements(p_operations) op_part,LATERAL jsonb_array_elements(op_part->'rows') row_value WHERE op_part->>'table'='sales' ORDER BY 1 LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-shift:'||sid::text,0));
 END LOOP;
 FOR part IN SELECT value FROM jsonb_array_elements(p_operations) LOOP
  IF part->>'table' IN('shift_cash_counts','shift_reconciliations','shift_close_events','shift_notifications','shift_variance_alerts') THEN RAISE EXCEPTION 'FIN62_BUSINESS_SHIFT_GRAPH_FORBIDDEN';END IF;
  IF part->>'table'='shifts' AND EXISTS(SELECT 1 FROM jsonb_array_elements(part->'rows') row_value WHERE row_value->>'status' IS DISTINCT FROM 'OPEN' OR row_value->>'state' IS DISTINCT FROM 'ACTIVE' OR NOT EXISTS(SELECT 1 FROM public.shifts s WHERE s.id::text=row_value->>'id' AND s.store_id=p_branch AND s.status='OPEN' AND s.state='ACTIVE')) THEN RAISE EXCEPTION 'FIN62_BUSINESS_SHIFT_GRAPH_FORBIDDEN';END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(part->'changes','[]')) c WHERE c->>'op' IN('D','DELETE')) THEN RAISE EXCEPTION 'FIN62_BUSINESS_DELETE_UNSUPPORTED';END IF;
  IF part->>'table'='sales' THEN
   FOR r IN SELECT value FROM jsonb_array_elements(part->'rows') LOOP
    sid:=(r->>'shift_id')::uuid;sale:=(r->>'id')::uuid;
    SELECT * INTO head FROM fin62_history_preparation.streams s WHERE s.organization_id=p_org AND s.branch_id=p_branch AND s.terminal_id=p_terminal AND s.shift_id=sid FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'FIN62_BUSINESS_HISTORY_REQUIRED';END IF;
    SELECT fin62_history_preparation.fact(f.fact) INTO target FROM fin62_history_preparation.stream_facts f WHERE f.organization_id=p_org AND f.branch_id=p_branch AND f.terminal_id=p_terminal AND f.shift_id=sid AND f.sale_id=sale;
    IF target IS NULL OR fin62_history_preparation.row_fact(r) IS DISTINCT FROM target THEN RAISE EXCEPTION 'FIN62_FINANCIAL_PROJECTION_MISMATCH';END IF;
    SELECT to_jsonb(s) INTO stored FROM public.sales s WHERE s.id=sale FOR UPDATE;
    IF stored IS NOT NULL AND ROW(stored->>'store_id',stored->>'shift_id') IS DISTINCT FROM ROW(p_branch,sid::text) THEN RAISE EXCEPTION 'FIN62_FINANCIAL_SCOPE_IMMUTABLE';END IF;
    cursor_fact:=fin62_history_preparation.row_fact(stored);started:=false;
    IF cursor_fact IS DISTINCT FROM target THEN
     FOR node IN SELECT n.* FROM fin62_history_preparation.nodes n WHERE n.organization_id=p_org AND n.branch_id=p_branch AND n.terminal_id=p_terminal AND n.shift_id=sid AND n.node_kind='MUTATION' ORDER BY n.sequence LOOP
      FOR change IN SELECT value FROM jsonb_array_elements(node.payload_json::jsonb->'changes') WHERE value->>'saleId'=sale::text LOOP
       IF NOT started AND fin62_history_preparation.fact(nullif(change->'before','null'::jsonb)) IS NOT DISTINCT FROM cursor_fact THEN started:=true;END IF;
       IF started THEN
        IF fin62_history_preparation.fact(nullif(change->'before','null'::jsonb)) IS DISTINCT FROM cursor_fact THEN RAISE EXCEPTION 'FIN62_BUSINESS_HISTORY_DIVERGED';END IF;
        PERFORM fin62_history_preparation.current_author(p_branch,p_terminal,node.proof,node.payload_json::jsonb->>'action',node.operation_id,node.payload_hash);
        cursor_fact:=fin62_history_preparation.fact(nullif(change->'after','null'::jsonb));
       END IF;
      END LOOP;
     END LOOP;
     IF NOT started OR cursor_fact IS DISTINCT FROM target THEN RAISE EXCEPTION 'FIN62_BUSINESS_HISTORY_DIVERGED';END IF;
    END IF;
   END LOOP;
  END IF;
 END LOOP;
 INSERT INTO fin62_history_preparation.business_context VALUES(pg_backend_pid(),pg_current_xact_id(),p_org,p_branch,p_terminal);
 ack:=public.pos_sync_push_aggregate(p_batch,p_org,p_branch,p_terminal,p_operations);
 -- Read back actual persisted values; stale/monotonic writer behaviour must
 -- never turn an apparently accepted projection into different public money.
 FOR part IN SELECT value FROM jsonb_array_elements(p_operations) WHERE value->>'table'='sales' LOOP
  FOR r IN SELECT value FROM jsonb_array_elements(part->'rows') LOOP
   SELECT to_jsonb(s) INTO stored FROM public.sales s WHERE s.id=(r->>'id')::uuid;
   IF fin62_history_preparation.row_fact(stored) IS DISTINCT FROM fin62_history_preparation.row_fact(r) THEN RAISE EXCEPTION 'FIN62_FINANCIAL_PROJECTION_MISMATCH';END IF;
  END LOOP;
 END LOOP;
 DELETE FROM fin62_history_preparation.business_context WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id();
 INSERT INTO fin62_history_preparation.business_receipts VALUES(p_batch,p_org,p_branch,p_terminal,p_operations,ack); -- Immutable indexed facts come only from actual persisted business rows after
 -- successful writer/readback, never from a caller-issued authorized snapshot.
 INSERT INTO fin62_history_preparation.publications(batch_id,sale_id,organization_id,branch_id,terminal_id,shift_id,financial_fact,stream_sequence,capture_xid,evidence_order)
 SELECT p_batch,s.id,p_org,p_branch,p_terminal,s.shift_id::uuid,fin62_history_preparation.row_fact(to_jsonb(s)),h.sequence,pg_current_xact_id(),nextval('fin62_evidence_preparation.helper_order')
 FROM jsonb_array_elements(p_operations) source_part,LATERAL jsonb_array_elements(source_part->'rows') source_row
 JOIN public.sales s ON s.id=(source_row->>'id')::uuid
 JOIN fin62_history_preparation.streams h ON h.organization_id=p_org AND h.branch_id=p_branch AND h.terminal_id=p_terminal AND h.shift_id::text=s.shift_id
 WHERE source_part->>'table'='sales';
 RETURN ack;
END $fn$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA fin62_history_preparation FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.pos_sync_push_financial_business_aggregate(uuid,text,text,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pos_sync_push_financial_business_aggregate(uuid,text,text,text,jsonb) TO service_role;
CREATE TABLE fin62_history_preparation.graph_context(pid integer NOT NULL,xid xid8 NOT NULL,branch_id text NOT NULL,shift_id uuid NOT NULL,PRIMARY KEY(pid,xid));
ALTER TABLE fin62_history_preparation.graph_context ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_history_preparation.graph_context FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION fin62_history_preparation.guard_shift_graph() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM fin62_history_preparation.protected_shifts p WHERE p.shift_id=OLD.id AND p.branch_id=OLD.store_id) AND
  (to_jsonb(NEW)-ARRAY['updated_at','row_version']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['updated_at','row_version']) AND
  NOT EXISTS(SELECT 1 FROM fin62_history_preparation.graph_context c WHERE c.pid=pg_backend_pid() AND c.xid=pg_current_xact_id() AND c.branch_id=OLD.store_id AND c.shift_id=OLD.id)
 THEN RAISE EXCEPTION 'FIN62_SHIFT_ALIAS_NOT_INTEGRATED';END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER prototype_fin62_shift_write_guard BEFORE UPDATE ON public.shifts FOR EACH ROW EXECUTE FUNCTION fin62_history_preparation.guard_shift_graph();
REVOKE ALL ON FUNCTION fin62_history_preparation.guard_shift_graph() FROM PUBLIC,anon,authenticated,service_role;
-- A public fact that differs from this terminal's known snapshot is admissible
-- only with an actual successful guarded business publication by another stream.
-- Supported later mutations are only immutable SALE births and false->true REFUND.
CREATE FUNCTION fin62_history_preparation.published_later_fact(p_org text,p_branch text,p_shift uuid,p_sale uuid,p_before jsonb,p_after jsonb) RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$
DECLARE native_proof boolean;live_proof boolean;web_edges jsonb:='[]';published boolean;
BEGIN
 SELECT EXISTS(
  SELECT 1 FROM fin62_history_preparation.publications publication
  JOIN fin62_history_preparation.business_receipts receipt ON receipt.batch_id=publication.batch_id
  JOIN fin62_history_preparation.sale_steps step ON step.organization_id=publication.organization_id AND step.branch_id=publication.branch_id AND step.shift_id=publication.shift_id AND step.sale_id=publication.sale_id AND step.terminal_id=publication.terminal_id
  JOIN fin62_history_preparation.nodes node ON node.operation_id=step.operation_id AND node.organization_id=step.organization_id AND node.branch_id=step.branch_id AND node.terminal_id=step.terminal_id AND node.shift_id=step.shift_id AND node.node_kind='MUTATION'
  WHERE publication.organization_id=p_org AND publication.branch_id=p_branch AND publication.shift_id=p_shift AND publication.sale_id=p_sale
   AND receipt.organization_id=p_org AND receipt.branch_id=p_branch AND receipt.terminal_id=publication.terminal_id
   AND fin62_history_preparation.snapshot_canonical_fact(publication.financial_fact) IS NOT DISTINCT FROM p_after AND fin62_history_preparation.snapshot_canonical_fact(step.before_fact) IS NOT DISTINCT FROM p_before AND fin62_history_preparation.snapshot_canonical_fact(step.after_fact) IS NOT DISTINCT FROM p_after
   AND ((p_before IS NULL AND step.action='SALE' AND EXISTS(SELECT 1 FROM fin62_history_preparation.sale_birth_claims claim WHERE claim.sale_id=p_sale AND claim.operation_id=node.operation_id AND claim.organization_id=p_org AND claim.branch_id=p_branch AND claim.shift_id=p_shift)) OR (p_before IS NOT NULL AND step.action='REFUND'))
 ) INTO native_proof;
 IF native_proof THEN RETURN true;END IF;
 IF to_regprocedure('fin62_live_preparation.proves_later_publication(text,text,uuid,uuid,jsonb,jsonb)') IS NOT NULL THEN
  EXECUTE 'SELECT fin62_live_preparation.proves_later_publication($1,$2,$3,$4,$5,$6)' INTO live_proof USING p_org,p_branch,p_shift,p_sale,p_before,p_after;
  IF live_proof THEN RETURN true;END IF;
 END IF;
 IF to_regprocedure('fin62_live_preparation.publication_edges(text,text,uuid,uuid)') IS NOT NULL THEN
  EXECUTE 'SELECT coalesce(jsonb_agg(jsonb_build_object(''before'',before_fact,''after'',after_fact)),''[]'') FROM fin62_live_preparation.publication_edges($1,$2,$3,$4)' INTO web_edges USING p_org,p_branch,p_shift,p_sale;
 END IF;
 -- A chain of metadata alone is never publication. Its final fact must exist
 -- in an actual guarded native/business or live success receipt.
 SELECT EXISTS(SELECT 1 FROM fin62_history_preparation.publications p WHERE p.organization_id=p_org AND p.branch_id=p_branch AND p.shift_id=p_shift AND p.sale_id=p_sale AND fin62_history_preparation.snapshot_canonical_fact(p.financial_fact) IS NOT DISTINCT FROM p_after)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(web_edges) e WHERE fin62_history_preparation.snapshot_canonical_fact(nullif(e->'after','null'::jsonb)) IS NOT DISTINCT FROM p_after) INTO published;
 IF NOT published THEN RETURN false;END IF;
 RETURN(WITH native_edges AS(
  SELECT fin62_history_preparation.snapshot_canonical_fact(step.before_fact) before_fact,fin62_history_preparation.snapshot_canonical_fact(step.after_fact) after_fact
  FROM fin62_history_preparation.sale_steps step JOIN fin62_history_preparation.nodes node ON node.operation_id=step.operation_id AND node.organization_id=step.organization_id AND node.branch_id=step.branch_id AND node.terminal_id=step.terminal_id AND node.shift_id=step.shift_id AND node.node_kind='MUTATION'
  WHERE step.organization_id=p_org AND step.branch_id=p_branch AND step.shift_id=p_shift AND step.sale_id=p_sale AND
   (step.action='REFUND' OR (step.action='SALE' AND EXISTS(SELECT 1 FROM fin62_history_preparation.sale_birth_claims claim WHERE claim.sale_id=p_sale AND claim.operation_id=step.operation_id AND claim.organization_id=p_org AND claim.branch_id=p_branch AND claim.shift_id=p_shift)))
 ),edges AS(
  SELECT * FROM native_edges UNION
  SELECT fin62_history_preparation.snapshot_canonical_fact(nullif(e->'before','null'::jsonb)),fin62_history_preparation.snapshot_canonical_fact(nullif(e->'after','null'::jsonb)) FROM jsonb_array_elements(web_edges) e
 ) SELECT EXISTS(SELECT 1 FROM edges WHERE before_fact IS NOT DISTINCT FROM p_before AND after_fact IS NOT DISTINCT FROM p_after)
  OR EXISTS(SELECT 1 FROM edges first_edge JOIN edges second_edge ON first_edge.after_fact IS NOT DISTINCT FROM second_edge.before_fact WHERE first_edge.before_fact IS NOT DISTINCT FROM p_before AND second_edge.after_fact IS NOT DISTINCT FROM p_after));
END $$;
CREATE FUNCTION fin62_history_preparation.require_published_projection(p_org text,p_branch text,p_terminal text,p_shift uuid) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE head fin62_history_preparation.streams%ROWTYPE;row_value record;expected jsonb;actual jsonb;
BEGIN
 -- Caller holds pos-sync-shift advisory lock. All compatible business writers
 -- acquire that same lock before financial DML; legacy protected aliases deny.
 SELECT * INTO STRICT head FROM fin62_history_preparation.streams s WHERE s.organization_id=p_org AND s.branch_id=p_branch AND s.terminal_id=p_terminal AND s.shift_id=p_shift FOR UPDATE;
 FOR row_value IN SELECT s.id,to_jsonb(s) value FROM public.sales s WHERE s.store_id=p_branch AND s.shift_id=p_shift::text ORDER BY s.id FOR UPDATE LOOP
  SELECT fin62_history_preparation.snapshot_fact(f.fact) INTO expected FROM fin62_history_preparation.stream_facts f WHERE f.organization_id=p_org AND f.branch_id=p_branch AND f.terminal_id=p_terminal AND f.shift_id=p_shift AND f.sale_id=row_value.id;actual:=fin62_history_preparation.row_snapshot_fact(row_value.value);
  IF actual IS DISTINCT FROM expected AND NOT fin62_history_preparation.published_later_fact(p_org,p_branch,p_shift,row_value.id,expected,actual) THEN RAISE EXCEPTION 'FIN62_BUSINESS_PUBLICATION_REQUIRED';END IF;

 END LOOP;
 IF EXISTS(SELECT 1 FROM fin62_history_preparation.stream_facts f WHERE f.organization_id=p_org AND f.branch_id=p_branch AND f.terminal_id=p_terminal AND f.shift_id=p_shift AND NOT EXISTS(SELECT 1 FROM public.sales s WHERE s.id=f.sale_id AND s.store_id=p_branch AND s.shift_id=p_shift::text)) THEN RAISE EXCEPTION 'FIN62_BUSINESS_PUBLICATION_REQUIRED';END IF;END $$;
REVOKE ALL ON FUNCTION fin62_history_preparation.published_later_fact(text,text,uuid,uuid,jsonb,jsonb),fin62_history_preparation.require_published_projection(text,text,text,uuid) FROM PUBLIC,anon,authenticated,service_role;
-- Prepared override depends on the earlier financial-admission foundation.
-- Legacy basis-only inputs retain their existing guarded implementation.
ALTER FUNCTION public.pos_sync_push_financial_shift_intent(uuid,text,text,text,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb) RENAME TO prototype_fin62_legacy_financial_shift_intent;
REVOKE ALL ON FUNCTION public.prototype_fin62_legacy_financial_shift_intent(uuid,text,text,text,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.pos_sync_push_financial_shift_intent(p_batch_id uuid,p_organization_id text,p_branch_id text,p_terminal_id text,p_operations jsonb,p_shift_intent jsonb,p_shift_author jsonb,p_author_authority jsonb,p_closing_start jsonb,p_start_authority jsonb,p_financial_basis jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $fn$
DECLARE raw_basis text;raw_graph text;proof jsonb;basis jsonb;graph jsonb;node fin62_history_preparation.nodes%ROWTYPE;prior fin62_action_preparation.receipts%ROWTYPE;basis_id uuid;result jsonb;ack_version integer;origin jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_SERVICE_REQUIRED';END IF;
 raw_basis:=p_financial_basis->>'basisJson';basis:=raw_basis::jsonb;
 IF NOT basis?'financialFrontier' THEN RETURN public.prototype_fin62_legacy_financial_shift_intent(p_batch_id,p_organization_id,p_branch_id,p_terminal_id,p_operations,p_shift_intent,p_shift_author,p_author_authority,p_closing_start,p_start_authority,p_financial_basis);END IF;
 PERFORM public.pos_sync_validate_scope(p_organization_id,p_branch_id,p_terminal_id);
 raw_graph:=p_shift_intent->>'payloadJson';graph:=raw_graph::jsonb;proof:=p_financial_basis->'proof';
 IF p_batch_id IS NULL OR p_batch_id::text IS DISTINCT FROM graph->>'intentId' THEN RAISE EXCEPTION 'FIN62_HISTORY_REPLAY_MISMATCH';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-batch:'||p_batch_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-intent:'||p_batch_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-shift:'||(graph->>'shiftId'),0));
 SELECT * INTO node FROM fin62_history_preparation.nodes WHERE operation_id=p_batch_id;
 IF NOT FOUND OR node.node_kind IS DISTINCT FROM 'CLOSE_BOUNDARY' OR ROW(node.organization_id,node.branch_id,node.terminal_id,node.shift_id::text) IS DISTINCT FROM ROW(p_organization_id,p_branch_id,p_terminal_id,graph->>'shiftId') OR
  convert_to(node.graph_json,'UTF8') IS DISTINCT FROM convert_to(raw_graph,'UTF8') OR convert_to(node.basis_json,'UTF8') IS DISTINCT FROM convert_to(raw_basis,'UTF8') OR node.proof IS DISTINCT FROM proof OR node.graph_author IS DISTINCT FROM p_shift_author
 THEN RAISE EXCEPTION 'FIN62_REGISTERED_BOUNDARY_REQUIRED';END IF;
 origin:=coalesce(proof->'openingOrigin',basis->'financialFrontier'->'cloudOrigin');
 SELECT birth_basis_id INTO STRICT basis_id FROM fin62_history_preparation.streams WHERE organization_id=p_organization_id AND branch_id=p_branch_id AND terminal_id=p_terminal_id AND shift_id=node.shift_id AND opening_origin=origin;
 SELECT * INTO prior FROM fin62_action_preparation.receipts WHERE intent_id=p_batch_id;
 IF prior.intent_id IS NULL THEN
  IF EXISTS(SELECT 1 FROM pos_sync_private.shift_intent_receipts WHERE intent_id=p_batch_id) THEN RAISE EXCEPTION 'FIN62_FINANCIAL_HISTORY_UNPROVEN';END IF;
  PERFORM fin62_history_preparation.current_author(p_branch_id,p_terminal_id,p_shift_author,graph->>'kind',p_batch_id,node.graph_hash);
  PERFORM fin62_history_preparation.require_published_projection(p_organization_id,p_branch_id,p_terminal_id,node.shift_id);
 END IF;
 INSERT INTO fin62_history_preparation.graph_context VALUES(pg_backend_pid(),pg_current_xact_id(),p_branch_id,node.shift_id);
 -- Unchanged real author/start writers enforce current authority, actor, count,
 -- original/recount state and causal token. Metadata alone is never this ACK.
 IF p_closing_start IS NOT NULL THEN result:=public.pos_sync_push_started_shift_intent(p_batch_id,p_organization_id,p_branch_id,p_terminal_id,p_operations,p_shift_intent,p_shift_author,p_author_authority,p_closing_start,p_start_authority);
 ELSE
  IF p_start_authority IS NOT NULL THEN RAISE EXCEPTION 'FIN62_START_PROOF_REQUIRED';END IF;
  result:=public.pos_sync_push_author_shift_intent(p_batch_id,p_organization_id,p_branch_id,p_terminal_id,p_operations,p_shift_intent,p_shift_author,p_author_authority);
 END IF;
 DELETE FROM fin62_history_preparation.graph_context WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id();
 IF prior.intent_id IS NULL THEN
  INSERT INTO fin62_action_preparation.receipts(intent_id,organization_id,branch_id,terminal_id,shift_id,author_id,key_id,graph_payload_hash,basis_id,basis_hash,basis_json,basis_proof,formula,acknowledgement)
  VALUES(p_batch_id,p_organization_id,p_branch_id,p_terminal_id,node.shift_id,(proof->>'authorId')::uuid,(proof->>'keyId')::uuid,node.graph_hash,basis_id,node.basis_hash,raw_basis,proof,proof->>'formula',result);
 END IF;
 ack_version:=CASE WHEN proof?'openingOrigin' THEN 2 ELSE 1 END;
 RETURN result||jsonb_build_object('financial_basis_receipt',jsonb_build_object('ack_version',ack_version,'intentId',p_batch_id,'graphPayloadHash',node.graph_hash,'basisHash',node.basis_hash,'serverBasisId',basis_id,'formula',proof->>'formula')||CASE WHEN ack_version=2 THEN jsonb_build_object('openingOrigin',origin) ELSE '{}'::jsonb END);
END $fn$;
REVOKE ALL ON FUNCTION public.pos_sync_push_financial_shift_intent(uuid,text,text,text,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pos_sync_push_financial_shift_intent(uuid,text,text,text,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb) TO service_role;
CREATE FUNCTION public.pos_sync_read_financial_basis(p_org text,p_branch text,p_terminal text,p_shift uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_basis jsonb;evidence jsonb;published jsonb;
BEGIN
 v_basis:=public.prototype_fin62_create_basis(p_org,p_branch,p_terminal,p_shift);
 SELECT jsonb_build_object('creatorXid',b.creator_xid::text,'snapshot',b.snapshot_text,'evidenceOrder',b.evidence_order::text) INTO evidence FROM fin62_cloud_preparation.bases b WHERE b.id=(v_basis->>'basisId')::uuid;
  SELECT coalesce(jsonb_object_agg(sale_id::text,covered::text),'{}') INTO published FROM(
  SELECT p.sale_id,max(p.stream_sequence) covered FROM fin62_history_preparation.publications p JOIN fin62_cloud_preparation.bases b ON b.id=(v_basis->>'basisId')::uuid
  WHERE p.organization_id=p_org AND p.branch_id=p_branch AND p.terminal_id=p_terminal AND p.shift_id=p_shift
  AND CASE WHEN p.capture_xid=b.creator_xid THEN p.evidence_order<b.evidence_order ELSE pg_visible_in_snapshot(p.capture_xid,b.snapshot_text::pg_snapshot) END GROUP BY p.sale_id
 ) proof;
 RETURN v_basis||jsonb_build_object('parentSnapshot',v_basis->'basis'->'parentSnapshot','sourceEvidence',evidence,'ownPublishedThrough',published);
END $$;
REVOKE ALL ON FUNCTION public.pos_sync_read_financial_basis(text,text,text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pos_sync_read_financial_basis(text,text,text,uuid) TO service_role;
CREATE FUNCTION fin62_history_preparation.visible_materialized_sequence(p_org text,p_branch text,p_terminal text,p_shift uuid,p_sale uuid,p_source uuid) RETURNS bigint LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT coalesce(max(p.stream_sequence),0) FROM fin62_history_preparation.publications p JOIN fin62_cloud_preparation.bases b ON b.id=p_source
 WHERE p.organization_id=p_org AND p.branch_id=p_branch AND p.terminal_id=p_terminal AND p.shift_id=p_shift AND p.sale_id=p_sale
 AND CASE WHEN p.capture_xid=b.creator_xid THEN p.evidence_order<b.evidence_order ELSE pg_visible_in_snapshot(p.capture_xid,b.snapshot_text::pg_snapshot) END;
$$;
REVOKE ALL ON FUNCTION fin62_history_preparation.visible_materialized_sequence(text,text,text,uuid,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
-- Verified-device read-metadata only. Source is a complete immutable actual SQL
-- basis; own deltas come only from previously accepted immutable signed events.
-- No writer is replayed and no current actor grant is invented by observation.
CREATE FUNCTION public.pos_sync_register_financial_observation(p_org text,p_branch text,p_terminal text,p_raw text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $fn$
DECLARE body jsonb;op uuid;sid uuid;n bigint;digest text;origin jsonb;source fin62_cloud_preparation.bases%ROWTYPE;
 prior fin62_history_preparation.nodes%ROWTYPE;previous fin62_history_preparation.nodes%ROWTYPE;previous_basis fin62_cloud_preparation.bases%ROWTYPE;
 head fin62_history_preparation.streams%ROWTYPE;source_state jsonb;merged jsonb;pending jsonb:='{}';previous_pending jsonb:='{}';previous_sequence bigint:=0;
 overrides jsonb[]:=ARRAY[]::jsonb[];pending_entries jsonb[]:=ARRAY[]::jsonb[];identifier uuid;step record;first_step boolean;source_value jsonb;working jsonb;chosen bigint;earliest bigint;covered_sequence bigint;previous_raw jsonb;calc jsonb;ack jsonb;merged_array jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_SERVICE_REQUIRED';END IF;
 PERFORM public.pos_sync_validate_scope(p_org,p_branch,p_terminal);
 IF p_raw IS NULL OR octet_length(p_raw)>16384 THEN RAISE EXCEPTION 'FIN62_OBSERVATION_LIMIT';END IF;
 PERFORM fin62_preparation.math_unique_json(p_raw::json,56);body:=p_raw::jsonb;
 IF jsonb_typeof(body) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(body) key) IS DISTINCT FROM
  (CASE WHEN body->'version'='2'::jsonb THEN ARRAY['action','branchId','cloudOrigin','observedBasis','operationId','predecessorHash','predecessorOperationId','sequence','shiftId','terminalId','version']::text[] ELSE ARRAY['action','branchId','observedBasis','openingOrigin','operationId','predecessorHash','predecessorOperationId','sequence','shiftId','terminalId','version']::text[] END) OR
  body->'version' NOT IN('1'::jsonb,'2'::jsonb) OR body->>'action' IS DISTINCT FROM 'OBSERVE' OR body->>'branchId' IS DISTINCT FROM p_branch OR body->>'terminalId' IS DISTINCT FROM p_terminal OR
  jsonb_typeof(body->'sequence') IS DISTINCT FROM 'string' OR coalesce(body->>'sequence','')!~'^[1-9][0-9]{0,18}$' OR jsonb_typeof(body->'observedBasis') IS DISTINCT FROM 'object' OR
  (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(body->'observedBasis') key) IS DISTINCT FROM ARRAY['serverBasisHash','serverBasisId']::text[]
 THEN RAISE EXCEPTION 'FIN62_OBSERVATION_INVALID';END IF;
 op:=(body->>'operationId')::uuid;sid:=(body->>'shiftId')::uuid;n:=(body->>'sequence')::bigint;digest:=encode(sha256(convert_to(p_raw,'UTF8')),'hex');
 IF op IS NULL OR sid IS NULL OR n::text IS DISTINCT FROM body->>'sequence' THEN RAISE EXCEPTION 'FIN62_OBSERVATION_INVALID';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('fin62-history-node:'||op::text,0));
 SELECT * INTO prior FROM fin62_history_preparation.nodes WHERE operation_id=op;
 IF FOUND THEN
  IF prior.node_kind IS DISTINCT FROM 'OBSERVATION' OR ROW(prior.organization_id,prior.branch_id,prior.terminal_id,prior.shift_id,prior.sequence,prior.payload_hash) IS DISTINCT FROM ROW(p_org,p_branch,p_terminal,sid,n,digest) OR convert_to(prior.payload_json,'UTF8') IS DISTINCT FROM convert_to(p_raw,'UTF8') THEN RAISE EXCEPTION 'FIN62_HISTORY_REPLAY_MISMATCH';END IF;
  RETURN prior.acknowledgement;
 END IF;
 origin:=coalesce(body->'openingOrigin',body->'cloudOrigin');
 PERFORM fin62_history_preparation.ensure_stream(p_org,p_branch,p_terminal,sid,origin);
 SELECT * INTO STRICT head FROM fin62_history_preparation.streams s WHERE s.organization_id=p_org AND s.branch_id=p_branch AND s.terminal_id=p_terminal AND s.shift_id=sid FOR UPDATE;
 IF n<>head.sequence+1 OR body->>'predecessorOperationId' IS DISTINCT FROM head.operation_id::text OR body->>'predecessorHash' IS DISTINCT FROM head.payload_hash THEN RAISE EXCEPTION 'FIN62_HISTORY_GAP_OR_CONFLICT';END IF;
 SELECT * INTO source FROM fin62_cloud_preparation.bases b WHERE b.id=(body->'observedBasis'->>'serverBasisId')::uuid AND b.organization_id=p_org AND b.branch_id=p_branch AND b.terminal_id=p_terminal AND b.shift_id=sid;
 IF NOT FOUND OR source.basis_hash IS DISTINCT FROM body->'observedBasis'->>'serverBasisHash' THEN RAISE EXCEPTION 'FIN62_OBSERVATION_SOURCE_UNPROVEN';END IF;
 SELECT * INTO previous FROM fin62_history_preparation.nodes node WHERE node.organization_id=p_org AND node.branch_id=p_branch AND node.terminal_id=p_terminal AND node.shift_id=sid AND node.node_kind='OBSERVATION' ORDER BY node.sequence DESC LIMIT 1;
 IF FOUND THEN previous_sequence:=previous.sequence;previous_pending:=previous.pending_from;SELECT * INTO STRICT previous_basis FROM fin62_cloud_preparation.bases WHERE id=previous.observed_basis_id;
 ELSE SELECT * INTO STRICT previous_basis FROM fin62_cloud_preparation.bases WHERE id=head.birth_basis_id;END IF;
 -- This is MVCC receipt visibility, never a wall-time or global sequence clock.
 IF source.creator_xid=previous_basis.creator_xid THEN
  IF source.evidence_order<=previous_basis.evidence_order THEN RAISE EXCEPTION 'FIN62_OBSERVATION_SOURCE_STALE';END IF;
 ELSIF NOT pg_visible_in_snapshot(previous_basis.creator_xid,source.snapshot_text::pg_snapshot) THEN RAISE EXCEPTION 'FIN62_OBSERVATION_SOURCE_STALE';END IF;
 IF (CASE WHEN source.basis->>'openingFloat' IS NULL THEN 0 ELSE fin62_preparation.math_decimal_text(source.basis->>'openingFloat') END) IS DISTINCT FROM
  (CASE WHEN previous_basis.basis->>'openingFloat' IS NULL THEN 0 ELSE fin62_preparation.math_decimal_text(previous_basis.basis->>'openingFloat') END) THEN RAISE EXCEPTION 'FIN62_OBSERVATION_OPENING_CHANGED';END IF;
 SELECT coalesce(jsonb_object_agg(item->>'id',item),'{}') INTO source_state FROM jsonb_array_elements(source.basis->'inputs') item;
 merged:=source_state;
 FOR identifier IN SELECT DISTINCT e.sale_id FROM fin62_history_preparation.sale_steps e WHERE e.organization_id=p_org AND e.branch_id=p_branch AND e.terminal_id=p_terminal AND e.shift_id=sid AND
  (e.sequence>previous_sequence OR (previous_pending?e.sale_id::text AND e.sequence>=(previous_pending->>e.sale_id::text)::bigint)) LOOP
  covered_sequence:=fin62_history_preparation.visible_materialized_sequence(p_org,p_branch,p_terminal,sid,identifier,source.id);
  source_value:=source_state->identifier::text;chosen:=NULL;first_step:=true;previous_raw:=NULL;
  FOR step IN SELECT e.* FROM fin62_history_preparation.sale_steps e WHERE e.organization_id=p_org AND e.branch_id=p_branch AND e.terminal_id=p_terminal AND e.shift_id=sid AND e.sale_id=identifier AND e.sequence>covered_sequence AND
   (e.sequence>previous_sequence OR (previous_pending?identifier::text AND e.sequence>=(previous_pending->>identifier::text)::bigint)) ORDER BY e.sequence LOOP
   IF first_step THEN
    IF fin62_history_preparation.snapshot_fact(source_value) IS NOT DISTINCT FROM fin62_history_preparation.snapshot_fact(step.raw_before) THEN chosen:=0;END IF;
    first_step:=false;
   ELSIF fin62_history_preparation.snapshot_fact(previous_raw) IS DISTINCT FROM fin62_history_preparation.snapshot_fact(step.raw_before) THEN RAISE EXCEPTION 'FIN62_OBSERVATION_OWN_CHAIN_DIVERGED';END IF;
   IF fin62_history_preparation.snapshot_fact(source_value) IS NOT DISTINCT FROM fin62_history_preparation.snapshot_fact(step.raw_after) THEN chosen:=step.sequence;END IF;
   previous_raw:=step.raw_after;
  END LOOP;
  IF first_step THEN CONTINUE;END IF;
  IF chosen IS NULL THEN RAISE EXCEPTION 'FIN62_OBSERVATION_MERGE_DIVERGED';END IF;
  working:=source_value;earliest:=NULL;
  FOR step IN SELECT e.* FROM fin62_history_preparation.sale_steps e WHERE e.organization_id=p_org AND e.branch_id=p_branch AND e.terminal_id=p_terminal AND e.shift_id=sid AND e.sale_id=identifier AND e.sequence>covered_sequence AND e.sequence>chosen AND
   (e.sequence>previous_sequence OR (previous_pending?identifier::text AND e.sequence>=(previous_pending->>identifier::text)::bigint)) ORDER BY e.sequence LOOP
   IF fin62_history_preparation.snapshot_fact(working) IS DISTINCT FROM fin62_history_preparation.snapshot_fact(step.raw_before) THEN RAISE EXCEPTION 'FIN62_OBSERVATION_OWN_CHAIN_DIVERGED';END IF;
   IF earliest IS NULL THEN earliest:=step.sequence;END IF;working:=step.raw_after;
  END LOOP;
  overrides:=array_append(overrides,jsonb_build_object('id',identifier,'fact',working));
  IF earliest IS NOT NULL THEN pending_entries:=array_append(pending_entries,jsonb_build_object('id',identifier,'sequence',earliest::text));END IF;
 END LOOP;
 -- Aggregate once after all indexed per-sale decisions, rather than repeatedly
 -- copying an expanding JSON object for every pending sale.
 WITH changed AS MATERIALIZED(SELECT item->>'id' id,item->'fact' fact FROM unnest(overrides) item),combined AS(
  SELECT base.key id,base.value fact FROM jsonb_each(source_state) base WHERE NOT EXISTS(SELECT 1 FROM changed WHERE changed.id=base.key)
  UNION ALL SELECT id,fact FROM changed WHERE fact<>'null'::jsonb
 ) SELECT coalesce(jsonb_object_agg(id,fact),'{}') INTO merged FROM combined;
 SELECT coalesce(jsonb_object_agg(item->>'id',item->'sequence'),'{}') INTO pending FROM unnest(pending_entries) item;
 IF octet_length(merged::text)>6*1024*1024 THEN RAISE EXCEPTION 'FIN62_OBSERVATION_LIMIT';END IF;
 SELECT fin62_preparation.validate_financial_math(source.basis||jsonb_build_object('inputs',coalesce(jsonb_agg(value ORDER BY key),'[]'))) INTO calc FROM jsonb_each(merged);
 IF calc->>'status' IS DISTINCT FROM 'computed' THEN RAISE EXCEPTION 'FIN62_OBSERVATION_MATH_UNSUPPORTED';END IF;
 SELECT coalesce(jsonb_agg(value ORDER BY key COLLATE "C"),'[]') INTO merged_array FROM jsonb_each(merged);
 ack:=jsonb_build_object('computedMergedHash',encode(sha256(convert_to(fin62_history_preparation.canonical_json(merged_array),'UTF8')),'hex'),'pendingFromHash',encode(sha256(convert_to(fin62_history_preparation.canonical_json(pending),'UTF8')),'hex'),
  'status','financial_metadata_observed','operationId',op,'payloadHash',digest,'sequence',n::text,'businessUploaded',false,'shiftClosed',false);
 INSERT INTO fin62_history_preparation.nodes(operation_id,organization_id,branch_id,terminal_id,shift_id,sequence,node_kind,payload_json,payload_hash,proof,observed_basis_id,pending_from,acknowledgement)
 VALUES(op,p_org,p_branch,p_terminal,sid,n,'OBSERVATION',p_raw,digest,'{}',source.id,pending,ack);
 INSERT INTO fin62_history_preparation.stream_facts SELECT p_org,p_branch,p_terminal,sid,entry.key::uuid,entry.value FROM jsonb_each(merged) entry WHERE NOT EXISTS(SELECT 1 FROM fin62_history_preparation.stream_facts current_fact WHERE current_fact.organization_id=p_org AND current_fact.branch_id=p_branch AND current_fact.terminal_id=p_terminal AND current_fact.shift_id=sid AND current_fact.sale_id=entry.key::uuid AND current_fact.fact IS NOT DISTINCT FROM entry.value)
 ON CONFLICT(organization_id,branch_id,terminal_id,shift_id,sale_id) DO UPDATE SET fact=EXCLUDED.fact WHERE fin62_history_preparation.stream_facts.fact IS DISTINCT FROM EXCLUDED.fact;
 DELETE FROM fin62_history_preparation.stream_facts f WHERE f.organization_id=p_org AND f.branch_id=p_branch AND f.terminal_id=p_terminal AND f.shift_id=sid AND NOT merged?f.sale_id::text;
 UPDATE fin62_history_preparation.streams SET sequence=n,operation_id=op,payload_hash=digest WHERE organization_id=p_org AND branch_id=p_branch AND terminal_id=p_terminal AND shift_id=sid;
 RETURN ack;
END $fn$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA fin62_history_preparation FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.pos_sync_register_financial_observation(text,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pos_sync_register_financial_observation(text,text,text,text) TO service_role;

-- Source: scripts/preparation/shift-financial-web-actions.sql
-- Canonical source SHA256: C183B8A19955F180A9CD445F6263D0C8033DB85DA229887A4078E5E81C9A37A5
-- FIN62 PREPARATION ONLY / NOT FINAL / DO NOT APPLY TO OPERATOR DATABASE.
-- New web actions only: exact canonical v2 arithmetic under the actual existing
-- caller/action/branch guards. Legacy accepted replay returns remain untouched.
-- No new public RPC, permission grant, global report-helper change or data repair.
DO $pins$
DECLARE p record;
BEGIN
 FOR p IN SELECT * FROM (VALUES
 ('pos_admin_correct_closed_shift','6322741fecb9b086e93f413bf78e3f62'),
 ('shift_cash_count_submit','7da4fe386d35979d7b7cbc89f00a0dc6'),
 ('shift_close_start','66e07e54e6a9bc23bc3098a7c2fae40e'),
 ('shift_variance_approve','902e778332c2dca9bc34d241a1f9e119'),
 ('shift_reconcile_now','04a2bce3bfad4277dcc9aa2751f6ddbd'),
 ('shift_recount_submit','fa77acc46f885c1734e18d883d4f7f89')) expected(name,digest) LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_proc r WHERE r.pronamespace='public'::regnamespace AND r.proname=p.name AND md5(replace(pg_get_functiondef(r.oid),E'\r\n',E'\n')) IN (p.digest,CASE p.name WHEN 'shift_close_start' THEN '0017c1ad94bcd3b3db49fdaa803d70ce' WHEN 'shift_reconcile_now' THEN '920af85fa748db61b9d9c723c16eb495' ELSE p.digest END) AND r.proowner='postgres'::regrole AND r.prosecdef AND r.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql')) THEN RAISE EXCEPTION 'FIN62_WEB_SOURCE_UNEXPECTED: %',p.name;END IF;
 END LOOP;
END $pins$;
CREATE SCHEMA fin62_web_preparation;
REVOKE ALL ON SCHEMA fin62_web_preparation FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE fin62_web_preparation.actions(
 count_id uuid PRIMARY KEY REFERENCES public.shift_cash_counts(id),shift_id uuid NOT NULL,branch_id text NOT NULL,
 action text NOT NULL CHECK(action IN('ORIGINAL','RECOUNT','ADMIN_CORRECTION')),
 formula text NOT NULL CHECK(formula='canonical-exact-decimal-v2'),basis_json text NOT NULL,basis_hash text NOT NULL CHECK(basis_hash ~ '^[a-f0-9]{64}$'),
 expected_cash numeric NOT NULL,expected_card numeric NOT NULL,expected_digital numeric NOT NULL,
 counted_cash numeric NOT NULL,counted_card numeric,counted_digital numeric,
 snapshot_text text NOT NULL,creator_xid xid8 NOT NULL,actor_user_id uuid,created_at timestamptz NOT NULL DEFAULT now(),
 CHECK(octet_length(basis_json)<=6291456)
);
CREATE TABLE fin62_web_preparation.active_actions(pid integer NOT NULL,xid xid8 NOT NULL,count_id uuid NOT NULL,shift_id uuid NOT NULL,branch_id text NOT NULL,owns_graph_context boolean NOT NULL,PRIMARY KEY(pid,xid));
ALTER TABLE fin62_web_preparation.actions ENABLE ROW LEVEL SECURITY;
ALTER TABLE fin62_web_preparation.active_actions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_web_preparation.actions,fin62_web_preparation.active_actions FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION fin62_web_preparation.immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'FIN62_WEB_ACTION_IMMUTABLE';END $$;
CREATE TRIGGER actions_immutable BEFORE UPDATE OR DELETE ON fin62_web_preparation.actions FOR EACH ROW EXECUTE FUNCTION fin62_web_preparation.immutable();
CREATE FUNCTION fin62_web_preparation.validate_counted(cash numeric,card numeric,digital numeric) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE amount numeric;
BEGIN
 FOREACH amount IN ARRAY ARRAY[cash,card,digital] LOOP
  IF amount IS NOT NULL THEN
   PERFORM fin62_preparation.math_decimal_text(amount::text);
   IF amount<>round(amount,2) THEN RAISE EXCEPTION 'FIN62_WEB_COUNT_WHOLE_CENTS_REQUIRED';END IF;
  END IF;
 END LOOP;
END $$;
CREATE FUNCTION fin62_web_preparation.capture_expected(p_shift uuid,p_count uuid,p_action text) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE sh public.shifts%ROWTYPE;c public.shift_cash_counts%ROWTYPE;basis jsonb;raw text;computed jsonb;snapshot text;protected boolean:=false;
BEGIN
 SELECT * INTO STRICT sh FROM public.shifts WHERE id=p_shift FOR UPDATE;
 SELECT * INTO STRICT c FROM public.shift_cash_counts WHERE id=p_count AND shift_id=p_shift AND store_id=sh.store_id;
 IF p_action NOT IN('ORIGINAL','RECOUNT','ADMIN_CORRECTION') OR (p_action='ORIGINAL') IS DISTINCT FROM (c.kind='ORIGINAL') THEN RAISE EXCEPTION 'FIN62_WEB_COUNT_SCOPE_MISMATCH';END IF;
 PERFORM fin62_web_preparation.validate_counted(c.counted_cash,c.counted_card,c.counted_digital);
 IF EXISTS(SELECT 1 FROM fin62_web_preparation.active_actions WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id()) THEN RAISE EXCEPTION 'FIN62_WEB_ACTION_CONTEXT_BUSY';END IF;
 -- One statement snapshot covers the COMPLETE actual server input set. No
 -- caller-supplied totals, subset lists, timestamps or authorized flags exist.
 WITH scope AS MATERIALIZED(SELECT * FROM public.shifts WHERE id=p_shift AND store_id=sh.store_id),inputs AS MATERIALIZED(
  SELECT s.* FROM public.sales s JOIN scope p ON s.store_id=p.store_id AND s.shift_id=p.id::text)
 SELECT jsonb_build_object('prototypeVersion',2,'formula','canonical-exact-decimal-v2','branchId',p.store_id,'shiftId',p.id,'openingFloat',p.opening_float::text,'parentSnapshot',to_jsonb(p),'inputs',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'branchId',s.store_id,'shiftId',s.shift_id,'totalAmount',s.total_amount::text,'paymentType',s.payment_type,'paymentsJson',s.payments::text,'discountAmount',s.discount_amount::text,'isRefunded',s.is_refunded,'rowVersion',s.row_version::text) ORDER BY s.id) FROM inputs s),'[]'::jsonb)),pg_current_snapshot()::text INTO STRICT basis,snapshot FROM scope p;
 raw:=basis::text;computed:=fin62_preparation.validate_financial_math_text(raw);
 IF computed->>'status'<>'computed' OR computed->>'formula'<>'canonical-exact-decimal-v2' THEN RAISE EXCEPTION 'FIN62_WEB_MATH_UNVERIFIED';END IF;
 INSERT INTO fin62_web_preparation.actions(count_id,shift_id,branch_id,action,formula,basis_json,basis_hash,expected_cash,expected_card,expected_digital,counted_cash,counted_card,counted_digital,snapshot_text,creator_xid,actor_user_id)
 VALUES(p_count,p_shift,sh.store_id,p_action,'canonical-exact-decimal-v2',raw,encode(sha256(convert_to(raw,'UTF8')),'hex'),(computed#>>'{expected,cash}')::numeric,(computed#>>'{expected,card}')::numeric,(computed#>>'{expected,digital}')::numeric,c.counted_cash,c.counted_card,c.counted_digital,snapshot,pg_current_xact_id(),auth.uid());
 IF to_regclass('fin62_history_preparation.protected_shifts') IS NOT NULL THEN
  SELECT EXISTS(SELECT 1 FROM fin62_history_preparation.protected_shifts WHERE shift_id=p_shift AND branch_id=sh.store_id) INTO protected;
 END IF;
 IF protected THEN
  IF EXISTS(SELECT 1 FROM fin62_history_preparation.graph_context WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id()) THEN RAISE EXCEPTION 'FIN62_WEB_GRAPH_CONTEXT_BUSY';END IF;
  INSERT INTO fin62_history_preparation.graph_context VALUES(pg_backend_pid(),pg_current_xact_id(),sh.store_id,p_shift);
 END IF;
 INSERT INTO fin62_web_preparation.active_actions VALUES(pg_backend_pid(),pg_current_xact_id(),p_count,p_shift,sh.store_id,protected);
END $$;
CREATE FUNCTION fin62_web_preparation.action_expected(p_shift uuid,p_count uuid) RETURNS TABLE(expected_cash numeric,expected_card numeric,expected_digital numeric) LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM fin62_web_preparation.active_actions WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id() AND count_id=p_count AND shift_id=p_shift) THEN RAISE EXCEPTION 'FIN62_WEB_ACTION_CONTEXT_REQUIRED';END IF;
 RETURN QUERY SELECT a.expected_cash,a.expected_card,a.expected_digital FROM fin62_web_preparation.actions a WHERE a.count_id=p_count AND a.shift_id=p_shift;
 IF NOT FOUND THEN RAISE EXCEPTION 'FIN62_WEB_ACTION_MISSING';END IF;
END $$;
CREATE FUNCTION fin62_web_preparation.end_action(p_shift uuid,p_count uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE active fin62_web_preparation.active_actions%ROWTYPE;
BEGIN
 SELECT * INTO STRICT active FROM fin62_web_preparation.active_actions WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id() AND shift_id=p_shift AND count_id=p_count;
 IF active.owns_graph_context THEN DELETE FROM fin62_history_preparation.graph_context WHERE pid=active.pid AND xid=active.xid AND branch_id=active.branch_id AND shift_id=active.shift_id;IF NOT FOUND THEN RAISE EXCEPTION 'FIN62_WEB_GRAPH_CONTEXT_MISSING';END IF;END IF;
 DELETE FROM fin62_web_preparation.active_actions WHERE pid=active.pid AND xid=active.xid;
END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA fin62_web_preparation FROM PUBLIC,anon,authenticated,service_role;
DO $patch$
DECLARE routine oid;before_row pg_proc%ROWTYPE;after_row pg_proc%ROWTYPE;definition text;
BEGIN
 SELECT oid INTO STRICT routine FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='pos_admin_correct_closed_shift';
 SELECT * INTO STRICT before_row FROM pg_proc WHERE oid=routine;
 IF md5(replace(pg_get_functiondef(routine),E'\r\n',E'\n'))<>'6322741fecb9b086e93f413bf78e3f62' THEN RAISE EXCEPTION 'FIN62_WEB_SOURCE_CHANGED';END IF;
 EXECUTE 'CREATE OR REPLACE FUNCTION public.pos_admin_correct_closed_shift(p_shift uuid, p_cash numeric, p_card numeric, p_digital numeric, p_reason text, p_actor_id text, p_actor_name text, p_terminal text, p_client_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''public'', ''pg_temp''
AS $function$
DECLARE
  v public.shifts%ROWTYPE; e record; v_count uuid; v_rec uuid;
  v_existing_cash numeric; v_existing_card numeric; v_existing_digital numeric;
  v_reason text := btrim(coalesce(p_reason, ''''));
  v_before jsonb; v_after jsonb;
  v_var_cash numeric; v_var_card numeric; v_var_digital numeric; v_total numeric; v_status text;
BEGIN
  IF char_length(v_reason) < 3 THEN
    RAISE EXCEPTION ''A correction reason of at least 3 characters is required.'';
  END IF;
  IF nullif(btrim(coalesce(p_client_key, '''')), '''') IS NULL THEN
    RAISE EXCEPTION ''A client correction key is required.'';
  END IF;
  IF p_cash IS NULL OR p_cash < 0 OR (p_card IS NOT NULL AND p_card < 0)
     OR (p_digital IS NOT NULL AND p_digital < 0) THEN
    RAISE EXCEPTION ''Counted tender amounts cannot be negative.'';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_client_key, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended(''pos-sync-shift:''||p_shift::text,0));
  SELECT * INTO v FROM public.shifts WHERE id = p_shift FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION ''That shift no longer exists.''; END IF;

  SELECT shift_id, counted_cash, counted_card, counted_digital
    INTO v_count, v_existing_cash, v_existing_card, v_existing_digital
    FROM public.shift_cash_counts
   WHERE client_key = p_client_key LIMIT 1;
  IF FOUND THEN
    IF v_count <> p_shift THEN
      RAISE EXCEPTION ''That correction key was already used for another shift.'';
    END IF;
    IF v_existing_cash IS DISTINCT FROM p_cash
       OR v_existing_card IS DISTINCT FROM p_card
       OR v_existing_digital IS DISTINCT FROM p_digital THEN
      RAISE EXCEPTION ''That correction key was already used with different counted amounts.'';
    END IF;
    RETURN jsonb_build_object(''ok'', true, ''replayed'', true, ''shift_id'', v_count);
  END IF;

  IF v.status IS DISTINCT FROM ''CLOSED'' OR coalesce(v.state, ''CLOSED'') <> ''CLOSED'' THEN
    RAISE EXCEPTION ''Only a closed shift can be corrected.'';
  END IF;
  -- Preserve existing raw API rounding; capture validates the actual saved count.
  v_before := jsonb_build_object(
    ''counted_cash'', v.counted_cash, ''counted_card'', v.counted_card,
    ''counted_digital'', v.counted_digital, ''expected_cash'', v.expected_cash,
    ''expected_card'', v.expected_card, ''expected_digital'', v.expected_digital,
    ''variance_cash'', v.variance_cash, ''variance_card'', v.variance_card,
    ''variance_digital'', v.variance_digital, ''variance_total'', v.variance_total,
    ''variance_status'', v.variance_status
  );

  INSERT INTO public.shift_cash_counts
    (shift_id, store_id, terminal_id, kind, counted_cash, counted_card, counted_digital,
     reason, counted_by_name, counted_by_staff_id, client_key)
  VALUES
    (p_shift, v.store_id, coalesce(p_terminal, v.terminal_id), ''RECOUNT'', p_cash, p_card,
     p_digital, v_reason, nullif(p_actor_name, ''''), nullif(p_actor_id, ''''), p_client_key)
  RETURNING id INTO v_count;
  PERFORM fin62_web_preparation.capture_expected(p_shift,v_count,''ADMIN_CORRECTION'');
  SELECT * INTO e FROM fin62_web_preparation.action_expected(p_shift,v_count);
  v_var_cash := round(p_cash - e.expected_cash, 2);
  v_var_card := CASE WHEN p_card IS NULL THEN NULL ELSE round(p_card - e.expected_card, 2) END;
  v_var_digital := CASE WHEN p_digital IS NULL THEN NULL ELSE round(p_digital - e.expected_digital, 2) END;
  v_total := round(v_var_cash + coalesce(v_var_card, 0) + coalesce(v_var_digital, 0), 2);
  v_status := CASE WHEN abs(v_total) <= 0.005 THEN ''NO_VARIANCE''
                   WHEN v_total > 0 THEN ''OVER'' ELSE ''SHORT'' END;

  INSERT INTO public.shift_reconciliations
    (shift_id, store_id, count_id, expected_cash, expected_card, expected_digital,
     counted_cash, counted_card, counted_digital, variance_cash, variance_card,
     variance_digital, variance_total, variance_status)
  VALUES
    (p_shift, v.store_id, v_count, e.expected_cash, e.expected_card, e.expected_digital,
     p_cash, p_card, p_digital, v_var_cash, v_var_card, v_var_digital, v_total, v_status)
  RETURNING id INTO v_rec;

  PERFORM set_config(''pos.shift_fn'', ''on'', true);
  UPDATE public.shifts SET
    counted_cash = p_cash, final_counted_cash = p_cash, closing_float = p_cash,
    counted_card = p_card, counted_digital = p_digital,
    expected_cash = e.expected_cash, expected_card = e.expected_card,
    expected_digital = e.expected_digital, variance_cash = v_var_cash,
    variance_card = v_var_card, variance_digital = v_var_digital,
    variance_total = v_total, variance_status = v_status,
    row_version = coalesce(row_version, 0) + 1, updated_at = now()
  WHERE id = p_shift;
  PERFORM set_config(''pos.shift_fn'', '''', true);

  v_after := jsonb_build_object(
    ''counted_cash'', p_cash, ''counted_card'', p_card, ''counted_digital'', p_digital,
    ''expected_cash'', e.expected_cash, ''expected_card'', e.expected_card,
    ''expected_digital'', e.expected_digital, ''variance_cash'', v_var_cash,
    ''variance_card'', v_var_card, ''variance_digital'', v_var_digital,
    ''variance_total'', v_total, ''variance_status'', v_status
  );
  INSERT INTO public.record_edits
    (record_type, record_id, reference, store_id, terminal_id, action_key, edited_by,
     edited_by_name, authorized_by, authorized_by_name, mode_used, before_value,
     after_value, note)
  VALUES
    (''shift'', p_shift::text, p_shift::text, v.store_id, coalesce(p_terminal, v.terminal_id),
     ''SHIFT_CLOSE_CORRECTED'', nullif(p_actor_id, ''''), nullif(p_actor_name, ''''),
     nullif(p_actor_id, ''''), nullif(p_actor_name, ''''), ''admin'', v_before, v_after, v_reason);
  INSERT INTO public.activity_events
    (event_type, severity, title, message, actor_id, actor_name, actor_role, terminal_id, store_id,
     entity_type, entity_id, amount, meta, client_event_id)
  VALUES
    (''shift_close_corrected'', ''warning'', ''Closed shift corrected'', v_reason, nullif(p_actor_id, ''''),
     nullif(p_actor_name, ''''), ''admin'', coalesce(p_terminal, v.terminal_id), v.store_id,
     ''shift'', p_shift::text, v_total,
     jsonb_build_object(''before'', v_before, ''after'', v_after, ''reconciliation_id'', v_rec),
     ''shift-correction:'' || p_client_key)
  ON CONFLICT DO NOTHING;
  PERFORM fin62_web_preparation.end_action(p_shift,v_count);
  RETURN jsonb_build_object(''ok'', true, ''replayed'', false, ''shift_id'', p_shift,
                            ''variance_total'', v_total, ''variance_status'', v_status);
END $function$
';
 SELECT * INTO STRICT after_row FROM pg_proc WHERE oid=routine;
 IF after_row.proowner IS DISTINCT FROM before_row.proowner OR after_row.proacl IS DISTINCT FROM before_row.proacl OR after_row.proconfig IS DISTINCT FROM before_row.proconfig OR after_row.prosecdef IS DISTINCT FROM before_row.prosecdef OR after_row.proargtypes IS DISTINCT FROM before_row.proargtypes OR after_row.proargdefaults::text IS DISTINCT FROM before_row.proargdefaults::text OR after_row.prorettype IS DISTINCT FROM before_row.prorettype THEN RAISE EXCEPTION 'FIN62_WEB_AUTHORITY_CHANGED';END IF;
 SELECT oid INTO STRICT routine FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='shift_cash_count_submit';
 SELECT * INTO STRICT before_row FROM pg_proc WHERE oid=routine;
 IF md5(replace(pg_get_functiondef(routine),E'\r\n',E'\n'))<>'7da4fe386d35979d7b7cbc89f00a0dc6' THEN RAISE EXCEPTION 'FIN62_WEB_SOURCE_CHANGED';END IF;
 EXECUTE 'CREATE OR REPLACE FUNCTION public.shift_cash_count_submit(p_shift uuid, p_cash numeric, p_card numeric DEFAULT NULL::numeric, p_digital numeric DEFAULT NULL::numeric, p_client_key text DEFAULT NULL::text, p_terminal text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''public'', ''pg_temp''
AS $function$
DECLARE v public.shifts%ROWTYPE; v_me record; v_count uuid; v_res record;
BEGIN
  IF NOT (public.has_perm(''can_shift_cash_count'') OR public.has_perm(''can_close_shift'')) THEN
    RAISE EXCEPTION ''You do not have permission to submit a cash count.'';
  END IF;
  IF p_cash IS NULL OR p_cash < 0 THEN RAISE EXCEPTION ''Enter the cash counted in the drawer.''; END IF;
  IF p_card IS NOT NULL AND p_card < 0 THEN RAISE EXCEPTION ''The card total counted cannot be negative.''; END IF;
  IF p_digital IS NOT NULL AND p_digital < 0 THEN RAISE EXCEPTION ''The digital total counted cannot be negative.''; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(''pos-sync-shift:''||p_shift::text,0));
  SELECT * INTO v FROM public.shifts WHERE id = p_shift FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION ''That shift no longer exists.''; END IF;
  IF NOT public.store_visible(v.store_id) THEN RAISE EXCEPTION ''That shift belongs to another branch.''; END IF;
  IF v.state = ''ACTIVE'' THEN RAISE EXCEPTION ''Start the closing process before counting the drawer.''; END IF;
  IF v.state NOT IN (''CLOSING_STARTED'',''CASH_COUNT_REQUIRED'') THEN
    RETURN v.state;  -- already counted: never accept a second original count
  END IF;

  -- Preserve existing raw API rounding; capture validates the actual saved count.
  SELECT * INTO v_me FROM public.current_app_user();
  PERFORM set_config(''pos.shift_fn'', ''on'', true);
  INSERT INTO public.shift_cash_counts
    (shift_id, store_id, terminal_id, kind, counted_cash, counted_card, counted_digital,
     reason, counted_by_name, counted_by_staff_id, counted_by_user_id, client_key)
  VALUES (p_shift, v.store_id, coalesce(p_terminal, v.terminal_id), ''ORIGINAL'',
          round(p_cash, 2), round(p_card, 2), round(p_digital, 2), v.close_reason,
          coalesce(v_me.full_name, v.opened_by_name), v_me.user_id, auth.uid(), p_client_key)
  ON CONFLICT (shift_id) WHERE kind = ''ORIGINAL'' DO NOTHING
  RETURNING id INTO v_count;

  IF v_count IS NULL THEN RAISE EXCEPTION ''FIN62_WEB_EXISTING_ORIGINAL_REQUIRES_REVIEW''; END IF;
  PERFORM fin62_web_preparation.capture_expected(p_shift,v_count,''ORIGINAL'');

  UPDATE public.shifts SET state = ''CASH_COUNT_SUBMITTED'', updated_at = now() WHERE id = p_shift;
  PERFORM set_config(''pos.shift_fn'', '''', true);

  IF v_count IS NULL THEN
    SELECT id INTO v_count FROM public.shift_cash_counts
      WHERE shift_id = p_shift AND kind = ''ORIGINAL'' LIMIT 1;
  END IF;

  PERFORM public.shift_log_event(p_shift, ''cash_count_submitted'', ''CASH_COUNT_REQUIRED'',
    ''CASH_COUNT_SUBMITTED'', jsonb_build_object(''count_id'', v_count), p_terminal);

  SELECT * INTO v_res FROM public.shift_reconcile_now(p_shift, v_count, round(p_cash,2), round(p_card,2), round(p_digital,2));
  PERFORM fin62_web_preparation.end_action(p_shift,v_count);
  RETURN v_res.state;  -- state only: never the variance
END $function$
';
 SELECT * INTO STRICT after_row FROM pg_proc WHERE oid=routine;
 IF after_row.proowner IS DISTINCT FROM before_row.proowner OR after_row.proacl IS DISTINCT FROM before_row.proacl OR after_row.proconfig IS DISTINCT FROM before_row.proconfig OR after_row.prosecdef IS DISTINCT FROM before_row.prosecdef OR after_row.proargtypes IS DISTINCT FROM before_row.proargtypes OR after_row.proargdefaults::text IS DISTINCT FROM before_row.proargdefaults::text OR after_row.prorettype IS DISTINCT FROM before_row.prorettype THEN RAISE EXCEPTION 'FIN62_WEB_AUTHORITY_CHANGED';END IF;
 SELECT oid INTO STRICT routine FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='shift_reconcile_now';
 SELECT * INTO STRICT before_row FROM pg_proc WHERE oid=routine;
 IF md5(replace(pg_get_functiondef(routine),E'\r\n',E'\n')) NOT IN('04a2bce3bfad4277dcc9aa2751f6ddbd','920af85fa748db61b9d9c723c16eb495') THEN RAISE EXCEPTION 'FIN62_WEB_SOURCE_CHANGED';END IF;
 EXECUTE 'CREATE OR REPLACE FUNCTION public.shift_reconcile_now(p_shift uuid, p_count_id uuid, p_cash numeric, p_card numeric, p_digital numeric)
 RETURNS TABLE(state text, variance_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''public'', ''pg_temp''
AS $function$
DECLARE
  v public.shifts%ROWTYPE; e record; v_rec uuid;
  v_var_cash numeric; v_var_card numeric; v_var_digital numeric; v_total numeric;
  v_status text; v_threshold numeric := 0; v_state text;
  v_store_name text; v_cashier text; v_terminal text; v_msg text;
  v_total_sales numeric := 0; v_net_cash_sales numeric := 0;
BEGIN
  SELECT * INTO v FROM public.shifts WHERE id = p_shift;
  SELECT * INTO e FROM fin62_web_preparation.action_expected(p_shift,p_count_id);

  v_var_cash    := round(p_cash - e.expected_cash, 2);
  v_var_card    := CASE WHEN p_card IS NULL THEN NULL ELSE round(p_card - e.expected_card, 2) END;
  v_var_digital := CASE WHEN p_digital IS NULL THEN NULL ELSE round(p_digital - e.expected_digital, 2) END;
  v_total       := round(v_var_cash + coalesce(v_var_card,0) + coalesce(v_var_digital,0), 2);

  SELECT coalesce(abs((r ->> ''variance_pin_threshold'')::numeric), 0) INTO v_threshold
    FROM public.pos_rules_get() AS r;
  IF v_threshold IS NULL THEN v_threshold := 0; END IF;

  v_status := CASE WHEN abs(v_total) <= 0.005 THEN ''NO_VARIANCE''
                   WHEN v_total > 0 THEN ''OVER'' ELSE ''SHORT'' END;

  -- The counted amount is final. A difference is recorded and reported, never
  -- a reason to keep the shift open.
  v_state := ''CLOSED'';

  PERFORM set_config(''pos.shift_fn'', ''on'', true);
  INSERT INTO public.shift_reconciliations
    (shift_id, store_id, count_id, expected_cash, expected_card, expected_digital,
     counted_cash, counted_card, counted_digital,
     variance_cash, variance_card, variance_digital, variance_total, variance_status)
  VALUES (p_shift, v.store_id, p_count_id, e.expected_cash, e.expected_card, e.expected_digital,
          p_cash, p_card, p_digital, v_var_cash, v_var_card, v_var_digital, v_total, v_status)
  RETURNING id INTO v_rec;

  UPDATE public.shifts
     SET state = v_state,
         status = ''CLOSED'',
         closed_at = coalesce(closed_at, now()),
         final_counted_cash = p_cash,
         counted_cash = p_cash,
         closing_float = p_cash,
         counted_card = p_card,
         counted_digital = p_digital,
         expected_cash = e.expected_cash,
         expected_card = e.expected_card,
         expected_digital = e.expected_digital,
         variance_cash = v_var_cash,
         variance_card = v_var_card,
         variance_digital = v_var_digital,
         variance_total = v_total,
         variance_status = v_status,
         updated_at = now()
   WHERE id = p_shift;

  IF v_status <> ''NO_VARIANCE'' THEN
    SELECT coalesce(nullif(btrim(name), ''''), v.store_id) INTO v_store_name
      FROM public.stores WHERE id = v.store_id;
    v_store_name := coalesce(v_store_name, v.store_id, '''');
    SELECT coalesce(nullif(btrim(counted_by_name), ''''), v.opened_by_name, '''')
      INTO v_cashier
      FROM public.shift_cash_counts WHERE id = p_count_id;
    v_cashier := coalesce(v_cashier, v.opened_by_name, '''');
    v_terminal := coalesce(nullif(btrim(v.terminal_name), ''''), v.terminal_id, '''');
    SELECT coalesce(sum(s.total_amount), 0) INTO v_total_sales
      FROM public.sales s
     WHERE s.shift_id = p_shift::text AND coalesce(s.is_refunded, false) = false;
    v_net_cash_sales := round(e.expected_cash - coalesce(v.opening_float, 0), 2);

    INSERT INTO public.shift_variance_alerts
      (shift_id, store_id, reconciliation_id, variance_total, variance_status, severity, message)
    VALUES (p_shift, v.store_id, v_rec, v_total, v_status,
            CASE WHEN abs(v_total) > v_threshold THEN ''critical'' ELSE ''warning'' END,
            format(''Shift at %s closed %s by %s. Cashier %s, terminal %s. Opening %s, sales %s, net cash sales %s, expected cash %s, counted cash %s.'',
                   v_store_name, lower(v_status), abs(v_total), v_cashier, v_terminal,
                   to_char(coalesce(v.opening_float, 0), ''FM999999990.00''),
                   to_char(v_total_sales, ''FM999999990.00''),
                   to_char(v_net_cash_sales, ''FM999999990.00''),
                   to_char(e.expected_cash, ''FM999999990.00''), to_char(p_cash, ''FM999999990.00'')))
    ON CONFLICT (reconciliation_id) DO NOTHING;

    v_msg := format(
      E''Cashier: %s\nBranch: %s\nTerminal: %s\nShift: %s\nClosed: %s\n\nOpening float: %s\nTotal sales: %s\nNet cash sales: %s\nExpected cash: %s\nCounted cash: %s\nCard expected / counted: %s / %s\nDigital expected / counted: %s / %s\nVariance: %s\n\nType: Cash %s'',
      v_cashier, v_store_name, v_terminal,
      p_shift::text, to_char(now(), ''YYYY-MM-DD HH24:MI:SS TZ''),
      to_char(coalesce(v.opening_float, 0), ''FM999999990.00''),
      to_char(v_total_sales, ''FM999999990.00''),
      to_char(v_net_cash_sales, ''FM999999990.00''),
      to_char(e.expected_cash, ''FM999999990.00''),
      to_char(p_cash, ''FM999999990.00''),
      to_char(e.expected_card, ''FM999999990.00''), coalesce(to_char(p_card, ''FM999999990.00''), ''not counted''),
      to_char(e.expected_digital, ''FM999999990.00''), coalesce(to_char(p_digital, ''FM999999990.00''), ''not counted''),
      CASE WHEN v_total > 0 THEN ''+'' ELSE ''-'' END || to_char(abs(v_total), ''FM999999990.00''),
      CASE WHEN v_total > 0 THEN ''Overage'' ELSE ''Shortage'' END);

    -- The shared notification feed: one row per shift, so a replay of the
    -- close after an outage can never raise a second alert.
    INSERT INTO public.activity_events
      (event_type, severity, title, message, actor_name, terminal_id, store_id,
       branch_id, entity_type, entity_id, amount, meta, client_event_id, created_at)
    VALUES (''shift_cash_variance'',
            CASE WHEN abs(v_total) > v_threshold THEN ''critical'' ELSE ''warning'' END,
            ''Shift cash variance detected'', v_msg, nullif(v_cashier, ''''),
            nullif(v_terminal, ''''), v.store_id, v.store_id, ''shift'', p_shift::text, v_total,
            jsonb_build_object(''branch_name'', v_store_name, ''terminal_name'', v_terminal,
                               ''opened_at'', v.opened_at, ''closed_at'', now(),
                               ''opening_float'', coalesce(v.opening_float, 0),
                               ''total_sales'', v_total_sales, ''net_cash_sales'', v_net_cash_sales,
                               ''expected_cash'', e.expected_cash, ''counted_cash'', p_cash,
                               ''expected_card'', e.expected_card, ''counted_card'', p_card,
                               ''expected_digital'', e.expected_digital, ''counted_digital'', p_digital,
                               ''variance_total'', v_total, ''variance_status'', v_status,
                               ''reconciliation_id'', v_rec),
            ''shift:'' || p_shift::text || '':cash_variance'', now())
    ON CONFLICT (client_event_id) DO NOTHING;
  END IF;
  PERFORM set_config(''pos.shift_fn'', '''', true);

  PERFORM public.shift_log_event(p_shift, ''reconciled'', ''CASH_COUNT_SUBMITTED'', v_state,
    jsonb_build_object(''variance_status'', v_status, ''variance_total'', v_total), v.terminal_id);


  RETURN QUERY SELECT v_state, v_status;
END $function$
';
 SELECT * INTO STRICT after_row FROM pg_proc WHERE oid=routine;
 IF after_row.proowner IS DISTINCT FROM before_row.proowner OR after_row.proacl IS DISTINCT FROM before_row.proacl OR after_row.proconfig IS DISTINCT FROM before_row.proconfig OR after_row.prosecdef IS DISTINCT FROM before_row.prosecdef OR after_row.proargtypes IS DISTINCT FROM before_row.proargtypes OR after_row.proargdefaults::text IS DISTINCT FROM before_row.proargdefaults::text OR after_row.prorettype IS DISTINCT FROM before_row.prorettype THEN RAISE EXCEPTION 'FIN62_WEB_AUTHORITY_CHANGED';END IF;
 SELECT oid INTO STRICT routine FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='shift_recount_submit';
 SELECT * INTO STRICT before_row FROM pg_proc WHERE oid=routine;
 IF md5(replace(pg_get_functiondef(routine),E'\r\n',E'\n'))<>'fa77acc46f885c1734e18d883d4f7f89' THEN RAISE EXCEPTION 'FIN62_WEB_SOURCE_CHANGED';END IF;
 EXECUTE 'CREATE OR REPLACE FUNCTION public.shift_recount_submit(p_shift uuid, p_cash numeric, p_reason text, p_card numeric DEFAULT NULL::numeric, p_digital numeric DEFAULT NULL::numeric, p_terminal text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''public'', ''pg_temp''
AS $function$
DECLARE v public.shifts%ROWTYPE; v_me record; v_count uuid; v_res record; v_reason text := btrim(coalesce(p_reason,''''));
BEGIN
  IF NOT public.has_perm(''can_shift_cash_recount'') THEN
    RAISE EXCEPTION ''You do not have permission to recount a drawer.'';
  END IF;
  IF v_reason = '''' THEN RAISE EXCEPTION ''A reason for the recount is required.''; END IF;
  IF p_cash IS NULL OR p_cash < 0 THEN RAISE EXCEPTION ''Enter the recounted cash amount.''; END IF;
  IF p_card IS NOT NULL AND p_card < 0 THEN RAISE EXCEPTION ''The card total counted cannot be negative.''; END IF;
  IF p_digital IS NOT NULL AND p_digital < 0 THEN RAISE EXCEPTION ''The digital total counted cannot be negative.''; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(''pos-sync-shift:''||p_shift::text,0));
  SELECT * INTO v FROM public.shifts WHERE id = p_shift FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION ''That shift no longer exists.''; END IF;
  IF NOT public.store_visible(v.store_id) THEN RAISE EXCEPTION ''That shift belongs to another branch.''; END IF;
  IF v.state NOT IN (''VARIANCE_REVIEW_REQUIRED'',''RECONCILIATION'',''CLOSED'') THEN
    RAISE EXCEPTION ''This shift has not been counted yet.'';
  END IF;

  -- Preserve existing raw API rounding; capture validates the actual saved count.
  SELECT * INTO v_me FROM public.current_app_user();
  PERFORM set_config(''pos.shift_fn'', ''on'', true);
  INSERT INTO public.shift_cash_counts
    (shift_id, store_id, terminal_id, kind, counted_cash, counted_card, counted_digital,
     reason, counted_by_name, counted_by_staff_id, counted_by_user_id)
  VALUES (p_shift, v.store_id, coalesce(p_terminal, v.terminal_id), ''RECOUNT'',
          round(p_cash,2), round(p_card,2), round(p_digital,2), v_reason,
          v_me.full_name, v_me.user_id, auth.uid())
  RETURNING id INTO v_count;
  PERFORM fin62_web_preparation.capture_expected(p_shift,v_count,''RECOUNT'');
  PERFORM set_config(''pos.shift_fn'', '''', true);

  PERFORM public.shift_log_event(p_shift, ''recount_submitted'', v.state, v.state,
    jsonb_build_object(''reason'', v_reason, ''count_id'', v_count), p_terminal);

  SELECT * INTO v_res FROM public.shift_reconcile_now(p_shift, v_count, round(p_cash,2), round(p_card,2), round(p_digital,2));
  PERFORM fin62_web_preparation.end_action(p_shift,v_count);
  RETURN v_res.state;
END $function$
';
 SELECT * INTO STRICT after_row FROM pg_proc WHERE oid=routine;
 IF after_row.proowner IS DISTINCT FROM before_row.proowner OR after_row.proacl IS DISTINCT FROM before_row.proacl OR after_row.proconfig IS DISTINCT FROM before_row.proconfig OR after_row.prosecdef IS DISTINCT FROM before_row.prosecdef OR after_row.proargtypes IS DISTINCT FROM before_row.proargtypes OR after_row.proargdefaults::text IS DISTINCT FROM before_row.proargdefaults::text OR after_row.prorettype IS DISTINCT FROM before_row.prorettype THEN RAISE EXCEPTION 'FIN62_WEB_AUTHORITY_CHANGED';END IF;
END $patch$;
CREATE FUNCTION fin62_web_preparation.begin_graph(p_shift uuid,p_branch text) RETURNS boolean LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF to_regclass('fin62_history_preparation.protected_shifts') IS NULL THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT 1 FROM fin62_history_preparation.protected_shifts WHERE shift_id=p_shift AND branch_id=p_branch) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM fin62_history_preparation.graph_context WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id()) THEN RAISE EXCEPTION 'FIN62_WEB_GRAPH_CONTEXT_BUSY';END IF;
 INSERT INTO fin62_history_preparation.graph_context VALUES(pg_backend_pid(),pg_current_xact_id(),p_branch,p_shift);RETURN true;
END $$;
CREATE FUNCTION fin62_web_preparation.end_graph(p_shift uuid,p_branch text,p_owned boolean) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF p_owned THEN DELETE FROM fin62_history_preparation.graph_context WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id() AND branch_id=p_branch AND shift_id=p_shift;IF NOT FOUND THEN RAISE EXCEPTION 'FIN62_WEB_GRAPH_CONTEXT_MISSING';END IF;END IF;
END $$;
REVOKE ALL ON FUNCTION fin62_web_preparation.begin_graph(uuid,text),fin62_web_preparation.end_graph(uuid,text,boolean) FROM PUBLIC,anon,authenticated,service_role;
DO $aliases$
DECLARE name text;routine oid;before_row pg_proc%ROWTYPE;after_row pg_proc%ROWTYPE;source text;
BEGIN
 FOREACH name IN ARRAY ARRAY['shift_close_start','shift_variance_approve'] LOOP
  SELECT oid INTO STRICT routine FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=name;
  SELECT * INTO STRICT before_row FROM pg_proc WHERE oid=routine;
  source:=replace(pg_get_functiondef(routine),E'\r\n',E'\n');
  source:=replace(source,'SELECT * INTO v FROM public.shifts WHERE id = p_shift FOR UPDATE;','PERFORM pg_advisory_xact_lock(hashtextextended(''pos-sync-shift:''||p_shift::text,0)); SELECT * INTO v FROM public.shifts WHERE id = p_shift FOR UPDATE;');
  source:=replace(source,'DECLARE v public.shifts%ROWTYPE;','DECLARE v_fin62_graph boolean := false; v public.shifts%ROWTYPE;');
  IF name='shift_variance_approve' THEN
   source:=replace(source,'IF v.state = ''CLOSED'' THEN RETURN ''CLOSED''; END IF;','IF NOT public.store_visible(v.store_id) THEN RAISE EXCEPTION ''That shift belongs to another branch.'';END IF; IF v.state = ''CLOSED'' THEN RETURN ''CLOSED''; END IF;');
  END IF;
  source:=replace(source,'PERFORM set_config(''pos.shift_fn'', ''on'', true);','v_fin62_graph := fin62_web_preparation.begin_graph(p_shift,v.store_id); PERFORM set_config(''pos.shift_fn'', ''on'', true);');
  IF name='shift_close_start' THEN source:=replace(source,'RETURN ''CASH_COUNT_REQUIRED'';','PERFORM fin62_web_preparation.end_graph(p_shift,v.store_id,v_fin62_graph); RETURN ''CASH_COUNT_REQUIRED'';');
  ELSE source:=replace(source,'RETURN ''CLOSED'';'||E'\nEND','PERFORM fin62_web_preparation.end_graph(p_shift,v.store_id,v_fin62_graph); RETURN ''CLOSED'';'||E'\nEND');END IF;
  IF source=pg_get_functiondef(routine) OR strpos(source,'v_fin62_graph := fin62_web_preparation.begin_graph')=0 OR strpos(source,'PERFORM fin62_web_preparation.end_graph')=0 THEN RAISE EXCEPTION 'FIN62_WEB_ALIAS_PATCH_UNEXPECTED';END IF;
  EXECUTE source;SELECT * INTO STRICT after_row FROM pg_proc WHERE oid=routine;
  IF after_row.proowner IS DISTINCT FROM before_row.proowner OR after_row.proacl IS DISTINCT FROM before_row.proacl OR after_row.proconfig IS DISTINCT FROM before_row.proconfig OR after_row.prosecdef IS DISTINCT FROM before_row.prosecdef OR after_row.proargtypes IS DISTINCT FROM before_row.proargtypes OR after_row.proargdefaults::text IS DISTINCT FROM before_row.proargdefaults::text OR after_row.prorettype IS DISTINCT FROM before_row.prorettype THEN RAISE EXCEPTION 'FIN62_WEB_AUTHORITY_CHANGED';END IF;
 END LOOP;
END $aliases$;

-- Source: scripts/preparation/shift-financial-live-business.sql
-- Canonical source SHA256: A014E7A06AEB4A4B42C4825EF0C899466AE9D09726B3B52886E06881266B5A8E
-- FIN62 PREPARATION ONLY. Not a registered migration or activation.
-- Service-only adapters consume the hosted relay's freshly verified app-user
-- UUID. They do not authenticate that UUID themselves or expose a JWT bypass.
-- Original sale INVOKER/RLS and refund routines are not replaced.
DO $pins$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='public.pos_sale_commit(jsonb,jsonb,jsonb,jsonb,jsonb,text)'::regprocedure AND NOT prosecdef AND proowner='postgres'::regrole AND md5(replace(pg_get_functiondef(oid),E'\r\n',E'\n')) IN('670c036818c06e99f7963fb9d5d30905','0a8f6fc976060f01aaca6710cae7db02')) OR
  NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='public.sale_refund(uuid,jsonb,text,text,text)'::regprocedure AND prosecdef AND proowner='postgres'::regrole AND md5(replace(pg_get_functiondef(oid),E'\r\n',E'\n'))='2095254e1769d3c21f3df057a3117247') THEN RAISE EXCEPTION 'FIN62_LIVE_SOURCE_UNEXPECTED';END IF;
END $pins$;
CREATE SCHEMA fin62_live_preparation;
REVOKE ALL ON SCHEMA fin62_live_preparation FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE fin62_live_preparation.receipts(
 operation_id uuid PRIMARY KEY,action text NOT NULL CHECK(action IN('SALE','REFUND')),
 sale_id uuid NOT NULL,branch_id text NOT NULL,shift_id uuid,organization_id text,terminal_id text,author_id uuid NOT NULL,
 request_key text NOT NULL,request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'),
 before_row jsonb,after_row jsonb NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(action,sale_id,request_key)
);
ALTER TABLE fin62_live_preparation.receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_live_preparation.receipts FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON fin62_live_preparation.receipts FOR EACH ROW EXECUTE FUNCTION fin62_history_preparation.immutable();
CREATE INDEX receipts_scope_sale ON fin62_live_preparation.receipts(branch_id,shift_id,sale_id);
CREATE FUNCTION fin62_live_preparation.authorize(p_author uuid,p_branch text,p_terminal text,p_action text) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE a public.app_users%ROWTYPE;device public.terminal_tokens%ROWTYPE;admin boolean;supervisor boolean;permission text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_LIVE_SERVICE_REQUIRED';END IF;
 SELECT * INTO a FROM public.app_users WHERE id=p_author AND is_active IS TRUE FOR SHARE;
 IF NOT FOUND OR nullif(p_branch,'') IS NULL OR p_action NOT IN('SALE','REFUND') THEN RAISE EXCEPTION 'FIN62_LIVE_AUTHOR_INVALID';END IF;
 admin:=coalesce(a.role::text='admin' OR a.role_slug='admin',false);
 supervisor:=admin OR coalesce(a.role::text='manager' OR a.role_slug='supervisor',false);
 permission:=CASE WHEN p_action='SALE' THEN 'can_process_sale' ELSE 'can_process_refund' END;
 IF NOT admin AND a.permissions->permission IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'FIN62_LIVE_PERMISSION_DENIED';END IF;
 IF p_terminal IS NOT NULL THEN
  SELECT * INTO device FROM public.terminal_tokens WHERE id::text=p_terminal AND status IN('active','used') AND revoked_at IS NULL FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FIN62_LIVE_BRANCH_DENIED';END IF;
  IF nullif(a.store_id,'') IS NOT NULL AND lower(a.store_id)<>lower(p_branch) THEN RAISE EXCEPTION 'FIN62_LIVE_BRANCH_DENIED';END IF;
  IF device.location_id IS NULL THEN
   -- Actual read admission proves the registered Management device capability;
   -- the separate fresh person/action/branch rules still govern this write.
   PERFORM public.pos_sync_validate_read_scope('default',p_branch,p_terminal);
   IF NOT pos_sync_private.shift_author_management_allowed(a.role::text,a.role_slug,a.permissions) OR (NOT supervisor AND a.store_id IS DISTINCT FROM p_branch) THEN RAISE EXCEPTION 'FIN62_LIVE_BRANCH_DENIED';END IF;
  ELSIF device.location_id IS DISTINCT FROM p_branch OR (nullif(a.store_id,'') IS NOT NULL AND lower(a.store_id)<>lower(p_branch)) THEN RAISE EXCEPTION 'FIN62_LIVE_BRANCH_DENIED';END IF;
 ELSIF NOT supervisor AND a.store_id IS DISTINCT FROM p_branch THEN RAISE EXCEPTION 'FIN62_LIVE_BRANCH_DENIED';END IF;
END $$;
CREATE FUNCTION fin62_live_preparation.organization(p_branch text,p_shift uuid) RETURNS text LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT CASE WHEN count(DISTINCT organization_id)=1 THEN min(organization_id) ELSE NULL END FROM fin62_history_preparation.streams WHERE branch_id=p_branch AND shift_id=p_shift;
$$;
CREATE FUNCTION public.pos_live_financial_sale(p_author uuid,p_branch text,p_terminal text,p_sale jsonb,p_items jsonb,p_payments jsonb,p_movements jsonb,p_member jsonb,p_exchange_bill text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE sid uuid;shift uuid;op uuid:=gen_random_uuid();request text;digest text;before_row jsonb;after_row jsonb;result jsonb;prior fin62_live_preparation.receipts%ROWTYPE;org text;
BEGIN
 PERFORM fin62_live_preparation.authorize(p_author,p_branch,p_terminal,'SALE');
 sid:=(p_sale->>'id')::uuid;shift:=nullif(p_sale->>'shift_id','')::uuid;
 IF sid IS NULL OR p_sale->>'store_id' IS DISTINCT FROM p_branch THEN RAISE EXCEPTION 'FIN62_LIVE_SALE_SCOPE';END IF;
 IF coalesce(p_sale->>'original_bill_number','') LIKE 'OLDPOS:%' AND NOT EXISTS(SELECT 1 FROM public.app_users WHERE id=p_author AND (role::text='admin' OR role_slug='admin')) THEN RAISE EXCEPTION 'FIN62_LIVE_ADMIN_REQUIRED';END IF;
 request:=coalesce(nullif(p_sale->>'client_transaction_id',''),sid::text);
 digest:=encode(sha256(convert_to(jsonb_build_array(p_author,p_branch,p_terminal,p_sale,p_items,p_payments,p_movements,p_member,p_exchange_bill)::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('fin62-live-sale:'||sid,0));
 IF shift IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-shift:'||shift,0));PERFORM 1 FROM public.shifts WHERE id=shift AND store_id=p_branch FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'FIN62_LIVE_SHIFT_SCOPE';END IF;END IF;
 SELECT * INTO prior FROM fin62_live_preparation.receipts WHERE action='SALE' AND sale_id=sid AND request_key=request;
 IF FOUND THEN IF prior.request_hash<>digest THEN RAISE EXCEPTION 'FIN62_LIVE_REPLAY_MISMATCH';END IF;RETURN prior.result;END IF;
 SELECT to_jsonb(s) INTO before_row FROM public.sales s WHERE id=sid FOR UPDATE;
 IF before_row IS NOT NULL AND ROW(before_row->>'store_id',before_row->>'shift_id') IS DISTINCT FROM ROW(p_branch,shift::text) THEN RAISE EXCEPTION 'FIN62_LIVE_SALE_SCOPE';END IF;
 org:=fin62_live_preparation.organization(p_branch,shift);
 IF before_row IS NULL THEN
  INSERT INTO fin62_history_preparation.sale_birth_claims(sale_id,organization_id,branch_id,terminal_id,shift_id,operation_id) VALUES(sid,org,p_branch,p_terminal,shift,op);
 END IF;
 INSERT INTO fin62_history_preparation.live_context VALUES(pg_backend_pid(),pg_current_xact_id(),p_branch,shift,sid,p_author,'SALE');
 result:=public.pos_sale_commit(p_sale,p_items,p_payments,p_movements,p_member,p_exchange_bill);
 SELECT to_jsonb(s) INTO STRICT after_row FROM public.sales s WHERE id=sid AND store_id=p_branch;
 INSERT INTO fin62_live_preparation.receipts VALUES(op,'SALE',sid,p_branch,shift,org,p_terminal,p_author,request,digest,before_row,after_row,result,now());
 DELETE FROM fin62_history_preparation.live_context WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id();
 RETURN result;
END $$;
CREATE FUNCTION public.pos_live_financial_refund(p_author uuid,p_branch text,p_terminal text,p_sale_id uuid,p_lines jsonb,p_client_refund_id text,p_reason text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE shift uuid;op uuid:=gen_random_uuid();request text;digest text;before_row jsonb;after_row jsonb;result jsonb;prior fin62_live_preparation.receipts%ROWTYPE;
BEGIN
 PERFORM fin62_live_preparation.authorize(p_author,p_branch,p_terminal,'REFUND');
 request:=coalesce(nullif(btrim(p_client_refund_id),''),p_sale_id::text);
 digest:=encode(sha256(convert_to(jsonb_build_array(p_author,p_branch,p_terminal,p_sale_id,p_lines,p_client_refund_id,p_reason)::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('fin62-live-sale:'||p_sale_id,0));
 SELECT nullif(shift_id,'')::uuid INTO shift FROM public.sales WHERE id=p_sale_id AND store_id=p_branch;
 IF NOT FOUND THEN RAISE EXCEPTION 'FIN62_LIVE_SALE_SCOPE';END IF;
 IF shift IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-shift:'||shift,0));PERFORM 1 FROM public.shifts WHERE id=shift AND store_id=p_branch FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'FIN62_LIVE_SHIFT_SCOPE';END IF;END IF;
 SELECT * INTO prior FROM fin62_live_preparation.receipts WHERE action='REFUND' AND sale_id=p_sale_id AND request_key=request;
 IF FOUND THEN IF prior.request_hash<>digest THEN RAISE EXCEPTION 'FIN62_LIVE_REPLAY_MISMATCH';END IF;RETURN prior.result;END IF;
 SELECT to_jsonb(s) INTO STRICT before_row FROM public.sales s WHERE id=p_sale_id AND store_id=p_branch FOR UPDATE;
 IF before_row->>'shift_id' IS DISTINCT FROM shift::text THEN RAISE EXCEPTION 'FIN62_LIVE_SALE_SCOPE';END IF;
 INSERT INTO fin62_history_preparation.live_context VALUES(pg_backend_pid(),pg_current_xact_id(),p_branch,shift,p_sale_id,p_author,'REFUND');
 result:=public.sale_refund(p_sale_id,p_lines,p_client_refund_id,p_reason,p_branch);
 SELECT to_jsonb(s) INTO STRICT after_row FROM public.sales s WHERE id=p_sale_id AND store_id=p_branch;
 INSERT INTO fin62_live_preparation.receipts VALUES(op,'REFUND',p_sale_id,p_branch,shift,fin62_live_preparation.organization(p_branch,shift),p_terminal,p_author,request,digest,before_row,after_row,result,now());
 DELETE FROM fin62_history_preparation.live_context WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id();
 RETURN result;
END $$;
CREATE FUNCTION fin62_live_preparation.publication_edges(p_org text,p_branch text,p_shift uuid,p_sale uuid) RETURNS TABLE(operation_id uuid,before_fact jsonb,after_fact jsonb)
LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT r.operation_id,fin62_history_preparation.row_fact(r.before_row),fin62_history_preparation.row_fact(r.after_row)
 FROM fin62_live_preparation.receipts r WHERE r.branch_id=p_branch AND r.shift_id=p_shift AND r.sale_id=p_sale AND
 (r.organization_id=p_org OR (r.organization_id IS NULL AND EXISTS(SELECT 1 FROM fin62_history_preparation.streams s WHERE s.organization_id=p_org AND s.branch_id=p_branch AND s.shift_id=p_shift))) AND
 fin62_history_preparation.row_snapshot_fact(r.before_row) IS DISTINCT FROM fin62_history_preparation.row_snapshot_fact(r.after_row);
$$;
CREATE FUNCTION fin62_live_preparation.proves_later_publication(p_org text,p_branch text,p_shift uuid,p_sale uuid,p_before jsonb,p_after jsonb) RETURNS boolean
LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 WITH RECURSIVE raw_steps AS(
  SELECT r.operation_id,r.before_row,r.after_row FROM fin62_live_preparation.receipts r WHERE r.branch_id=p_branch AND r.shift_id=p_shift AND r.sale_id=p_sale AND
   (r.organization_id=p_org OR (r.organization_id IS NULL AND EXISTS(SELECT 1 FROM fin62_history_preparation.streams s WHERE s.organization_id=p_org AND s.branch_id=p_branch AND s.shift_id=p_shift)))
 ),steps AS MATERIALIZED(
  SELECT operation_id,fin62_history_preparation.row_snapshot_fact(before_row) before_fact,fin62_history_preparation.row_snapshot_fact(after_row) after_fact FROM raw_steps
  WHERE fin62_history_preparation.row_snapshot_fact(before_row) IS DISTINCT FROM fin62_history_preparation.row_snapshot_fact(after_row)
 ),chain AS(
  SELECT s.*,ARRAY[s.operation_id] seen FROM steps s WHERE s.before_fact IS NOT DISTINCT FROM p_before
  UNION ALL SELECT s.*,c.seen||s.operation_id FROM chain c JOIN steps s ON NOT s.operation_id=ANY(c.seen) AND cardinality(c.seen)<2 AND s.before_fact IS NOT DISTINCT FROM c.after_fact
 ) SELECT EXISTS(SELECT 1 FROM chain WHERE after_fact IS NOT DISTINCT FROM p_after);
$$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA fin62_live_preparation FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.pos_live_financial_sale(uuid,text,text,jsonb,jsonb,jsonb,jsonb,jsonb,text),public.pos_live_financial_refund(uuid,text,text,uuid,jsonb,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pos_live_financial_sale(uuid,text,text,jsonb,jsonb,jsonb,jsonb,jsonb,text),public.pos_live_financial_refund(uuid,text,text,uuid,jsonb,text,text) TO service_role;
-- Presence of the transport module alone never activates financial writes.
CREATE FUNCTION public.pos_live_financial_ready() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_LIVE_SERVICE_REQUIRED';END IF;
 RETURN jsonb_build_object('ready',false,'version',2);
END $$;
REVOKE ALL ON FUNCTION public.pos_live_financial_ready() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pos_live_financial_ready() TO service_role;

-- Source: scripts/preparation/shift-financial-admin-aliases.sql
-- Canonical source SHA256: 7C7BA27E530ABD0ACC7E5D126E0CAA04EE9749E5E9F076B8956D3F60A6091CF2
-- FIN62 PREPARATION ONLY / NOT FINAL / NO LIVE APPLICATION OR ACTIVATION.
-- Actual existing administrator writers remain unchanged. Service adapters bind
-- the fresh verified account UUID; they do not add any Native tender/void right.
DO $pins$
DECLARE item record;
BEGIN
 FOR item IN SELECT * FROM(VALUES
 ('public.pos_admin_correct_sale(uuid,text,integer,jsonb,jsonb,text,text,text,text,uuid)','57781707788f764fb67b358017320644'),
 ('public.pos_admin_correct_tender(uuid,text,text)','d56ea4079c9cc8fc55e5120ac33de27f'),
 ('public.pos_admin_add_missed_bill(jsonb,text,text)','ef937f21c6abf19c8e1084fdd08a898e'),
 ('fin62_history_preparation.block_unintegrated_write()','26acda2fbdbeef6190afe185cee4c37d'),
 ('fin62_history_preparation.published_later_fact(text,text,uuid,uuid,jsonb,jsonb)','f3618e236f052fb87952a882178e1e3a')
 ) expected(signature,digest) LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure(item.signature) AND proowner='postgres'::regrole AND md5(replace(pg_get_functiondef(oid),chr(13)||chr(10),chr(10)))=item.digest) THEN RAISE EXCEPTION 'FIN62_ADMIN_SOURCE_UNEXPECTED: %',item.signature;END IF;
 END LOOP;
END $pins$;
CREATE SCHEMA fin62_admin_preparation;
REVOKE ALL ON SCHEMA fin62_admin_preparation FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE fin62_admin_preparation.context(pid integer NOT NULL,xid xid8 NOT NULL,branch_id text NOT NULL,shift_id uuid,sale_id uuid NOT NULL,author_id uuid NOT NULL,action text NOT NULL CHECK(action IN('SALE_CORRECTION','TENDER_CORRECTION')),PRIMARY KEY(pid,xid));
CREATE TABLE fin62_admin_preparation.receipts(
 operation_id uuid PRIMARY KEY,action text NOT NULL CHECK(action IN('SALE_CORRECTION','TENDER_CORRECTION','MISSED_BILL')),
 sale_id uuid NOT NULL,branch_id text NOT NULL,shift_id uuid,organization_id text,terminal_id text,author_id uuid NOT NULL,
 request_key uuid,request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'),before_row jsonb,after_row jsonb NOT NULL,result jsonb NOT NULL,
 capture_xid xid8 NOT NULL,evidence_order bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(action,request_key)
);
CREATE INDEX receipts_scope_sale ON fin62_admin_preparation.receipts(branch_id,shift_id,sale_id);
ALTER TABLE fin62_admin_preparation.context ENABLE ROW LEVEL SECURITY;
ALTER TABLE fin62_admin_preparation.receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA fin62_admin_preparation FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON fin62_admin_preparation.receipts FOR EACH ROW EXECUTE FUNCTION fin62_history_preparation.immutable();
CREATE FUNCTION fin62_admin_preparation.authorize(p_author uuid,p_branch text,p_terminal text) RETURNS public.app_users LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE actor public.app_users%ROWTYPE;
BEGIN
 PERFORM fin62_live_preparation.authorize(p_author,p_branch,p_terminal,'SALE');
 SELECT * INTO actor FROM public.app_users WHERE id=p_author AND is_active IS TRUE FOR SHARE;
 IF NOT FOUND OR NOT coalesce(actor.role::text='admin' OR actor.role_slug='admin',false) OR nullif(actor.user_id,'') IS NULL THEN RAISE EXCEPTION 'FIN62_ADMIN_REQUIRED';END IF;
 -- Existing administrator correction routes restrict an assigned account even
 -- in a browser. A broader title never overrides its branch assignment here.
 IF nullif(actor.store_id,'') IS NOT NULL AND lower(actor.store_id)<>lower(p_branch) THEN RAISE EXCEPTION 'FIN62_ADMIN_BRANCH_DENIED';END IF;
 RETURN actor;
END $$;
CREATE FUNCTION fin62_admin_preparation.row_allowed(p_operation text,p_old jsonb,p_new jsonb) RETURNS boolean LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE scope fin62_admin_preparation.context%ROWTYPE;before_fact jsonb;after_fact jsonb;
BEGIN
 SELECT * INTO scope FROM fin62_admin_preparation.context WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id();
 IF NOT FOUND OR p_operation<>'UPDATE' OR p_new->>'id' IS DISTINCT FROM scope.sale_id::text OR p_old->>'id' IS DISTINCT FROM scope.sale_id::text OR
  ROW(p_old->>'store_id',p_old->>'shift_id',p_new->>'store_id',p_new->>'shift_id') IS DISTINCT FROM ROW(scope.branch_id,scope.shift_id::text,scope.branch_id,scope.shift_id::text) THEN RETURN false;END IF;
 before_fact:=fin62_history_preparation.row_fact(p_old);after_fact:=fin62_history_preparation.row_fact(p_new);
 IF scope.action='SALE_CORRECTION' THEN RETURN (before_fact-ARRAY['totalAmount','discountAmount']) IS NOT DISTINCT FROM (after_fact-ARRAY['totalAmount','discountAmount']);END IF;
 IF scope.action='TENDER_CORRECTION' THEN RETURN (before_fact-ARRAY['paymentType','payments']) IS NOT DISTINCT FROM (after_fact-ARRAY['paymentType','payments']);END IF;
 RETURN false;
END $$;
DO $guard$
DECLARE definition text;needle text:=' IF fin62_history_preparation.live_row_allowed(TG_OP,CASE WHEN TG_OP=''INSERT'' THEN NULL ELSE to_jsonb(OLD) END,CASE WHEN TG_OP=''DELETE'' THEN NULL ELSE to_jsonb(NEW) END) THEN RETURN NEW;END IF;';
BEGIN
 definition:=pg_get_functiondef('fin62_history_preparation.block_unintegrated_write()'::regprocedure);
 IF (length(definition)-length(replace(definition,needle,'')))<>length(needle) THEN RAISE EXCEPTION 'FIN62_ADMIN_GUARD_SOURCE_UNEXPECTED';END IF;
 EXECUTE replace(definition,needle,' IF fin62_admin_preparation.row_allowed(TG_OP,CASE WHEN TG_OP=''INSERT'' THEN NULL ELSE to_jsonb(OLD) END,CASE WHEN TG_OP=''DELETE'' THEN NULL ELSE to_jsonb(NEW) END) THEN RETURN NEW;END IF;'||chr(10)||needle);
END $guard$;
CREATE FUNCTION public.pos_live_financial_admin_correct_sale(p_author uuid,p_sale uuid,p_store text,p_expected_version integer,p_items jsonb,p_totals jsonb,p_reason text,p_terminal text,p_client_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE actor public.app_users%ROWTYPE;shift uuid;before_row jsonb;after_row jsonb;result jsonb;request_hash text;
BEGIN
 actor:=fin62_admin_preparation.authorize(p_author,p_store,p_terminal);
 SELECT nullif(shift_id,'')::uuid INTO shift FROM public.sales WHERE id=p_sale AND store_id=p_store;
 IF NOT FOUND THEN RAISE EXCEPTION 'This bill does not belong to the selected branch';END IF;
 IF shift IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-shift:'||shift,0));END IF;
 SELECT to_jsonb(s) INTO STRICT before_row FROM public.sales s WHERE id=p_sale AND store_id=p_store FOR UPDATE;
 IF before_row->>'shift_id' IS DISTINCT FROM shift::text THEN RAISE EXCEPTION 'FIN62_ADMIN_SCOPE_CHANGED';END IF;
 -- Let the unchanged original validate and read back legacy/new exact retries.
 -- Never turn an old accepted edit into fabricated new publication evidence.
 IF EXISTS(SELECT 1 FROM public.record_edits WHERE id=p_client_key) THEN RETURN public.pos_admin_correct_sale(p_sale,p_store,p_expected_version,p_items,p_totals,p_reason,actor.user_id,coalesce(nullif(actor.full_name,''),actor.user_id),p_terminal,p_client_key);END IF;
 IF EXISTS(SELECT 1 FROM fin62_admin_preparation.receipts WHERE action='SALE_CORRECTION' AND request_key=p_client_key) THEN RAISE EXCEPTION 'FIN62_ADMIN_ORIGINAL_RECEIPT_MISSING';END IF;
 INSERT INTO fin62_admin_preparation.context VALUES(pg_backend_pid(),pg_current_xact_id(),p_store,shift,p_sale,p_author,'SALE_CORRECTION');
 result:=public.pos_admin_correct_sale(p_sale,p_store,p_expected_version,p_items,p_totals,p_reason,actor.user_id,coalesce(nullif(actor.full_name,''),actor.user_id),p_terminal,p_client_key);
 SELECT to_jsonb(s) INTO STRICT after_row FROM public.sales s WHERE id=p_sale AND store_id=p_store;
 request_hash:=encode(sha256(convert_to(jsonb_build_array(p_sale,p_store,p_expected_version,p_items,p_totals,p_reason)::text,'UTF8')),'hex');
 INSERT INTO fin62_admin_preparation.receipts VALUES(gen_random_uuid(),'SALE_CORRECTION',p_sale,p_store,shift,fin62_live_preparation.organization(p_store,shift),p_terminal,p_author,p_client_key,request_hash,before_row,after_row,result,pg_current_xact_id(),nextval('fin62_evidence_preparation.helper_order'),now());
 DELETE FROM fin62_admin_preparation.context WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id();RETURN result;
END $$;
CREATE FUNCTION public.pos_live_financial_admin_correct_tender(p_author uuid,p_sale uuid,p_store text,p_method text,p_terminal text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE actor public.app_users%ROWTYPE;shift uuid;before_row jsonb;after_row jsonb;actual_branch text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_LIVE_SERVICE_REQUIRED';END IF;
 SELECT nullif(shift_id,'')::uuid,store_id INTO shift,actual_branch FROM public.sales WHERE id=p_sale AND lower(store_id)=lower(p_store);
 IF NOT FOUND THEN RAISE EXCEPTION 'The bill was not found in this branch. Synchronize and retry.';END IF;
 actor:=fin62_admin_preparation.authorize(p_author,actual_branch,p_terminal);
 IF shift IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended('pos-sync-shift:'||shift,0));END IF;
 SELECT to_jsonb(s) INTO STRICT before_row FROM public.sales s WHERE id=p_sale AND lower(store_id)=lower(p_store) FOR UPDATE;
 IF before_row->>'shift_id' IS DISTINCT FROM shift::text THEN RAISE EXCEPTION 'FIN62_ADMIN_SCOPE_CHANGED';END IF;
 INSERT INTO fin62_admin_preparation.context VALUES(pg_backend_pid(),pg_current_xact_id(),before_row->>'store_id',shift,p_sale,p_author,'TENDER_CORRECTION');
 PERFORM public.pos_admin_correct_tender(p_sale,p_store,p_method);
 SELECT to_jsonb(s) INTO STRICT after_row FROM public.sales s WHERE id=p_sale;
 INSERT INTO fin62_admin_preparation.receipts VALUES(gen_random_uuid(),'TENDER_CORRECTION',p_sale,before_row->>'store_id',shift,fin62_live_preparation.organization(before_row->>'store_id',shift),p_terminal,p_author,NULL,encode(sha256(convert_to(jsonb_build_array(p_sale,p_store,p_method)::text,'UTF8')),'hex'),before_row,after_row,'null',pg_current_xact_id(),nextval('fin62_evidence_preparation.helper_order'),now());
 DELETE FROM fin62_admin_preparation.context WHERE pid=pg_backend_pid() AND xid=pg_current_xact_id();
END $$;
CREATE FUNCTION public.pos_live_financial_admin_add_missed_bill(p_author uuid,p_entry jsonb,p_terminal text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE actor public.app_users%ROWTYPE;branch text:=btrim(p_entry->>'storeId');sale uuid:=(p_entry->>'clientKey')::uuid;result jsonb;after_row jsonb;operation uuid:=gen_random_uuid();previous_checkout_context text;
BEGIN
 actor:=fin62_admin_preparation.authorize(p_author,branch,p_terminal);
 PERFORM pg_advisory_xact_lock(hashtextextended('missed-bill:'||sale::text,0));
 IF EXISTS(SELECT 1 FROM public.missed_bill_entries WHERE id=sale) THEN RETURN public.pos_admin_add_missed_bill(p_entry,actor.user_id,p_terminal);END IF;
 IF EXISTS(SELECT 1 FROM public.sales WHERE id=sale) THEN RAISE EXCEPTION 'Historical entry identity is already recorded';END IF;
 INSERT INTO fin62_history_preparation.sale_birth_claims VALUES(sale,NULL,branch,p_terminal,NULL,operation);
 -- The original ALWAYS leaves sale/payment shift_id NULL. The optional old
 -- shift is attribution only and must never become a drawer posting.
 previous_checkout_context:=current_setting('pos.shift_checkout_context',true);
 PERFORM set_config('pos.shift_checkout_context',jsonb_build_object('branch',branch,'terminal',p_terminal,'mode','historical_admin')::text,true);
 BEGIN
  result:=public.pos_admin_add_missed_bill(p_entry,actor.user_id,p_terminal);
 EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('pos.shift_checkout_context',coalesce(previous_checkout_context,''),true);RAISE;
 END;
 PERFORM set_config('pos.shift_checkout_context',coalesce(previous_checkout_context,''),true);
 SELECT to_jsonb(s) INTO STRICT after_row FROM public.sales s WHERE id=sale AND store_id=branch;
 IF after_row->>'shift_id' IS NOT NULL THEN RAISE EXCEPTION 'FIN62_HISTORICAL_DRAWER_SCOPE_CHANGED';END IF;
 INSERT INTO fin62_admin_preparation.receipts VALUES(operation,'MISSED_BILL',sale,branch,NULL,NULL,p_terminal,p_author,sale,encode(sha256(convert_to(jsonb_build_array(p_entry,actor.user_id)::text,'UTF8')),'hex'),NULL,after_row,result,pg_current_xact_id(),nextval('fin62_evidence_preparation.helper_order'),now());RETURN result;
END $$;
CREATE FUNCTION fin62_admin_preparation.publication_edges(p_org text,p_branch text,p_shift uuid,p_sale uuid) RETURNS TABLE(before_fact jsonb,after_fact jsonb) LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT fin62_history_preparation.row_snapshot_fact(r.before_row),fin62_history_preparation.row_snapshot_fact(r.after_row) FROM fin62_admin_preparation.receipts r
 WHERE r.branch_id=p_branch AND r.shift_id=p_shift AND r.sale_id=p_sale AND (r.organization_id=p_org OR(r.organization_id IS NULL AND EXISTS(SELECT 1 FROM fin62_history_preparation.streams s WHERE s.organization_id=p_org AND s.branch_id=p_branch AND s.shift_id=p_shift)))
 AND fin62_history_preparation.row_snapshot_fact(r.before_row) IS DISTINCT FROM fin62_history_preparation.row_snapshot_fact(r.after_row);
$$;
CREATE FUNCTION fin62_admin_preparation.proves_publication(p_org text,p_branch text,p_shift uuid,p_sale uuid,p_before jsonb,p_after jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$
DECLARE graph jsonb;published boolean;nodes integer;bytes bigint;receipt record;source_rows integer:=0;raw_bytes bigint:=0;edge record;
BEGIN
 -- Bound source work BEFORE canonical payment parsing, UNION de-duplication or
 -- graph aggregation. TOAST size is not a memory bound: highly compressible
 -- payment JSON must be measured in its serialized (expanded) representation.
 FOR receipt IN
  SELECT e.raw_before before_raw,e.raw_after after_raw FROM fin62_history_preparation.sale_steps e
   WHERE e.organization_id=p_org AND e.branch_id=p_branch AND e.shift_id=p_shift AND e.sale_id=p_sale
  UNION ALL SELECT r.before_row,r.after_row FROM fin62_live_preparation.receipts r
   WHERE r.branch_id=p_branch AND r.shift_id=p_shift AND r.sale_id=p_sale
  UNION ALL SELECT r.before_row,r.after_row FROM fin62_admin_preparation.receipts r
   WHERE r.branch_id=p_branch AND r.shift_id=p_shift AND r.sale_id=p_sale
  LIMIT 4097
 LOOP
  source_rows:=source_rows+1;
  IF source_rows>4096 THEN RAISE EXCEPTION 'FIN62_PUBLICATION_HISTORY_REVIEW_REQUIRED';END IF;
  raw_bytes:=raw_bytes
   +coalesce(octet_length(coalesce(receipt.before_raw->'paymentsJson',receipt.before_raw->'payments')::text),0)
   +coalesce(octet_length(coalesce(receipt.after_raw->'paymentsJson',receipt.after_raw->'payments')::text),0)
   +coalesce(octet_length(coalesce(receipt.before_raw->'paymentType',receipt.before_raw->'payment_type')::text),0)
   +coalesce(octet_length(coalesce(receipt.after_raw->'paymentType',receipt.after_raw->'payment_type')::text),0)
   +coalesce(octet_length(coalesce(receipt.before_raw->'totalAmount',receipt.before_raw->'total_amount')::text),0)
   +coalesce(octet_length(coalesce(receipt.after_raw->'totalAmount',receipt.after_raw->'total_amount')::text),0)
   +coalesce(octet_length(coalesce(receipt.before_raw->'discountAmount',receipt.before_raw->'discount_amount')::text),0)
   +coalesce(octet_length(coalesce(receipt.after_raw->'discountAmount',receipt.after_raw->'discount_amount')::text),0);
  IF raw_bytes>8388608 THEN RAISE EXCEPTION 'FIN62_PUBLICATION_HISTORY_REVIEW_REQUIRED';END IF;
 END LOOP;
 -- A bounded canonical pass precedes jsonb_agg; no graph exists on denial.
 nodes:=0;bytes:=2;
 FOR edge IN
 WITH native_edges AS(
  SELECT fin62_history_preparation.snapshot_canonical_fact(e.before_fact) before_fact,fin62_history_preparation.snapshot_canonical_fact(e.after_fact) after_fact FROM fin62_history_preparation.sale_steps e JOIN fin62_history_preparation.nodes n ON n.operation_id=e.operation_id AND n.node_kind='MUTATION' AND n.organization_id=e.organization_id AND n.branch_id=e.branch_id AND n.terminal_id=e.terminal_id AND n.shift_id=e.shift_id
  WHERE e.organization_id=p_org AND e.branch_id=p_branch AND e.shift_id=p_shift AND e.sale_id=p_sale AND(e.action='REFUND' OR(e.action='SALE' AND EXISTS(SELECT 1 FROM fin62_history_preparation.sale_birth_claims c WHERE c.sale_id=p_sale AND c.operation_id=e.operation_id AND c.organization_id=p_org AND c.branch_id=p_branch AND c.shift_id=p_shift)))
 ),edges AS(
  SELECT * FROM native_edges UNION SELECT fin62_history_preparation.snapshot_canonical_fact(w.before_fact),fin62_history_preparation.snapshot_canonical_fact(w.after_fact) FROM fin62_live_preparation.publication_edges(p_org,p_branch,p_shift,p_sale) w
  UNION SELECT * FROM fin62_admin_preparation.publication_edges(p_org,p_branch,p_shift,p_sale)
 ),bounded AS(SELECT * FROM edges WHERE before_fact IS DISTINCT FROM after_fact LIMIT 1025)
 SELECT before_fact,after_fact FROM bounded
 LOOP
  nodes:=nodes+1;
  bytes:=bytes+2+octet_length(jsonb_build_object('before',edge.before_fact,'after',edge.after_fact)::text);
  IF nodes>1024 OR bytes>8388608 THEN RAISE EXCEPTION 'FIN62_PUBLICATION_HISTORY_REVIEW_REQUIRED';END IF;
 END LOOP;
 WITH native_edges AS(
  SELECT fin62_history_preparation.snapshot_canonical_fact(e.before_fact) before_fact,fin62_history_preparation.snapshot_canonical_fact(e.after_fact) after_fact FROM fin62_history_preparation.sale_steps e JOIN fin62_history_preparation.nodes n ON n.operation_id=e.operation_id AND n.node_kind='MUTATION' AND n.organization_id=e.organization_id AND n.branch_id=e.branch_id AND n.terminal_id=e.terminal_id AND n.shift_id=e.shift_id
  WHERE e.organization_id=p_org AND e.branch_id=p_branch AND e.shift_id=p_shift AND e.sale_id=p_sale AND(e.action='REFUND' OR(e.action='SALE' AND EXISTS(SELECT 1 FROM fin62_history_preparation.sale_birth_claims c WHERE c.sale_id=p_sale AND c.operation_id=e.operation_id AND c.organization_id=p_org AND c.branch_id=p_branch AND c.shift_id=p_shift)))
 ),edges AS(
  SELECT * FROM native_edges UNION SELECT fin62_history_preparation.snapshot_canonical_fact(w.before_fact),fin62_history_preparation.snapshot_canonical_fact(w.after_fact) FROM fin62_live_preparation.publication_edges(p_org,p_branch,p_shift,p_sale) w
  UNION SELECT * FROM fin62_admin_preparation.publication_edges(p_org,p_branch,p_shift,p_sale)
 ) SELECT coalesce(jsonb_agg(jsonb_build_object('before',before_fact,'after',after_fact)),'[]') INTO graph FROM edges WHERE before_fact IS DISTINCT FROM after_fact;
 SELECT EXISTS(SELECT 1 FROM fin62_history_preparation.publications p WHERE p.organization_id=p_org AND p.branch_id=p_branch AND p.shift_id=p_shift AND p.sale_id=p_sale AND fin62_history_preparation.snapshot_canonical_fact(p.financial_fact) IS NOT DISTINCT FROM p_after)
 OR EXISTS(SELECT 1 FROM fin62_live_preparation.publication_edges(p_org,p_branch,p_shift,p_sale) w WHERE fin62_history_preparation.snapshot_canonical_fact(w.after_fact) IS NOT DISTINCT FROM p_after)
 OR EXISTS(SELECT 1 FROM fin62_admin_preparation.publication_edges(p_org,p_branch,p_shift,p_sale) a WHERE a.after_fact IS NOT DISTINCT FROM p_after) INTO published;
 IF NOT published THEN RETURN false;END IF;
 RETURN(WITH RECURSIVE edges AS(SELECT nullif(e->'before','null'::jsonb) before_fact,nullif(e->'after','null'::jsonb) after_fact FROM jsonb_array_elements(graph) e),reachable(fact) AS(
  SELECT p_before UNION SELECT e.after_fact FROM reachable r JOIN edges e ON e.before_fact IS NOT DISTINCT FROM r.fact
 ) SELECT EXISTS(SELECT 1 FROM reachable WHERE fact IS NOT DISTINCT FROM p_after));
END $$;
-- Guarded source-only extension, preserving the original function/grants. Pins
-- are intentionally finalized AFTER all modules by the reviewed final bundle.
DO $proof$
DECLARE definition text;needle text:=' IF native_proof THEN RETURN true;END IF;';
BEGIN
 definition:=pg_get_functiondef('fin62_history_preparation.published_later_fact(text,text,uuid,uuid,jsonb,jsonb)'::regprocedure);
 IF (length(definition)-length(replace(definition,needle,'')))<>length(needle) THEN RAISE EXCEPTION 'FIN62_ADMIN_PROOF_SOURCE_UNEXPECTED';END IF;
 EXECUTE replace(definition,needle,needle||chr(10)||' IF fin62_admin_preparation.proves_publication(p_org,p_branch,p_shift,p_sale,p_before,p_after) THEN RETURN true;END IF;');
END $proof$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA fin62_admin_preparation FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.pos_live_financial_admin_correct_sale(uuid,uuid,text,integer,jsonb,jsonb,text,text,uuid),public.pos_live_financial_admin_correct_tender(uuid,uuid,text,text,text),public.pos_live_financial_admin_add_missed_bill(uuid,jsonb,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pos_live_financial_admin_correct_sale(uuid,uuid,text,integer,jsonb,jsonb,text,text,uuid),public.pos_live_financial_admin_correct_tender(uuid,uuid,text,text,text),public.pos_live_financial_admin_add_missed_bill(uuid,jsonb,text) TO service_role;

-- Source: scripts/preparation/shift-financial-rollout-capability.sql
-- Canonical source SHA256: BDB60AFFEBE577A4B885B54C04C6F21EBA8AE87EBEE55C05E4930FA54A6AC57D
-- PREPARATION ONLY. Empty rollout metadata is not approval or activation.
-- Owner-approved rollout rows require a separately reviewed maintenance plan,
-- including every registered till sharing the branch and existing pending work.
CREATE SCHEMA fin62_rollout_preparation;
REVOKE ALL ON SCHEMA fin62_rollout_preparation FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE fin62_rollout_preparation.approvals(
 organization_id text NOT NULL CHECK(length(organization_id) BETWEEN 1 AND 128),
 branch_id text NOT NULL CHECK(length(branch_id) BETWEEN 1 AND 128),
 terminal_id text NOT NULL CHECK(length(terminal_id) BETWEEN 1 AND 128),
 revision bigint NOT NULL CHECK(revision>0),rollout_id uuid NOT NULL,
 status text NOT NULL CHECK(status IN('approved','revoked')),
 approved_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(organization_id,branch_id,terminal_id,revision)
);
ALTER TABLE fin62_rollout_preparation.approvals ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_rollout_preparation.approvals FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON fin62_rollout_preparation.approvals
 FOR EACH ROW EXECUTE FUNCTION fin62_history_preparation.immutable();
-- Private predicate shared with the authorized settings-save trigger. It is
-- not an authentication API and no client/service role can execute it directly.
CREATE FUNCTION fin62_rollout_preparation.cohort_approved(p_org text,p_branch text,p_terminal text) RETURNS boolean
LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT EXISTS(
  SELECT 1 FROM fin62_rollout_preparation.approvals approval
  WHERE approval.organization_id=p_org AND approval.branch_id=p_branch AND approval.terminal_id=p_terminal AND approval.status='approved'
   AND approval.revision=(SELECT max(latest.revision) FROM fin62_rollout_preparation.approvals latest WHERE latest.organization_id=p_org AND latest.branch_id=p_branch AND latest.terminal_id=p_terminal)
   AND NOT EXISTS(
    SELECT 1 FROM public.terminal_tokens peer
    WHERE peer.location_id=p_branch AND peer.platform='pc' AND peer.status IN('active','used') AND peer.revoked_at IS NULL AND (peer.is_claimed IS TRUE OR peer.claimed_at IS NOT NULL)
     AND NOT EXISTS(
      SELECT 1 FROM fin62_rollout_preparation.approvals permitted
      WHERE permitted.organization_id=p_org AND permitted.branch_id=p_branch AND permitted.terminal_id=peer.id::text
       AND permitted.rollout_id=approval.rollout_id AND permitted.status='approved'
       AND permitted.revision=(SELECT max(latest.revision) FROM fin62_rollout_preparation.approvals latest WHERE latest.organization_id=p_org AND latest.branch_id=p_branch AND latest.terminal_id=peer.id::text)
     )
   )
 );
$$;
REVOKE ALL ON FUNCTION fin62_rollout_preparation.cohort_approved(text,text,text) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.pos_sync_financial_capability(p_org text,p_branch text,p_terminal text,p_shift uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE approval fin62_rollout_preparation.approvals%ROWTYPE;mode text:='disabled';shift_mode text;ready jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_CAPABILITY_SERVICE_REQUIRED';END IF;
 PERFORM public.pos_sync_validate_scope(p_org,p_branch,p_terminal);
 IF NOT EXISTS(SELECT 1 FROM public.terminal_tokens WHERE id::text=p_terminal AND location_id=p_branch AND platform='pc' AND status IN('active','used') AND revoked_at IS NULL AND (is_claimed IS TRUE OR claimed_at IS NOT NULL)) THEN RAISE EXCEPTION 'FIN62_CAPABILITY_TERMINAL_DENIED';END IF;
 SELECT * INTO approval FROM fin62_rollout_preparation.approvals WHERE organization_id=p_org AND branch_id=p_branch AND terminal_id=p_terminal ORDER BY revision DESC LIMIT 1;
 IF FOUND THEN mode:=CASE WHEN approval.status='approved' THEN 'required' ELSE 'blocked' END;END IF;
 IF mode='required' THEN
  -- A shared branch must not silently strand an older registered PC when the
  -- first upgraded PC protects a shift. Every active Operations PC must be in
  -- this same explicitly reviewed rollout; Management/mobile are not inferred
  -- to have local SQL financial-write capability.
  IF NOT fin62_rollout_preparation.cohort_approved(p_org,p_branch,p_terminal) THEN mode:='blocked';END IF;
 END IF;
 IF mode='required' THEN
  IF to_regprocedure('public.pos_live_financial_ready()') IS NULL THEN mode:='blocked';
  ELSE
   EXECUTE 'SELECT public.pos_live_financial_ready()' INTO ready;
   IF ready IS DISTINCT FROM '{"ready":true,"version":2}'::jsonb THEN mode:='blocked';END IF;
  END IF;
 END IF;
 IF p_shift IS NOT NULL THEN
  IF EXISTS(SELECT 1 FROM fin62_history_preparation.protected_shifts WHERE branch_id=p_branch AND shift_id=p_shift) THEN shift_mode:='required';
  ELSIF EXISTS(SELECT 1 FROM public.shifts WHERE id=p_shift AND store_id=p_branch) THEN shift_mode:='legacy';
  ELSE shift_mode:='unknown';END IF;
 END IF;
 RETURN jsonb_build_object('version',1,'mode',mode,'financialProtocol',2,'localSchema',26,'organizationId',p_org,'branchId',p_branch,'terminalId',p_terminal,'rolloutId',approval.rollout_id,'revision',coalesce(approval.revision::text,'0'),'shiftId',p_shift,'shiftMode',shift_mode);
END $$;
REVOKE ALL ON FUNCTION public.pos_sync_financial_capability(text,text,text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pos_sync_financial_capability(text,text,text,uuid) TO service_role;
CREATE FUNCTION fin62_rollout_preparation.assert_approved(p_org text,p_branch text,p_terminal text) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE capability jsonb;
BEGIN
 capability:=public.pos_sync_financial_capability(p_org,p_branch,p_terminal,NULL);
 IF capability->>'mode' IS DISTINCT FROM 'required' THEN RAISE EXCEPTION 'FIN62_ROLLOUT_NOT_APPROVED';END IF;
END $$;
REVOKE ALL ON FUNCTION fin62_rollout_preparation.assert_approved(text,text,text) FROM PUBLIC,anon,authenticated,service_role;

-- Source: scripts/preparation/shift-financial-final-readiness.sql
-- Canonical source SHA256: CD2EB62C446C7FEBC99C1FA9F41012A56CABAB74CD8D4DEA2BB0ECFDAC14467A
-- PREPARATION ONLY. Install after all protected aliases; no live execution.
-- pg_get_functiondef formats referenced types according to search_path. Capture
-- under the same fixed path used by the verifier, otherwise valid definitions
-- with composite return types are incorrectly classified as changed.
SET LOCAL search_path=pg_catalog;
CREATE TABLE fin62_live_preparation.contract_pins(signature text PRIMARY KEY,digest text NOT NULL,owner_oid oid NOT NULL,security_definer boolean NOT NULL,acl text,configuration text[]);
ALTER TABLE fin62_live_preparation.contract_pins ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fin62_live_preparation.contract_pins FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON fin62_live_preparation.contract_pins FOR EACH ROW EXECUTE FUNCTION fin62_history_preparation.immutable();
-- Owner-only inspection also works during a migration without an HTTP JWT.
-- Public callers still pass the unchanged service-role check below.
CREATE FUNCTION fin62_live_preparation.installation_ready() RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$
DECLARE ready boolean;
BEGIN
 SELECT count(*)=49 AND bool_and(r.oid IS NOT NULL AND p.digest=md5(pg_get_functiondef(r.oid)) AND p.owner_oid=r.proowner AND p.security_definer=r.prosecdef AND p.acl IS NOT DISTINCT FROM r.proacl::text AND p.configuration IS NOT DISTINCT FROM r.proconfig) INTO ready
 FROM fin62_live_preparation.contract_pins p LEFT JOIN pg_proc r ON r.oid=to_regprocedure(p.signature);
 ready:=coalesce(ready,false) AND NOT EXISTS(
  SELECT 1 FROM unnest(ARRAY['fin62_history_preparation.live_context','fin62_history_preparation.graph_context','fin62_history_preparation.protected_shifts','fin62_history_preparation.sale_birth_claims','fin62_web_preparation.actions','fin62_web_preparation.active_actions','fin62_live_preparation.receipts','fin62_live_preparation.contract_pins','fin62_admin_preparation.context','fin62_admin_preparation.receipts','fin62_rollout_preparation.approvals']) name
  LEFT JOIN pg_class c ON c.oid=to_regclass(name) WHERE c.oid IS NULL OR NOT c.relrowsecurity OR c.relowner<>'postgres'::regrole OR has_table_privilege('authenticated',c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER') OR has_table_privilege('service_role',c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER'));
 ready:=ready AND EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='fin62_rollout_preparation.approvals'::regclass AND tgname='immutable' AND tgenabled='O' AND tgfoid='fin62_history_preparation.immutable()'::regprocedure);
 RETURN coalesce(ready,false);
END $$;
REVOKE ALL ON FUNCTION fin62_live_preparation.installation_ready() FROM PUBLIC,anon,authenticated,service_role;
DO $ready_install$
DECLARE signature text;routine oid;
BEGIN
 FOREACH signature IN ARRAY ARRAY[
 'fin62_live_preparation.installation_ready()','public.pos_sale_commit(jsonb,jsonb,jsonb,jsonb,jsonb,text)','public.sale_refund(uuid,jsonb,text,text,text)',
 'public.shift_close_start(uuid,text,text)','public.shift_variance_approve(uuid,text)',
 'public.shift_cash_count_submit(uuid,numeric,numeric,numeric,text,text)','public.shift_recount_submit(uuid,numeric,text,numeric,numeric,text)',
 'public.shift_reconcile_now(uuid,uuid,numeric,numeric,numeric)','public.pos_admin_correct_closed_shift(uuid,numeric,numeric,numeric,text,text,text,text,text)',
 'fin62_web_preparation.capture_expected(uuid,uuid,text)','fin62_web_preparation.begin_graph(uuid,text)',
 'fin62_history_preparation.block_unintegrated_write()','fin62_history_preparation.guard_shift_graph()',
 'public.pos_live_financial_sale(uuid,text,text,jsonb,jsonb,jsonb,jsonb,jsonb,text)','public.pos_live_financial_refund(uuid,text,text,uuid,jsonb,text,text)',
 'fin62_preparation.validate_financial_math_text(text)',
 'fin62_live_preparation.authorize(uuid,text,text,text)','fin62_live_preparation.organization(text,uuid)',
 'fin62_live_preparation.proves_later_publication(text,text,uuid,uuid,jsonb,jsonb)','fin62_live_preparation.publication_edges(text,text,uuid,uuid)',
 'fin62_history_preparation.live_row_allowed(text,jsonb,jsonb)',
 'fin62_web_preparation.end_action(uuid,uuid)','fin62_web_preparation.action_expected(uuid,uuid)',
 'fin62_web_preparation.end_graph(uuid,text,boolean)','fin62_web_preparation.validate_counted(numeric,numeric,numeric)',
 'public.pos_live_financial_admin_correct_sale(uuid,uuid,text,integer,jsonb,jsonb,text,text,uuid)','public.pos_live_financial_admin_correct_tender(uuid,uuid,text,text,text)','public.pos_live_financial_admin_add_missed_bill(uuid,jsonb,text)','fin62_admin_preparation.authorize(uuid,text,text)','fin62_admin_preparation.row_allowed(text,jsonb,jsonb)','fin62_admin_preparation.publication_edges(text,text,uuid,uuid)','fin62_admin_preparation.proves_publication(text,text,uuid,uuid,jsonb,jsonb)','fin62_history_preparation.published_later_fact(text,text,uuid,uuid,jsonb,jsonb)','fin62_history_preparation.ensure_stream(text,text,text,uuid,jsonb)','public.pos_sync_financial_capability(text,text,text,uuid)','fin62_rollout_preparation.assert_approved(text,text,text)','fin62_history_preparation.immutable()','public.pos_sync_register_financial_event(text,text,text,text,jsonb)','public.pos_sync_register_financial_boundary(text,text,text,text,jsonb,jsonb)','public.pos_sync_register_financial_open(uuid,text,text,text,uuid,text,text,jsonb,text,jsonb)','public.pos_sync_push_financial_business_aggregate(uuid,text,text,text,jsonb)','public.pos_sync_push_financial_shift_intent(uuid,text,text,text,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb)','public.pos_sync_read_financial_basis(text,text,text,uuid)','public.pos_sync_register_financial_observation(text,text,text,text)','fin62_history_preparation.current_author(text,text,jsonb,text,uuid,text)','fin62_rollout_preparation.cohort_approved(text,text,text)','fin62_cloud_preparation.fact_payment(jsonb)','fin62_cloud_preparation.financial_fact(jsonb)','fin62_cloud_preparation.snapshot_financial_fact(jsonb)'] LOOP
  routine:=to_regprocedure(signature);IF routine IS NULL THEN RAISE EXCEPTION 'FIN62_LIVE_DEPENDENCY_MISSING: %',signature;END IF;
  INSERT INTO fin62_live_preparation.contract_pins SELECT signature,md5(pg_get_functiondef(oid)),proowner,prosecdef,proacl::text,proconfig FROM pg_proc WHERE oid=routine;
 END LOOP;
 IF strpos(pg_get_functiondef('public.shift_close_start(uuid,text,text)'::regprocedure),'fin62_web_preparation.begin_graph')=0 OR strpos(pg_get_functiondef('public.shift_variance_approve(uuid,text)'::regprocedure),'fin62_web_preparation.begin_graph')=0 THEN RAISE EXCEPTION 'FIN62_LIVE_WEB_CONTEXT_MISSING';END IF;
END $ready_install$;
CREATE OR REPLACE FUNCTION public.pos_live_financial_ready() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'FIN62_LIVE_SERVICE_REQUIRED';END IF;
 RETURN jsonb_build_object('ready',fin62_live_preparation.installation_ready(),'version',2);
END $$;
REVOKE ALL ON FUNCTION public.pos_live_financial_ready() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pos_live_financial_ready() TO service_role;

DO $financial_postflight$
BEGIN
 IF NOT fin62_live_preparation.installation_ready()
  OR EXISTS(SELECT 1 FROM fin62_rollout_preparation.approvals)
  OR EXISTS(SELECT 1 FROM fin62_history_preparation.protected_shifts) THEN
  RAISE EXCEPTION 'FIN62_FINAL_INSTALLATION_NOT_READY';
 END IF;
END $financial_postflight$;
NOTIFY pgrst,'reload schema';
COMMIT;
